function Test-BlobWinget { return [bool](Get-Command winget.exe -ErrorAction SilentlyContinue) }

# Text of "winget list" (the background data thread collects it once).
function Get-BlobWingetListText {
    $pre = Get-BlobPrefetch 'WingetList'
    if ($pre) { return [string]$pre }
    if (-not (Test-BlobWinget)) { return '' }
    try { return ((& winget.exe list --accept-source-agreements --disable-interactivity 2>$null) | Out-String) } catch { return '' }
}

function Get-BlobWingetInstalledIds {
    param([string]$ListText)
    $found = @{}
    foreach ($a in $Blob.WingetCatalog) {
        if ($ListText -match ('(?im)(^|\s)' + [regex]::Escape($a.Id) + '(\s|$)')) { $found[$a.Id] = $true }
    }
    return $found
}

# winget result codes worth explaining (hex as shown in winget docs).
$Blob.WingetCodes = @{
    0 = 'installed'; -1978335135 = 'already installed'; -1978335189 = 'no matching installer for this PC'
    -1978335212 = 'package not found in the winget source'; -1978334967 = 'installer reported a restart is needed'
}

# Runs one winget command; -Pump keeps the window responsive. Returns @{ Code; Text; Last }.
function Invoke-BlobWingetCommand {
    param([string]$Arguments, [scriptblock]$Pump = { Start-Sleep -Milliseconds 200 })
    $log = Join-Path ([IO.Path]::GetTempPath()) ("blob-winget-{0}.log" -f ([guid]::NewGuid().ToString('N').Substring(0, 8)))
    $p = Start-Process -FilePath 'winget.exe' -ArgumentList $Arguments -PassThru -NoNewWindow -RedirectStandardOutput $log -ErrorAction Stop
    while (-not $p.HasExited) { & $Pump }
    $text = ''
    try { $text = Get-Content -LiteralPath $log -Raw -ErrorAction Stop } catch { }
    Remove-Item -LiteralPath $log -Force -ErrorAction SilentlyContinue
    $last = @(($text -split "`r?`n") | ForEach-Object { ($_ -replace '[^\x20-\x7E]', '').Trim() } | Where-Object { $_ -and $_ -notmatch '^[-\\|/ ]+$' }) | Select-Object -Last 1
    return @{ Code = $p.ExitCode; Text = $text; Last = $last }
}

function Install-BlobWingetApp {
    param($App, [scriptblock]$Log = { param($m) }, [scriptblock]$Pump = { Start-Sleep -Milliseconds 200 })
    if ($Blob.DryRun) { & $Log "{Magenta} DRY  {White}$($App.Name) {Gray}would be installed ($($App.Id))"; return }
    & $Log "{Gray}Installing $($App.Name) ($($App.Id))..."
    try { $r = Invoke-BlobWingetCommand "install --id `"$($App.Id)`" --exact --source winget --accept-package-agreements --accept-source-agreements --disable-interactivity" $Pump }
    catch { & $Log "{Red} FAIL {White}$($App.Name) {Gray}($($_.Exception.Message -replace '[{}]', ''))"; return }
    $what = if ($Blob.WingetCodes.ContainsKey($r.Code)) { $Blob.WingetCodes[$r.Code] } else { "winget exit code $($r.Code): $($r.Last)" }
    if ($r.Code -in @(0, -1978335135, -1978334967)) {
        & $Log "{White} OK   {White}$($App.Name) {Gray}$what"
        if ($r.Code -eq 0) { Add-BlobActionRecord -Source 'install' -Label "Installed $($App.Name) with winget" -Target $App.Id -Detail 'Remove it from the Apps page if you no longer want it.' }
    } else { & $Log "{Red} FAIL {White}$($App.Name) {Gray}$($what -replace '[{}]', '')" }
}

function Update-BlobWingetAll {
    param([scriptblock]$Log = { param($m) }, [scriptblock]$Pump = { Start-Sleep -Milliseconds 200 })
    if ($Blob.DryRun) { & $Log '{Magenta} DRY  {White}winget upgrade --all would run'; return }
    & $Log '{Gray}Updating every app winget can update (this can take a while)...'
    $r = Invoke-BlobWingetCommand 'upgrade --all --accept-package-agreements --accept-source-agreements --disable-interactivity' $Pump
    $count = ([regex]::Matches($r.Text, '(?i)Successfully installed')).Count
    & $Log ("{White} OK   {White}Update finished {Gray}({0} package(s) updated, exit code {1})" -f $count, $r.Code)
    Add-BlobActionRecord -Source 'install' -Label 'Updated apps with winget' -Target 'winget upgrade --all' -Detail "$count package(s) updated"
}
#endregion

#region ---- Prefetch.ps1 ----
# ============================================================================
#  BLOB OPTIMIZER - Prefetch.ps1
#  Collects slow system information (WMI/CIM, network, disks, services,
#  cleanup sizes) on a background thread inside this PowerShell process while
#  the window is already usable. Pages use the snapshot for their first build
#  and query live data again after any change. The thread is disposed when
#  the window closes - nothing keeps running afterwards. Read-only.
# ============================================================================

# Three groups run in parallel; the slowest group sets the total time.
$Blob.PrefetchGroups = @(
    @('Adapters', 'IPConfig', 'Profiles', 'Dns'),
    @('Firewall', 'Defender', 'PhysicalDisks', 'Video', 'BIOS', 'Board', 'Memory'),
    @('OS', 'CPU', 'CS', 'LogicalDisks', 'Services', 'CleanupSizes', 'StoreApps'),
    @('WingetList')
)

$Blob.PrefetchScript = {
    param($CleanupTargets, $IsAdmin, $Names, $StoreFn, $StoreProtected)
    $r = @{}
    function Try-Get([string]$Name, [scriptblock]$Block) {
        if ($Names -notcontains $Name) { return }
        try { $r[$Name] = & $Block } catch { $r[$Name] = $null }
    }

    Try-Get 'OS'           { Get-CimInstance Win32_OperatingSystem -ErrorAction Stop }
    Try-Get 'CPU'          { @(Get-CimInstance Win32_Processor -ErrorAction Stop) }
    Try-Get 'CS'           { Get-CimInstance Win32_ComputerSystem -ErrorAction Stop }
    Try-Get 'Memory'       { @(Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop) }
    Try-Get 'Video'        { @(Get-CimInstance Win32_VideoController -ErrorAction Stop) }
    Try-Get 'BIOS'         { Get-CimInstance Win32_BIOS -ErrorAction Stop }
    Try-Get 'Board'        { Get-CimInstance Win32_BaseBoard -ErrorAction Stop }
    Try-Get 'LogicalDisks' { @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction Stop) }
    Try-Get 'Services'     { @(Get-CimInstance Win32_Service -ErrorAction Stop) }
    Try-Get 'PhysicalDisks' {
        @(Get-PhysicalDisk -ErrorAction Stop | ForEach-Object {
                [pscustomobject]@{ DeviceId = $_.DeviceId; FriendlyName = $_.FriendlyName; MediaType = [string]$_.MediaType
                                   Size = $_.Size; HealthStatus = [string]$_.HealthStatus } })
    }
    Try-Get 'Defender' { Get-MpComputerStatus -ErrorAction Stop | Select-Object RealTimeProtectionEnabled, AntivirusSignatureLastUpdated }
    Try-Get 'Firewall' { @(Get-NetFirewallProfile -ErrorAction Stop | ForEach-Object { [pscustomobject]@{ Name = [string]$_.Name; Enabled = [bool]$_.Enabled } }) }
    Try-Get 'Adapters' {
        @(Get-NetAdapter -ErrorAction Stop | ForEach-Object {
                [pscustomobject]@{ Name = $_.Name; InterfaceDescription = $_.InterfaceDescription; ifIndex = $_.ifIndex
                                   Status = [string]$_.Status; LinkSpeed = [string]$_.LinkSpeed; MacAddress = $_.MacAddress
                                   InterfaceGuid = [string]$_.InterfaceGuid } })
    }
    Try-Get 'IPConfig' {
        # Get-NetIPAddress + Get-NetRoute: the same data as Get-NetIPConfiguration, much faster.
        $h = @{}
        $addr = @(Get-NetIPAddress -ErrorAction Stop | Where-Object { $_.AddressState -eq 'Preferred' })
        $gw = @(Get-NetRoute -DestinationPrefix '0.0.0.0/0' -ErrorAction SilentlyContinue)
        foreach ($idx in @($addr | ForEach-Object { [int]$_.InterfaceIndex } | Select-Object -Unique)) {
            $h[$idx] = [pscustomobject]@{
                IPv4    = (@($addr | Where-Object { [int]$_.InterfaceIndex -eq $idx -and [string]$_.AddressFamily -eq 'IPv4' } | ForEach-Object { "$($_.IPAddress)/$($_.PrefixLength)" }) -join ', ')
                IPv6    = (@($addr | Where-Object { [int]$_.InterfaceIndex -eq $idx -and [string]$_.AddressFamily -eq 'IPv6' } | ForEach-Object { $_.IPAddress }) -join ', ')
                Gateway = (@($gw | Where-Object { [int]$_.InterfaceIndex -eq $idx } | ForEach-Object { $_.NextHop }) -join ', ') }
        }
        $h
    }
    Try-Get 'Profiles' {
        $h = @{}
        foreach ($p in @(Get-NetConnectionProfile -ErrorAction Stop)) { $h[[int]$p.InterfaceIndex] = [pscustomobject]@{ Name = $p.Name; NetworkCategory = [string]$p.NetworkCategory } }
        $h
    }
    Try-Get 'Dns' {
        $h = @{}
        foreach ($d in @(Get-DnsClientServerAddress -AddressFamily IPv4 -ErrorAction Stop)) { $h[[int]$d.InterfaceIndex] = @($d.ServerAddresses) }
        $h
    }
    if ($Names -contains 'StoreApps' -and $StoreFn) {
        . ([scriptblock]::Create("function Get-BlobStoreAppsLive {`n$StoreFn`n}"))
        Try-Get 'StoreApps' { @(Get-BlobStoreAppsLive -Protected $StoreProtected) }
    }
    Try-Get 'WingetList' {
        if (Get-Command winget.exe -ErrorAction SilentlyContinue) { ((& winget.exe list --accept-source-agreements --disable-interactivity 2>$null) | Out-String) } else { $null }
    }
    Try-Get 'CleanupSizes' {
        $sizes = @{}
        foreach ($t in $CleanupTargets) {
            if ($t.Admin -and -not $IsAdmin) { $sizes[$t.Id] = @{ Bytes = 0; Count = 0; Note = 'admin required' }; continue }
            if ($t.Special -eq 'Recycle') {
                try {
                    $shell = New-Object -ComObject Shell.Application
                    $items = @($shell.Namespace(10).Items()); $bytes = 0
                    foreach ($i in $items) { $bytes += [double]$i.Size }
                    $sizes[$t.Id] = @{ Bytes = $bytes; Count = $items.Count; Note = '' }
                } catch { $sizes[$t.Id] = @{ Bytes = 0; Count = 0; Note = 'unavailable' } }
                continue
            }
            $cutoff = (Get-Date).AddHours(-1 * [double]$t.MinAgeHours)
            $bytes = 0; $count = 0
            foreach ($p in $t.Paths) {
                if (-not $p -or -not (Test-Path -LiteralPath $p)) { continue }
                $params = @{ LiteralPath = $p; File = $true; Force = $true; ErrorAction = 'SilentlyContinue' }
                if ($t.Filter) { $params.Filter = $t.Filter } else { $params.Recurse = $true }
                foreach ($f in (Get-ChildItem @params)) { if ($f.LastWriteTime -lt $cutoff) { $bytes += $f.Length; $count++ } }
            }
            $sizes[$t.Id] = @{ Bytes = [double]$bytes; Count = $count; Note = '' }
        }
        $sizes
    }
    return $r
}

# Starts the background collection (three parallel threads). Returns immediately.
function Start-BlobPrefetch {
    $Blob.Prefetch = $null; $Blob.PrefetchValid = $false; $Blob.PrefetchState = 'Running'
    $jobs = New-Object System.Collections.ArrayList
    try {
        foreach ($names in $Blob.PrefetchGroups) {
            $rs = [runspacefactory]::CreateRunspace()
            $rs.ApartmentState = 'STA'   # Shell.Application (Recycle Bin size) prefers STA
            $rs.Open()
            $ps = [powershell]::Create()
            $ps.Runspace = $rs
            [void]$ps.AddScript($Blob.PrefetchScript.ToString()).AddArgument($Blob.CleanupTargets).AddArgument($Blob.IsAdmin).AddArgument([string[]]$names).AddArgument(${function:Get-BlobStoreAppsLive}.ToString()).AddArgument([string[]]$Blob.StoreProtected)
            [void]$jobs.Add(@{ PS = $ps; RS = $rs; Handle = $ps.BeginInvoke() })
        }
        $Blob.PrefetchJob = @{ Jobs = $jobs; Started = Get-Date }
    } catch {
        $Blob.PrefetchJob = @{ Jobs = $jobs; Started = Get-Date }
        Stop-BlobPrefetch
        $Blob.PrefetchState = 'Failed'
        Write-BlobLog "Background data collection could not start: $($_.Exception.Message)" 'WARN'
    }
}

# Collects the results when all threads finished. Returns $true once nothing is running.
function Receive-BlobPrefetch {
    $job = $Blob.PrefetchJob
    if (-not $job) { return $true }
    foreach ($j in $job.Jobs) { if (-not $j.Handle.IsCompleted) { return $false } }
    $merged = @{}
    $ok = $false
    foreach ($j in $job.Jobs) {
        try {
            $out = $j.PS.EndInvoke($j.Handle)
            if ($out.Count -gt 0 -and $out[0] -is [hashtable]) { foreach ($k in $out[0].Keys) { $merged[$k] = $out[0][$k] }; $ok = $true }
        } catch { Write-BlobLog "Background data collection part failed: $($_.Exception.Message)" 'WARN' }
    }
    if ($ok) {
        $Blob.Prefetch = $merged; $Blob.PrefetchValid = $true; $Blob.PrefetchState = 'Ready'
        Write-BlobLog ("Background data collected in {0:N1}s" -f ((Get-Date) - $job.Started).TotalSeconds)
    } else { $Blob.PrefetchState = 'Failed' }
    Stop-BlobPrefetch
    return $true
}

function Stop-BlobPrefetch {
    $job = $Blob.PrefetchJob
    if (-not $job) { return }
    foreach ($j in @($job.Jobs)) {
        try { if (-not $j.Handle.IsCompleted) { $j.PS.Stop() } } catch { }
        try { $j.PS.Dispose() } catch { }
        try { $j.RS.Dispose() } catch { }
    }
    $Blob.PrefetchJob = $null
    if ($Blob.PrefetchState -eq 'Running') { $Blob.PrefetchState = 'Stopped' }
}

# Returns prefetched data while the snapshot is still valid, otherwise $null
# (callers then query live). Any change invalidates the snapshot.
function Get-BlobPrefetch {
    param([string]$Name)
    # Return nothing (not $null) when unavailable, so @(Get-BlobPrefetch ...) is empty
    # and callers fall back to a live query.
    if (-not $Blob.PrefetchValid -or -not $Blob.Prefetch) { return }
    $v = $Blob.Prefetch[$Name]
    if ($null -eq $v) { return }
    return $v
}
#endregion

#region ---- Dashboard.ps1 ----
# ============================================================================
#  BLOB OPTIMIZER - Dashboard.ps1
#  Logo, system summary, main menu grid and the System Info page.
# ============================================================================

$Blob.Logo = @(
    '#####   ##        #####   ##### ',
    '##  ##  ##       ##   ##  ##  ##',
    '#####   ##       ##   ##  ##### ',
    '##  ##  ##       ##   ##  ##  ##',
    '#####   #######   #####   ##### '
)

$Blob.MainMenu = @(
    @{ Key = '1'; Label = 'Performance'; Run = { Show-BlobPerformance }; Info = 'Responsiveness, background apps, visual effects and resource information.' }
    @{ Key = '2'; Label = 'Gaming'; Run = { Show-BlobGaming }; Info = 'Game Mode, Game DVR, input and GPU scheduling options. No FPS promises.' }
    @{ Key = '3'; Label = 'Tweaks'; Run = { Show-BlobTweaks }; Info = 'File Explorer, taskbar, Start menu and Windows behaviour settings.' }
    @{ Key = '4'; Label = 'Privacy'; Run = { Show-BlobPrivacy }; Info = 'Advertising, suggestions, diagnostic data and activity history.' }
    @{ Key = '5'; Label = 'Services'; Run = { Show-BlobServices }; Info = 'Review services with explanations. Critical services are protected.' }
    @{ Key = '6'; Label = 'Startup'; Run = { Show-BlobStartup }; Info = 'Disable or re-enable programs that launch at sign-in.' }
    @{ Key = '7'; Label = 'Cleanup'; Run = { Show-BlobCleanup }; Info = 'Temporary files, caches and Recycle Bin with a size preview.' }
    @{ Key = '8'; Label = 'Network'; Run = { Show-BlobNetwork }; Info = 'Network information, diagnostics, DNS and optional resets.' }
    @{ Key = '9'; Label = 'Power'; Run = { Show-BlobPower }; Info = 'Power plans, display / sleep timeouts and hibernation.' }
    @{ Key = '10'; Label = 'Restore'; Run = { Show-BlobRestore }; Info = 'Change history, undo, registry snapshots and config export/import.' }
    @{ Key = '11'; Label = 'System Info'; Run = { Show-BlobSystemInfo }; Info = 'Detailed hardware and Windows information (read-only).' }
    @{ Key = 'P'; Label = 'Presets'; Run = { Show-BlobPresets }; Info = 'MINIMAL, STANDARD or ADVANCED - every change previewed before applying.' }
    @{ Key = 'V'; Label = 'Privacy center'; Run = { Show-BlobTweakSection -Section 'PrivacyCenter' -Crumb 'Privacy center' -Intro @('{White}Privacy center', "{Gray}$(@(Get-BlobPrivacyItems).Count) settings in $($Blob.PrivacyGroups.Count) sections. Enter shows the full explanation, recommendation and privacy impact.") }; Info = 'All privacy settings, explained, with a recommendation for each.' }
    @{ Key = 'T'; Label = 'External Tools'; Run = { Show-BlobExternalTools }; Info = 'Launch Chris Titus Tech WinUtil or O&O ShutUp10++ (third-party, asks first).' }
    @{ Key = '0'; Label = 'Exit'; Run = $null; Info = 'Close BLOB OPTIMIZER. Nothing keeps running in the background.' }
)

function Get-BlobSystemSummary {
    $s = @{ OS = 'Windows'; CPU = 'Unknown'; RAM = 'Unknown'; GPU = 'Unknown'; Host = $env:COMPUTERNAME; Uptime = '' }
    try {
        $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop
        $cv = Get-ItemProperty -LiteralPath 'HKLM:\SOFTWARE\Microsoft\Windows NT\CurrentVersion' -ErrorAction SilentlyContinue
        $caption = $os.Caption -replace '^Microsoft\s+', ''
        if ([int]$os.BuildNumber -ge 22000) { $caption = $caption -replace 'Windows 10', 'Windows 11' }
        $s.OS = "$caption $($cv.DisplayVersion) (build $($os.BuildNumber).$($cv.UBR))"
        $up = (Get-Date) - $os.LastBootUpTime
        $s.Uptime = '{0}d {1}h {2}m' -f $up.Days, $up.Hours, $up.Minutes
    } catch { }
    try {
        $cpu = Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1
        $s.CPU = ($cpu.Name -replace '\s+', ' ').Trim() + " ($($cpu.NumberOfCores)C/$($cpu.NumberOfLogicalProcessors)T)"
    } catch { }
    try {
        $cs = Get-CimInstance Win32_ComputerSystem -ErrorAction Stop
        $s.RAM = '{0:N1} GB' -f ($cs.TotalPhysicalMemory / 1GB)
        $s.Model = "$($cs.Manufacturer) $($cs.Model)"
    } catch { }
    try { $s.GPU = (@(Get-CimInstance Win32_VideoController -ErrorAction Stop | ForEach-Object { $_.Name } | Select-Object -Unique) -join ', ') } catch { }
    return $s
}

function Show-BlobDashboard {
    $sel = 0
    $cols = 2
    $pendingDigit = $null
    while ($true) {
        $plan = (Get-BlobActivePowerPlan).Name
        $si = $Blob.SysInfo
        $L = Write-BlobFrame -Crumb 'Dashboard' -Footer (Format-BlobFooter @("$($Blob.Ch.Up)$($Blob.Ch.Down)$([char]0x2190)$([char]0x2192)|Navigate", 'Enter|Open', '1-11 / P / V / T|Jump', 'Esc|Exit'))
        $menuRows = [Math]::Ceiling($Blob.MainMenu.Count / $cols)
        $needFull = $Blob.Logo.Count + 2 + 5 + 2 + $menuRows + 2
        $showLogo = $L.BodyH -ge $needFull
        $row = $L.BodyTop
        $lines = New-Object System.Collections.ArrayList
        if ($showLogo) {
            $pad = [Math]::Max(0, [int](($L.Inner - $Blob.Logo[0].Length) / 2))
            foreach ($logoLine in $Blob.Logo) { [void]$lines.Add('{Cyan}' + (' ' * $pad) + ($logoLine -replace '#', $Blob.Ch.Block)) }
            $sub = "O P T I M I Z E R   {DarkGray}v$($Blob.Version)"
            [void]$lines.Add(' ' * [Math]::Max(0, [int](($L.Inner - (Get-BlobPlainText $sub).Length) / 2)) + '{White}' + $sub)
        } else {
            [void]$lines.Add("{Cyan}BLOB OPTIMIZER {DarkGray}v$($Blob.Version)")
        }
        [void]$lines.Add('')
        $half = [int]($L.Inner / 2)
        $kv = { param($k, $v, $c = 'White') ("{DarkGray}$($k.PadRight(8)){$c}$v") }
        $pairs = @(
            @((& $kv 'OS' $si.OS), (& $kv 'HOST' $si.Host)),
            @((& $kv 'CPU' $si.CPU), (& $kv 'RAM' $si.RAM)),
            @((& $kv 'GPU' $si.GPU), (& $kv 'POWER' $plan)),
            @((& $kv 'ADMIN' $(if ($Blob.IsAdmin) { 'Administrator' } else { 'Standard user (read-only features)' }) $(if ($Blob.IsAdmin) { 'Green' } else { 'Yellow' })),
              (& $kv 'STATUS' $(if ($Blob.DryRun) { 'DRY RUN - no changes' } else { 'READY' }) $(if ($Blob.DryRun) { 'Magenta' } else { 'Green' })))
        )
        [void]$lines.Add("{DarkCyan}$($Blob.Ch.S)$($Blob.Ch.S) {Cyan}SYSTEM {DarkCyan}" + ($Blob.Ch.S * ($L.Inner - 10)))
        foreach ($p in $pairs) {
            $left = $p[0]; $plainLen = (Get-BlobPlainText $left).Length
            if ($plainLen -gt $half - 2) { $left = '{DarkGray}' + (Get-BlobPlainText $left).Substring(0, 8) + '{White}' + (Get-BlobPlainText $left).Substring(8, $half - 13) + '...'; $plainLen = $half - 2 }
            [void]$lines.Add($left + (' ' * ($half - $plainLen)) + $p[1])
        }
        [void]$lines.Add('')
        [void]$lines.Add("{DarkCyan}$($Blob.Ch.S)$($Blob.Ch.S) {Cyan}MENU {DarkCyan}" + ($Blob.Ch.S * ($L.Inner - 8)))
        foreach ($textLine in $lines) { if ($row -lt $L.BodyTop + $L.BodyH) { Write-BlobRow $L $row $textLine; $row++ } }

        $cellW = [int](($L.Inner - 4) / $cols)
        for ($r = 0; $r -lt $menuRows; $r++) {
            if ($row -ge $L.BodyTop + $L.BodyH - 2) { break }
            $L2 = $L
            Write-BlobRow $L2 $row ''
            for ($c = 0; $c -lt $cols; $c++) {
                $i = $r + $c * $menuRows
                if ($i -ge $Blob.MainMenu.Count) { continue }
                $m = $Blob.MainMenu[$i]
                $text = (" [{0}] {1}" -f $m.Key, $m.Label).PadRight($cellW - 2)
                $x = $L.L + 4 + $c * $cellW
                if ($i -eq $sel) { Write-BlobAt $x $row $text 'Black' 'Cyan' }
                else {
                    Write-BlobAt $x $row (" [{0}]" -f $m.Key) 'Cyan'
                    Write-BlobAt ($x + (" [{0}]" -f $m.Key).Length) $row (" $($m.Label)") $(if ($m.Key -eq '0') { 'Gray' } else { 'White' })
                }
            }
            $row++
        }
        while ($row -lt $L.BodyTop + $L.BodyH - 1) { Write-BlobRow $L $row ''; $row++ }
        Write-BlobRow $L $row ("{Gray}" + $Blob.MainMenu[$sel].Info)

        $k = Read-BlobKey
        if (-not $k) { continue }
        $count = $Blob.MainMenu.Count
        $r0 = $sel % $menuRows; $c0 = [Math]::Floor($sel / $menuRows)
        $choose = $null
        switch ($k.Key) {
            'UpArrow'    { $sel = ($sel - 1 + $count) % $count }
            'DownArrow'  { $sel = ($sel + 1) % $count }
            'LeftArrow'  { if ($c0 -gt 0) { $sel = $sel - $menuRows } }
            'RightArrow' { if ($sel + $menuRows -lt $count) { $sel = $sel + $menuRows } }
            'Tab'        { $sel = ($sel + $menuRows) % $count; if ($sel -ge $count) { $sel = $r0 } }
            'Home'       { $sel = 0 }
            'End'        { $sel = $count - 1 }
            'Enter'      { $choose = $sel }
            'Escape'     { $choose = $count - 1 }
        }
        $ch = ([string]$k.KeyChar).ToUpperInvariant()
        if ($ch -match '^[0-9PTV]$') {
            $key = $ch
            if ($ch -eq '1') {
                # Wait briefly for a second digit so 10 and 11 can be typed.
                $deadline = (Get-Date).AddMilliseconds(450)
                while ((Get-Date) -lt $deadline -and -not [Console]::KeyAvailable) { Start-Sleep -Milliseconds 25 }
                if ([Console]::KeyAvailable) {
                    $k2 = [Console]::ReadKey($true)
                    if ($k2.KeyChar -in @([char]'0', [char]'1')) { $key = '1' + $k2.KeyChar }
                }
            }
            for ($i = 0; $i -lt $count; $i++) { if ($Blob.MainMenu[$i].Key -eq $key) { $sel = $i; $choose = $i } }
        }
        if ($null -ne $choose) {
            $m = $Blob.MainMenu[$choose]
            if (-not $m.Run) { return }
            try { & $m.Run }
            catch {
                if ($_.Exception.Message -eq 'BLOB_WINDOW_TOO_SMALL') { continue }
                Write-BlobLog "Unhandled error in $($m.Label): $($_.Exception.Message) $($_.InvocationInfo.PositionMessage)" 'ERROR'
                Show-BlobNotice -Crumb $m.Label -Kind Error -Title 'Something went wrong' -Lines @(
                    "{Gray}$($_.Exception.Message -replace '[{}]', '')", '',
                    '{Gray}No further changes were made. Details were written to the session log.')
            }
        }
    }
}

function Get-BlobSystemInfoLines {
    $lines = New-Object System.Collections.ArrayList
    $add = { param($t) [void]$lines.Add($t) }
    $kv = { param($k, $v) [void]$lines.Add("{Gray}$($k.PadRight(22)){White}$($v -replace '[{}]', '')") }
    & $add '{Cyan}Windows'
    try {
        $os = Get-BlobPrefetch 'OS'
        if (-not $os) { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop }
        & $kv 'Edition' $Blob.SysInfo.OS
        & $kv 'Architecture' $os.OSArchitecture
        & $kv 'Installed' $os.InstallDate.ToString('yyyy-MM-dd')
        & $kv 'Last boot' "$($os.LastBootUpTime.ToString('yyyy-MM-dd HH:mm'))  (uptime $($Blob.SysInfo.Uptime))"
        & $kv 'Computer name' $env:COMPUTERNAME
        & $kv 'Locale' (Get-Culture).Name
    } catch { & $add "{Red}$($_.Exception.Message)" }
    & $add ''; & $add '{Cyan}Hardware'
    try {
        & $kv 'Model' $Blob.SysInfo.Model
        $cpu = @(Get-BlobPrefetch 'CPU') | Select-Object -First 1
        if (-not $cpu) { $cpu = Get-CimInstance Win32_Processor -ErrorAction Stop | Select-Object -First 1 }
        & $kv 'Processor' ($cpu.Name -replace '\s+', ' ').Trim()
        & $kv 'Cores / threads' "$($cpu.NumberOfCores) / $($cpu.NumberOfLogicalProcessors)  @ $($cpu.MaxClockSpeed) MHz"
        $mods = @(Get-BlobPrefetch 'Memory')
        if ($mods.Count -eq 0) { $mods = @(Get-CimInstance Win32_PhysicalMemory -ErrorAction Stop) }
        & $kv 'Memory' ("{0} in {1} module(s), {2} MT/s" -f $Blob.SysInfo.RAM, $mods.Count, ($mods | Select-Object -First 1).Speed)
        $vid = @(Get-BlobPrefetch 'Video')
        if ($vid.Count -eq 0) { $vid = @(Get-CimInstance Win32_VideoController -ErrorAction Stop) }
        foreach ($g in $vid) { & $kv 'Graphics' "$($g.Name)  (driver $($g.DriverVersion))" }
        $bios = Get-BlobPrefetch 'BIOS'
        if (-not $bios) { $bios = Get-CimInstance Win32_BIOS -ErrorAction Stop }
        & $kv 'BIOS' "$($bios.Manufacturer) $($bios.SMBIOSBIOSVersion)"
        $bb = Get-BlobPrefetch 'Board'
        if (-not $bb) { $bb = Get-CimInstance Win32_BaseBoard -ErrorAction Stop }
        & $kv 'Motherboard' "$($bb.Manufacturer) $($bb.Product)"
    } catch { }
    try {
        $pds = @(Get-BlobPrefetch 'PhysicalDisks')
        if ($pds.Count -eq 0) { $pds = @(Get-PhysicalDisk -ErrorAction Stop) }
        foreach ($pd in $pds) { & $kv 'Disk' ("{0}  {1}  {2}  health {3}" -f $pd.FriendlyName, $pd.MediaType, (Format-BlobSize $pd.Size), $pd.HealthStatus) } } catch { }
    & $add ''; & $add '{Cyan}Security status (read-only)'
    try {
        $mp = Get-BlobPrefetch 'Defender'
        if (-not $mp) { $mp = Get-MpComputerStatus -ErrorAction Stop }
        & $kv 'Defender real-time' $(if ($mp.RealTimeProtectionEnabled) { 'On' } else { 'Off' })
        & $kv 'Defender signatures' $mp.AntivirusSignatureLastUpdated
    } catch { & $kv 'Defender' 'status unavailable (third-party antivirus or no permission)' }
    try {
        $fwp = @(Get-BlobPrefetch 'Firewall')
        if ($fwp.Count -eq 0) { $fwp = @(Get-NetFirewallProfile -ErrorAction Stop) }
        $fw = @($fwp | ForEach-Object { "$($_.Name): $(if ($_.Enabled) { 'On' } else { 'Off' })" }) -join ', '
        & $kv 'Firewall' $fw
    } catch { }
    & $add ''; & $add '{Cyan}BLOB OPTIMIZER'
    & $kv 'Version' $Blob.Version
    & $kv 'PowerShell' "$($PSVersionTable.PSVersion) ($($PSVersionTable.PSEdition))"
    & $kv 'Administrator' $(if ($Blob.IsAdmin) { 'yes' } else { 'no' })
    & $kv 'Dry run' $(if ($Blob.DryRun) { 'yes' } else { 'no' })
    & $kv 'Data folder' $Blob.DataRoot
    & $kv 'Recorded changes' $Blob.Changes.Count
    return $lines.ToArray()
}

function Show-BlobSystemInfo {
    Start-BlobWork 'System Info'
    Write-BlobWork '{Gray}Collecting system information...'
    $lines = Get-BlobSystemInfoLines
    $null = Show-BlobText -Crumb 'System Info' -Lines $lines
}
#endregion

#region ---- GuiXaml.ps1 ----
# ============================================================================
#  BLOB OPTIMIZER - GuiXaml.ps1
#  WPF markup for the window interface. WPF ships with Windows / .NET, so
#  nothing is downloaded or installed. Pure ASCII: glyphs use XML entities.
#
#  Design: an engineering spec sheet. Warm paper, near-black ink, one signal
#  colour (international orange) reserved for things that need attention.
#  Bahnschrift (built into Windows) for structure and numbers, Segoe UI for
#  reading, a monospace face only for technical values. Hairline rules
#  instead of boxes, almost no rounding, no shadows, no gradients.
# ============================================================================

$Blob.GuiTheme = @'
<ResourceDictionary xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
                    xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml">
  <SolidColorBrush x:Key="Paper" Color="#EFECE6"/>
  <SolidColorBrush x:Key="Surface" Color="#F7F5F1"/>
  <SolidColorBrush x:Key="Ink" Color="#141414"/>
  <SolidColorBrush x:Key="Ink2" Color="#57544E"/>
  <SolidColorBrush x:Key="Ink3" Color="#8A867E"/>
  <SolidColorBrush x:Key="Rule" Color="#D6D2CA"/>
  <SolidColorBrush x:Key="Signal" Color="#FF4F00"/>
  <SolidColorBrush x:Key="SignalSoft" Color="#FBE4D7"/>
  <FontFamily x:Key="Display">Bahnschrift, Segoe UI</FontFamily>
  <FontFamily x:Key="Mono">Cascadia Mono, Consolas</FontFamily>

  <Style TargetType="TextBlock">
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="TextWrapping" Value="Wrap"/>
  </Style>

  <!-- Secondary button: hairline ink outline -->
  <Style TargetType="Button">
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="BorderBrush" Value="{StaticResource Ink}"/>
    <Setter Property="Padding" Value="14,6"/>
    <Setter Property="Margin" Value="0,0,8,0"/>
    <Setter Property="FontFamily" Value="{StaticResource Display}"/>
    <Setter Property="FontSize" Value="13.5"/>
    <Setter Property="Cursor" Value="Hand"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                  BorderThickness="1" CornerRadius="2" Padding="{TemplateBinding Padding}">
            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#E4E0D8"/></Trigger>
            <Trigger Property="IsPressed" Value="True"><Setter TargetName="Bd" Property="Background" Value="#D6D2CA"/></Trigger>
            <Trigger Property="IsEnabled" Value="False"><Setter TargetName="Bd" Property="Opacity" Value="0.35"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <!-- Primary: solid ink -->
  <Style x:Key="AccentButton" TargetType="Button" BasedOn="{StaticResource {x:Type Button}}">
    <Setter Property="Background" Value="{StaticResource Ink}"/>
    <Setter Property="Foreground" Value="{StaticResource Paper}"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{TemplateBinding BorderBrush}"
                  BorderThickness="1" CornerRadius="2" Padding="{TemplateBinding Padding}">
            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#333230"/></Trigger>
            <Trigger Property="IsEnabled" Value="False"><Setter TargetName="Bd" Property="Opacity" Value="0.35"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style x:Key="DangerButton" TargetType="Button" BasedOn="{StaticResource {x:Type Button}}">
    <Setter Property="Foreground" Value="#B83A00"/>
    <Setter Property="BorderBrush" Value="#B83A00"/>
  </Style>
  <!-- Text-only button used for filters and links -->
  <Style x:Key="ChipButton" TargetType="Button">
    <Setter Property="Foreground" Value="{StaticResource Ink2}"/>
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="BorderBrush" Value="Transparent"/>
    <Setter Property="FontFamily" Value="{StaticResource Display}"/>
    <Setter Property="FontSize" Value="13.5"/>
    <Setter Property="Cursor" Value="Hand"/>
    <Setter Property="Margin" Value="0,0,18,6"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Bd" Background="Transparent" BorderBrush="{TemplateBinding BorderBrush}" BorderThickness="0,0,0,2" Padding="0,2,0,3">
            <ContentPresenter VerticalAlignment="Center"/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter Property="Foreground" Value="{StaticResource Ink}"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <!-- Full-width list row used for "start here" actions -->
  <Style x:Key="RowButton" TargetType="Button">
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="Cursor" Value="Hand"/>
    <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Bd" Background="{TemplateBinding Background}" BorderBrush="{StaticResource Rule}" BorderThickness="0,0,0,1" Padding="2,13">
            <ContentPresenter HorizontalAlignment="Stretch"/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#E8E4DC"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <!-- Table-of-contents navigation item; BorderBrush paints the marker bar -->
  <Style x:Key="NavButton" TargetType="Button">
    <Setter Property="Foreground" Value="{StaticResource Ink2}"/>
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="BorderBrush" Value="Transparent"/>
    <Setter Property="FontFamily" Value="{StaticResource Display}"/>
    <Setter Property="FontSize" Value="15"/>
    <Setter Property="Cursor" Value="Hand"/>
    <Setter Property="HorizontalContentAlignment" Value="Stretch"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Grid Background="Transparent">
            <Grid.ColumnDefinitions><ColumnDefinition Width="3"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Border Grid.Column="0" Background="{TemplateBinding BorderBrush}"/>
            <Border x:Name="Bd" Grid.Column="1" Background="{TemplateBinding Background}" Padding="17,7,12,7">
              <ContentPresenter/>
            </Border>
          </Grid>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#E4E0D8"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style x:Key="TabButton" TargetType="Button" BasedOn="{StaticResource NavButton}"/>
  <Style x:Key="CaptionButton" TargetType="Button">
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="Width" Value="46"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Bd" Background="{TemplateBinding Background}">
            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#DEDAD2"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style x:Key="CloseButton" TargetType="Button" BasedOn="{StaticResource CaptionButton}">
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="Button">
          <Border x:Name="Bd" Background="{TemplateBinding Background}">
            <ContentPresenter HorizontalAlignment="Center" VerticalAlignment="Center"/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#141414"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style x:Key="IconButton" TargetType="Button" BasedOn="{StaticResource ChipButton}"/>

  <!-- On/off switch: rectangular, ink when on -->
  <Style x:Key="Switch" TargetType="CheckBox">
    <Setter Property="Cursor" Value="Hand"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="CheckBox">
          <Border x:Name="Track" Width="38" Height="20" Background="Transparent" BorderBrush="{StaticResource Ink}" BorderThickness="1.5" CornerRadius="2">
            <Border x:Name="Thumb" Width="14" Height="12" Background="{StaticResource Ink3}" HorizontalAlignment="Left" Margin="2,0" CornerRadius="1"/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsChecked" Value="True">
              <Setter TargetName="Track" Property="Background" Value="{StaticResource Ink}"/>
              <Setter TargetName="Thumb" Property="Background" Value="{StaticResource Paper}"/>
              <Setter TargetName="Thumb" Property="HorizontalAlignment" Value="Right"/>
            </Trigger>
            <Trigger Property="IsEnabled" Value="False"><Setter TargetName="Track" Property="Opacity" Value="0.3"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <Style TargetType="CheckBox">
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="Cursor" Value="Hand"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="CheckBox">
          <Grid Background="Transparent">
            <Grid.ColumnDefinitions><ColumnDefinition Width="Auto"/><ColumnDefinition Width="*"/></Grid.ColumnDefinitions>
            <Border x:Name="Box" Width="16" Height="16" Background="Transparent" BorderBrush="{StaticResource Ink}"
                    BorderThickness="1.5" VerticalAlignment="Top" Margin="0,2,10,0">
              <Path x:Name="Mark" Data="M2.5,7.5 L6,11 L12.5,3.5" Stroke="{StaticResource Paper}" StrokeThickness="2" Visibility="Collapsed"/>
            </Border>
            <ContentPresenter Grid.Column="1" VerticalAlignment="Top"/>
          </Grid>
          <ControlTemplate.Triggers>
            <Trigger Property="IsChecked" Value="True">
              <Setter TargetName="Box" Property="Background" Value="{StaticResource Ink}"/>
              <Setter TargetName="Mark" Property="Visibility" Value="Visible"/>
            </Trigger>
            <Trigger Property="IsEnabled" Value="False"><Setter Property="Opacity" Value="0.4"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <Style TargetType="ScrollBar">
    <Setter Property="Width" Value="8"/>
    <Setter Property="MinWidth" Value="8"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ScrollBar">
          <Track x:Name="PART_Track" IsDirectionReversed="True">
            <Track.Thumb><Thumb><Thumb.Template><ControlTemplate TargetType="Thumb">
              <Border Background="#BDB8AE" Margin="2,0"/>
            </ControlTemplate></Thumb.Template></Thumb></Track.Thumb>
          </Track>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
    <Style.Triggers>
      <Trigger Property="Orientation" Value="Horizontal">
        <Setter Property="Width" Value="Auto"/>
        <Setter Property="Height" Value="8"/>
        <Setter Property="MinHeight" Value="8"/>
        <Setter Property="Template">
          <Setter.Value>
            <ControlTemplate TargetType="ScrollBar">
              <Track x:Name="PART_Track">
                <Track.Thumb><Thumb><Thumb.Template><ControlTemplate TargetType="Thumb">
                  <Border Background="#BDB8AE" Margin="0,2"/>
                </ControlTemplate></Thumb.Template></Thumb></Track.Thumb>
              </Track>
            </ControlTemplate>
          </Setter.Value>
        </Setter>
      </Trigger>
    </Style.Triggers>
  </Style>

  <!-- Inputs: underline only -->
  <Style TargetType="TextBox">
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="BorderBrush" Value="{StaticResource Ink}"/>
    <Setter Property="BorderThickness" Value="0,0,0,1.5"/>
    <Setter Property="CaretBrush" Value="{StaticResource Ink}"/>
    <Setter Property="SelectionBrush" Value="{StaticResource Signal}"/>
    <Setter Property="Padding" Value="2,5"/>
    <Setter Property="FontSize" Value="13.5"/>
  </Style>

  <Style TargetType="ComboBox">
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="FontSize" Value="13.5"/>
    <Setter Property="MinWidth" Value="160"/>
    <Setter Property="Height" Value="32"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ComboBox">
          <Grid>
            <ToggleButton Focusable="False" ClickMode="Press"
                          IsChecked="{Binding IsDropDownOpen, Mode=TwoWay, RelativeSource={RelativeSource TemplatedParent}}">
              <ToggleButton.Template>
                <ControlTemplate TargetType="ToggleButton">
                  <Border x:Name="Bd" Background="Transparent" BorderBrush="#141414" BorderThickness="0,0,0,1.5">
                    <Path HorizontalAlignment="Right" VerticalAlignment="Center" Margin="0,0,6,0" Data="M0,0 L4.5,4.5 L9,0"
                          Stroke="#141414" StrokeThickness="1.5"/>
                  </Border>
                  <ControlTemplate.Triggers>
                    <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#E4E0D8"/></Trigger>
                  </ControlTemplate.Triggers>
                </ControlTemplate>
              </ToggleButton.Template>
            </ToggleButton>
            <ContentPresenter IsHitTestVisible="False" Margin="2,0,24,0" VerticalAlignment="Center"
                              Content="{TemplateBinding SelectionBoxItem}" ContentTemplate="{TemplateBinding SelectionBoxItemTemplate}"/>
            <Popup IsOpen="{TemplateBinding IsDropDownOpen}" Placement="Bottom" AllowsTransparency="False" Focusable="False">
              <Border Background="#F7F5F1" BorderBrush="#141414" BorderThickness="1" MinWidth="{TemplateBinding ActualWidth}" MaxHeight="320">
                <ScrollViewer><ItemsPresenter/></ScrollViewer>
              </Border>
            </Popup>
          </Grid>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
  <Style TargetType="ComboBoxItem">
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ComboBoxItem">
          <Border x:Name="Bd" Padding="10,6" Background="Transparent"><ContentPresenter/></Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsHighlighted" Value="True"><Setter TargetName="Bd" Property="Background" Value="#E4E0D8"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <Style TargetType="ListBox">
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="BorderThickness" Value="0"/>
  </Style>
  <Style TargetType="ListBoxItem">
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ListBoxItem">
          <Border x:Name="Bd" Background="Transparent" BorderBrush="{StaticResource Rule}" BorderThickness="0,0,0,1" Padding="{TemplateBinding Padding}">
            <ContentPresenter/>
          </Border>
          <ControlTemplate.Triggers>
            <Trigger Property="IsMouseOver" Value="True"><Setter TargetName="Bd" Property="Background" Value="#E8E4DC"/></Trigger>
            <Trigger Property="IsSelected" Value="True"><Setter TargetName="Bd" Property="Background" Value="{StaticResource SignalSoft}"/></Trigger>
          </ControlTemplate.Triggers>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <!-- Tables: hairline rows, small-caps header, soft signal selection -->
  <Style TargetType="DataGrid">
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="BorderBrush" Value="{StaticResource Ink}"/>
    <Setter Property="BorderThickness" Value="0,1.5,0,1"/>
    <Setter Property="RowBackground" Value="Transparent"/>
    <Setter Property="AlternatingRowBackground" Value="Transparent"/>
    <Setter Property="GridLinesVisibility" Value="Horizontal"/>
    <Setter Property="HorizontalGridLinesBrush" Value="{StaticResource Rule}"/>
    <Setter Property="HeadersVisibility" Value="Column"/>
    <Setter Property="AutoGenerateColumns" Value="False"/>
    <Setter Property="IsReadOnly" Value="True"/>
    <Setter Property="CanUserAddRows" Value="False"/>
    <Setter Property="SelectionMode" Value="Extended"/>
    <Setter Property="SelectionUnit" Value="FullRow"/>
    <Setter Property="RowHeight" Value="32"/>
    <Setter Property="FontSize" Value="13"/>
  </Style>
  <Style TargetType="DataGridColumnHeader">
    <Setter Property="Background" Value="Transparent"/>
    <Setter Property="Foreground" Value="{StaticResource Ink3}"/>
    <Setter Property="FontFamily" Value="{StaticResource Display}"/>
    <Setter Property="FontSize" Value="12"/>
    <Setter Property="Padding" Value="8,8"/>
    <Setter Property="BorderBrush" Value="{StaticResource Rule}"/>
    <Setter Property="BorderThickness" Value="0,0,0,1"/>
  </Style>
  <Style TargetType="DataGridCell">
    <Setter Property="BorderThickness" Value="0"/>
    <Setter Property="Padding" Value="8,0"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="DataGridCell">
          <Border Background="{TemplateBinding Background}" Padding="{TemplateBinding Padding}">
            <ContentPresenter VerticalAlignment="Center"/>
          </Border>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
    <Style.Triggers>
      <Trigger Property="IsSelected" Value="True">
        <Setter Property="Background" Value="{StaticResource SignalSoft}"/>
        <Setter Property="Foreground" Value="{StaticResource Ink}"/>
      </Trigger>
    </Style.Triggers>
  </Style>

  <Style TargetType="ProgressBar">
    <Setter Property="Height" Value="4"/>
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ProgressBar">
          <Grid>
            <Border x:Name="PART_Track" Background="{StaticResource Rule}"/>
            <Border x:Name="PART_Indicator" HorizontalAlignment="Left" Background="{TemplateBinding Foreground}"/>
          </Grid>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>

  <Style TargetType="ToolTip">
    <Setter Property="Foreground" Value="{StaticResource Ink}"/>
    <Setter Property="HasDropShadow" Value="False"/>
    <Setter Property="Template">
      <Setter.Value>
        <ControlTemplate TargetType="ToolTip">
          <Border Background="#F7F5F1" BorderBrush="#141414" BorderThickness="1" Padding="14,12" MaxWidth="520">
            <ContentPresenter/>
          </Border>
        </ControlTemplate>
      </Setter.Value>
    </Setter>
  </Style>
</ResourceDictionary>
'@

$Blob.GuiXaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Title="BLOB OPTIMIZER" Width="1280" Height="840" MinWidth="1000" MinHeight="640"
        WindowStartupLocation="CenterScreen" Background="#EFECE6" WindowStyle="None" ResizeMode="CanResize"
        FontFamily="Segoe UI" FontSize="13" UseLayoutRounding="True" TextOptions.TextFormattingMode="Display">
  <WindowChrome.WindowChrome>
    <WindowChrome CaptionHeight="48" ResizeBorderThickness="6" GlassFrameThickness="0" CornerRadius="0"/>
  </WindowChrome.WindowChrome>
  <!--THEME-->
  <Border x:Name="RootBorder" BorderBrush="#141414" BorderThickness="1">
    <Grid>
      <Grid.RowDefinitions>
        <RowDefinition Height="48"/>
        <RowDefinition Height="*"/>
        <RowDefinition Height="Auto"/>
        <RowDefinition Height="26"/>
      </Grid.RowDefinitions>

      <!-- Title bar -->
      <Border Grid.Row="0" BorderBrush="#141414" BorderThickness="0,0,0,1.5">
        <Grid>
          <StackPanel Orientation="Horizontal" VerticalAlignment="Center" Margin="22,0,0,0">
            <TextBlock Text="BLOB" FontFamily="{StaticResource Display}" FontWeight="Bold" FontSize="21" VerticalAlignment="Center"/>
            <Border Width="7" Height="7" Background="#FF4F00" Margin="3,9,0,0" VerticalAlignment="Center"/>
            <TextBlock Text="optimizer" FontFamily="{StaticResource Display}" FontSize="15" Foreground="#57544E" Margin="10,3,0,0" VerticalAlignment="Center"/>
            <TextBlock x:Name="TitleVersion" FontFamily="{StaticResource Mono}" FontSize="11" Foreground="#8A867E" Margin="12,5,0,0" VerticalAlignment="Center"/>
          </StackPanel>
          <StackPanel Orientation="Horizontal" HorizontalAlignment="Right">
            <Button x:Name="BtnSearch" Style="{StaticResource ChipButton}" WindowChrome.IsHitTestVisibleInChrome="True" Margin="0,0,22,0" VerticalAlignment="Center" ToolTip="Search everything (Ctrl+K)">
              <TextBlock><Run Text="Search"/><Run Text="  Ctrl+K" Foreground="#8A867E" FontFamily="Cascadia Mono, Consolas" FontSize="11"/></TextBlock>
            </Button>
            <Border x:Name="DryRunBadge" BorderBrush="#B83A00" BorderThickness="1" Padding="7,1" Margin="0,0,10,0" VerticalAlignment="Center" Visibility="Collapsed">
              <TextBlock Text="DRY RUN" FontFamily="{StaticResource Display}" FontSize="11.5" Foreground="#B83A00"/>
            </Border>
            <Border x:Name="AdminBadge" BorderThickness="1" Padding="7,1" Margin="0,0,18,0" VerticalAlignment="Center">
              <TextBlock x:Name="AdminBadgeText" FontFamily="{StaticResource Display}" FontSize="11.5"/>
            </Border>
            <Button x:Name="BtnMin" Style="{StaticResource CaptionButton}" WindowChrome.IsHitTestVisibleInChrome="True" ToolTip="Minimize">
              <Path Data="M0,0.5 L10,0.5" Stroke="#141414" StrokeThickness="1.2"/>
            </Button>
            <Button x:Name="BtnMax" Style="{StaticResource CaptionButton}" WindowChrome.IsHitTestVisibleInChrome="True" ToolTip="Maximize">
              <Path Data="M0.5,0.5 H9.5 V9.5 H0.5 Z" Stroke="#141414" StrokeThickness="1.2"/>
            </Button>
            <Button x:Name="BtnClose" Style="{StaticResource CloseButton}" WindowChrome.IsHitTestVisibleInChrome="True" ToolTip="Close">
              <Path x:Name="CloseGlyph" Data="M0,0 L10,10 M10,0 L0,10" Stroke="#141414" StrokeThickness="1.2"/>
            </Button>
          </StackPanel>
        </Grid>
      </Border>

      <!-- Body -->
      <Grid Grid.Row="1">
        <Grid.ColumnDefinitions>
          <ColumnDefinition Width="220"/>
          <ColumnDefinition Width="*"/>
        </Grid.ColumnDefinitions>

        <!-- Table of contents -->
        <Border Grid.Column="0" BorderBrush="#141414" BorderThickness="0,0,1.5,0">
          <DockPanel>
            <TextBlock DockPanel.Dock="Top" Text="CONTENTS" FontFamily="{StaticResource Display}" FontSize="11.5" Foreground="#8A867E" Margin="22,22,0,10"/>
            <StackPanel DockPanel.Dock="Bottom" Margin="22,10,16,18">
              <TextBlock Text="Portable. Nothing installed." FontSize="11.5" Foreground="#8A867E"/>
              <TextBlock Text="Every change can be undone." FontSize="11.5" Foreground="#8A867E" Margin="0,2,0,0"/>
            </StackPanel>
            <ScrollViewer VerticalScrollBarVisibility="Auto">
              <StackPanel x:Name="NavPanel"/>
            </ScrollViewer>
          </DockPanel>
        </Border>

        <!-- Page -->
        <Grid Grid.Column="1">
          <Grid.RowDefinitions>
            <RowDefinition Height="Auto"/>
            <RowDefinition Height="*"/>
            <RowDefinition Height="Auto"/>
          </Grid.RowDefinitions>
          <Border Grid.Row="0" Margin="40,26,36,0" BorderBrush="#141414" BorderThickness="0,0,0,2" Padding="0,0,0,14">
            <DockPanel>
              <StackPanel x:Name="PageActions" DockPanel.Dock="Right" Orientation="Horizontal" VerticalAlignment="Bottom"/>
              <StackPanel>
                <StackPanel Orientation="Horizontal">
                  <TextBlock x:Name="PageNumber" FontFamily="{StaticResource Display}" FontSize="32" Foreground="#B8B3A9" Margin="0,0,14,0"/>
                  <TextBlock x:Name="PageTitle" FontFamily="{StaticResource Display}" FontSize="32" FontWeight="SemiBold"/>
                </StackPanel>
                <TextBlock x:Name="PageSubtitle" FontSize="13.5" Foreground="#57544E" Margin="0,4,0,0" MaxWidth="620" HorizontalAlignment="Left"/>
              </StackPanel>
            </DockPanel>
          </Border>
          <ScrollViewer x:Name="PageScroll" Grid.Row="1" VerticalScrollBarVisibility="Auto" Padding="40,20,36,28">
            <ContentControl x:Name="PageHost"/>
          </ScrollViewer>
          <!-- Pending changes bar (shown only when choices are waiting) -->
          <Border x:Name="PendingBar" Grid.Row="2" Background="#141414" Padding="40,12,36,12" Visibility="Collapsed">
            <DockPanel>
              <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
                <Button x:Name="PendingDiscard" Content="Discard" Foreground="#EFECE6" BorderBrush="#57544E" Padding="16,6"/>
                <Button x:Name="PendingApply" Content="Review and apply" Background="#FF4F00" BorderBrush="#FF4F00" Foreground="#141414" Padding="18,6" Margin="0"/>
              </StackPanel>
              <Border Width="9" Height="9" Background="#FF4F00" VerticalAlignment="Center" Margin="0,0,12,0"/>
              <TextBlock x:Name="PendingText" FontFamily="{StaticResource Display}" FontSize="15" Foreground="#EFECE6" VerticalAlignment="Center"/>
            </DockPanel>
          </Border>
        </Grid>
      </Grid>

      <!-- Log drawer -->
      <Border Grid.Row="2" BorderBrush="#141414" BorderThickness="0,1.5,0,0">
        <DockPanel>
          <DockPanel DockPanel.Dock="Top" Margin="22,5,12,5">
            <Button x:Name="BtnToggleLog" DockPanel.Dock="Right" Content="Show log" Style="{StaticResource ChipButton}" Margin="12,0,0,0"/>
            <Button x:Name="BtnClearLog" DockPanel.Dock="Right" Content="Clear" Style="{StaticResource ChipButton}" Margin="12,0,0,0"/>
            <TextBlock Text="LOG" FontFamily="{StaticResource Display}" FontSize="11.5" Foreground="#8A867E" VerticalAlignment="Center" Margin="0,0,14,0"/>
            <TextBlock x:Name="LogLast" FontFamily="{StaticResource Mono}" FontSize="11.5" Foreground="#57544E" VerticalAlignment="Center" TextTrimming="CharacterEllipsis" TextWrapping="NoWrap"/>
          </DockPanel>
          <ScrollViewer x:Name="LogScroll" Height="130" VerticalScrollBarVisibility="Auto" Padding="22,2,12,8" Visibility="Collapsed">
            <StackPanel x:Name="LogPanel"/>
          </ScrollViewer>
        </DockPanel>
      </Border>

      <!-- Status line -->
      <Border Grid.Row="3" BorderBrush="#D6D2CA" BorderThickness="0,1,0,0">
        <DockPanel Margin="22,0">
          <TextBlock x:Name="StatusRight" DockPanel.Dock="Right" FontFamily="{StaticResource Mono}" Foreground="#8A867E" FontSize="11" VerticalAlignment="Center"/>
          <TextBlock x:Name="StatusText" FontFamily="{StaticResource Mono}" Foreground="#57544E" FontSize="11" VerticalAlignment="Center" Text="Ready"/>
        </DockPanel>
      </Border>
    </Grid>
  </Border>
</Window>
'@

$Blob.GuiDialogXaml = @'
<Window xmlns="http://schemas.microsoft.com/winfx/2006/xaml/presentation"
        xmlns:x="http://schemas.microsoft.com/winfx/2006/xaml"
        Width="740" Height="580" MinWidth="520" MinHeight="300" WindowStyle="None" ResizeMode="CanResize"
        WindowStartupLocation="CenterOwner" Background="#F7F5F1" ShowInTaskbar="False" FontFamily="Segoe UI" FontSize="13">
  <WindowChrome.WindowChrome>
    <WindowChrome CaptionHeight="64" ResizeBorderThickness="6" GlassFrameThickness="0" CornerRadius="0"/>
  </WindowChrome.WindowChrome>
  <!--THEME-->
  <Border x:Name="DlgBorder" BorderBrush="#141414" BorderThickness="1.5">
    <DockPanel>
      <Border x:Name="DlgStripe" DockPanel.Dock="Top" Height="5" Background="#141414"/>
      <Border DockPanel.Dock="Top" Padding="28,18,28,14" BorderBrush="#D6D2CA" BorderThickness="0,0,0,1">
        <StackPanel>
          <TextBlock x:Name="DlgTitle" FontFamily="{StaticResource Display}" FontSize="22" FontWeight="SemiBold"/>
          <TextBlock x:Name="DlgSub" FontSize="13" Foreground="#57544E" Margin="0,4,0,0"/>
        </StackPanel>
      </Border>
      <Border DockPanel.Dock="Bottom" Padding="28,14" BorderBrush="#141414" BorderThickness="0,1.5,0,0">
        <DockPanel>
          <StackPanel DockPanel.Dock="Right" Orientation="Horizontal">
            <Button x:Name="DlgCancel" Content="Cancel" MinWidth="96"/>
            <Button x:Name="DlgOk" Content="Confirm" MinWidth="130" Margin="0" Style="{StaticResource AccentButton}"/>
          </StackPanel>
          <CheckBox x:Name="DlgCheck" VerticalAlignment="Center" Margin="0,0,16,0" Visibility="Collapsed">
            <TextBlock x:Name="DlgCheckText" FontSize="13"/>
          </CheckBox>
        </DockPanel>
      </Border>
      <ScrollViewer VerticalScrollBarVisibility="Auto" Padding="28,16">
        <StackPanel x:Name="DlgBody"/>
      </ScrollViewer>
    </DockPanel>
  </Border>
</Window>
'@
#endregion

#region ---- Gui.ps1 ----
# ============================================================================
#  BLOB OPTIMIZER - Gui.ps1
#  Window interface shell: window creation, navigation, dialogs, activity log
#  and small control factories. Uses WPF, which is part of Windows - nothing
#  is installed. All work goes through the same engine as the terminal UI.
# ============================================================================

# Shared, pre-compiled handlers: per-element data lives in DataContext, so
# building many rows does not compile a new script block for each one.
$Blob.GuiShared = @{
    RiskTip     = { param($el) New-BlobTooltipPanel -Title $Blob.RiskInfo[$el.DataContext].Label -Paragraphs @($Blob.RiskInfo[$el.DataContext].Text) }
    TweakTip    = { param($el) New-BlobTweakTooltip (Get-BlobTweak $el.DataContext) }
    SwitchClick = { Switch-BlobGuiTweak $Blob.Gui.Sender.DataContext }
}

# Palette: paper, ink and one signal colour. The old colour-tag names used in
# log/preview lines map onto it: Cyan marks structure (signal), Yellow/Magenta
# warn (signal text), Red is reserved for failures.
$Blob.GuiColors = @{
    Paper = '#EFECE6'; Surface = '#F7F5F1'; Hover = '#E4E0D8'; Rule = '#D6D2CA'
    Ink = '#141414'; Ink2 = '#57544E'; Ink3 = '#8A867E'; Ghost = '#B8B3A9'
    Signal = '#FF4F00'; SignalText = '#B83A00'; SignalSoft = '#FBE4D7'; Error = '#B3261E'
    Cyan = '#B83A00'; DarkCyan = '#D6D2CA'; White = '#141414'; Gray = '#57544E'; DarkGray = '#8A867E'
    Green = '#141414'; Yellow = '#B83A00'; Red = '#B3261E'; DarkYellow = '#8A867E'; Magenta = '#B83A00'; Black = '#141414'
}
$Blob.GuiFonts = @{ Display = 'Bahnschrift, Segoe UI'; Mono = 'Cascadia Mono, Consolas'; Body = 'Segoe UI' }

function Test-BlobGuiSupported {
    if ([Threading.Thread]::CurrentThread.GetApartmentState() -ne 'STA') { return 'PowerShell is not running in STA mode (required by WPF).' }
    try { Add-Type -AssemblyName PresentationFramework, PresentationCore, WindowsBase -ErrorAction Stop } catch { return 'WPF is not available on this system.' }
    return $null
}

function New-BlobGuiWindow {
    param([string]$Xaml)
    $full = $Xaml.Replace('<!--THEME-->', "<Window.Resources>$($Blob.GuiTheme)</Window.Resources>")
    return [Windows.Markup.XamlReader]::Parse($full)
}

function Get-BlobBrush {
    param([string]$Color)
    if (-not $Blob.GuiBrushCache) { $Blob.GuiBrushCache = @{} }
    $hex = if ($Blob.GuiColors.ContainsKey($Color)) { $Blob.GuiColors[$Color] } else { $Color }
    if (-not $Blob.GuiBrushCache.ContainsKey($hex)) {
        $b = New-Object Windows.Media.SolidColorBrush ([Windows.Media.ColorConverter]::ConvertFromString($hex))
        $b.Freeze()
        $Blob.GuiBrushCache[$hex] = $b
    }
    return $Blob.GuiBrushCache[$hex]
}

function Get-BlobFont { param([string]$Kind) return [Windows.Media.FontFamily]::new($Blob.GuiFonts[$Kind]) }

# Turns a colour-tagged line ("{Gray}a {White}b") into a TextBlock of Runs.
function ConvertTo-BlobTextBlock {
    param([string]$Markup, [double]$Size = 13, [switch]$Mono, [string]$Default = 'White')
    $tb = [Windows.Controls.TextBlock]::new()
    $tb.FontSize = $Size
    $tb.TextWrapping = 'Wrap'
    if ($Mono) { $tb.FontFamily = Get-BlobFont 'Mono' }
    $parts = [regex]::Split($Markup, $Blob.ColorTag)
    $color = $Default
    for ($i = 0; $i -lt $parts.Count; $i++) {
        if ($i % 2 -eq 1) { $color = $parts[$i]; continue }
        if ($parts[$i].Length -eq 0) { continue }
        $run = [Windows.Documents.Run]::new($parts[$i])
        $run.Foreground = Get-BlobBrush $color
        $tb.Inlines.Add($run)
    }
    if ($Markup.Length -eq 0) { $tb.Height = 8 }
    return $tb
}

# ---------------------------------------------------------------------------
#  Control factories
# ---------------------------------------------------------------------------
function New-BlobText {
    param([string]$Text, [double]$Size = 13, [string]$Color = 'Ink', [string]$Weight = 'Normal', [string]$Margin = '0', [switch]$Display, [switch]$Mono)
    $t = [Windows.Controls.TextBlock]::new()
    $t.Text = $Text; $t.FontSize = $Size; $t.Foreground = Get-BlobBrush $Color
    $t.FontWeight = $Weight; $t.Margin = $Margin; $t.TextWrapping = 'Wrap'
    if ($Display) { $t.FontFamily = Get-BlobFont 'Display' }
    if ($Mono) { $t.FontFamily = Get-BlobFont 'Mono' }
    return $t
}

function New-BlobButton {
    param([string]$Label, [scriptblock]$Action, [ValidateSet('Normal', 'Accent', 'Danger', 'Link')][string]$Kind = 'Normal', [string]$ToolTip, [string]$Margin)
    $b = [Windows.Controls.Button]::new()
    $b.Content = $Label
    if ($Kind -eq 'Accent') { $b.Style = $Blob.Gui.Window.FindResource('AccentButton') }
    if ($Kind -eq 'Danger') { $b.Style = $Blob.Gui.Window.FindResource('DangerButton') }
    if ($Kind -eq 'Link') { $b.Style = $Blob.Gui.Window.FindResource('ChipButton'); $b.Foreground = Get-BlobBrush 'Ink'; $b.BorderBrush = Get-BlobBrush 'Ink' }
    if ($ToolTip) { $b.ToolTip = $ToolTip }
    if ($Margin) { $b.Margin = $Margin }
    Register-BlobClick $b $Action
    return $b
}

# Handlers store their action in Tag and run through Invoke-BlobGuiAction,
# which guards against re-entry and reports errors instead of crashing.
function Register-BlobClick {
    param($Control, [scriptblock]$Action)
    $Control.Tag = $Action
    $Control.Add_Click({ param($s, $e) $Blob.Gui.Sender = $s; Invoke-BlobGuiAction $s.Tag })
}

function Invoke-BlobGuiAction {
    param([scriptblock]$Action)
    if ($Blob.Gui.Busy -or -not $Action) { return }
    $Blob.Gui.Busy = $true
    $Blob.Gui.Window.Cursor = [Windows.Input.Cursors]::Wait
    try { & $Action }
    catch {
        $msg = $_.Exception.Message
        Write-BlobLog "GUI error: $msg $($_.InvocationInfo.PositionMessage)" 'ERROR'
        Add-BlobGuiLog "{Red}Error: $($msg -replace '[{}]', '')"
        Show-BlobGuiMessage -Title 'Something went wrong' -Kind Error -Lines @("{Gray}$($msg -replace '[{}]', '')", '', '{Gray}No further changes were made. Details are in the session log.')
    } finally {
        $Blob.Gui.Busy = $false
        $Blob.Gui.Window.Cursor = $null
        Set-BlobGuiStatus 'Ready'
    }
}

# A section on paper: hairline border, no rounding, no shadow.
function New-BlobCard {
    param($Child, [string]$Margin = '0,0,0,18', [string]$Padding = '18,14', [double]$Width = [double]::NaN)
    $c = [Windows.Controls.Border]::new()
    $c.Background = Get-BlobBrush 'Surface'; $c.BorderBrush = Get-BlobBrush 'Rule'
    $c.BorderThickness = 1; $c.Padding = $Padding; $c.Margin = $Margin
    if (-not [double]::IsNaN($Width)) { $c.Width = $Width }
    $c.Child = $Child
    return $c
}

function New-BlobBadge {
    param([string]$Text, [string]$Color = 'Ink2')
    $b = [Windows.Controls.Border]::new()
    $b.Padding = '6,0,6,1'; $b.Margin = '8,0,0,0'; $b.VerticalAlignment = 'Center'
    $b.BorderBrush = Get-BlobBrush $(if ($Color -in @('Gray', 'DarkGray', 'Ink2', 'Ink3')) { 'Rule' } else { $Color })
    $b.BorderThickness = 1
    $b.Child = New-BlobText $Text 11 $Color 'Normal' -Display
    return $b
}

function New-BlobStack {
    param([string]$Orientation = 'Vertical', [string]$Margin = '0')
    $s = [Windows.Controls.StackPanel]::new()
    $s.Orientation = $Orientation; $s.Margin = $Margin
    return $s
}

# Section heading: Bahnschrift capitals over a hairline.
function New-BlobHeading {
    param([string]$Text, [string]$Margin = '0,10,0,10')
    $b = [Windows.Controls.Border]::new()
    $b.BorderBrush = Get-BlobBrush 'Ink'; $b.BorderThickness = '0,0,0,1'; $b.Margin = $Margin; $b.Padding = '0,0,0,5'
    $b.Child = New-BlobText $Text.ToUpper() 12.5 'Ink' 'SemiBold' -Display
    return $b
}

function New-BlobBar {
    param([double]$Fraction, [double]$Width = 260)
    $p = [Windows.Controls.ProgressBar]::new()
    $p.Minimum = 0; $p.Maximum = 1; $p.Value = [Math]::Min(1, [Math]::Max(0, $Fraction)); $p.Width = $Width
    $p.Foreground = if ($Fraction -ge 0.9) { Get-BlobBrush 'Signal' } else { Get-BlobBrush 'Ink' }
    return $p
}

function New-BlobCombo {
    param([string[]]$Items, [int]$Selected = 0, [double]$Width = 220)
    $c = [Windows.Controls.ComboBox]::new()
    foreach ($i in $Items) { [void]$c.Items.Add($i) }
    if ($Items.Count -gt 0) { $c.SelectedIndex = [Math]::Max(0, $Selected) }
    $c.Width = $Width; $c.Margin = '0,0,16,0'
    return $c
}

function New-BlobGrid {
    param([array]$Columns, [double]$Height = 420)
    # Columns: @( @{ Header; Path; Width } )
    $g = [Windows.Controls.DataGrid]::new()
    $g.Height = $Height
    foreach ($col in $Columns) {
        $c = [Windows.Controls.DataGridTextColumn]::new()
        $c.Header = $col.Header.ToUpper()
        $c.Binding = New-Object Windows.Data.Binding $col.Path
        if ($col.Width) { $c.Width = New-Object Windows.Controls.DataGridLength($col.Width, $(if ($col.Width -le 1) { 'Star' } else { 'Pixel' })) }
        else { $c.Width = New-Object Windows.Controls.DataGridLength(1, 'Star') }
        [void]$g.Columns.Add($c)
    }
    return $g
}

# Lines of markup rendered in a section (used for info pages).
function New-BlobInfoCard {
    param([string[]]$Lines, [switch]$Mono)
    $s = New-BlobStack
    foreach ($l in $Lines) { [void]$s.Children.Add((ConvertTo-BlobTextBlock $l -Mono:$Mono -Size 12.5)) }
    return (New-BlobCard $s)
}

# ---------------------------------------------------------------------------
#  Help marks, tooltips and the risk meter
# ---------------------------------------------------------------------------
function New-BlobTooltipPanel {
    param([string]$Title, [string[]]$Paragraphs = @(), [string[]]$Mono = @(), [string]$MonoTitle = '')
    $s = New-BlobStack
    $s.MaxWidth = 490
    [void]$s.Children.Add((New-BlobText $Title 16 'Ink' 'SemiBold' '0,0,0,8' -Display))
    foreach ($p in $Paragraphs) {
        if (-not $p) { continue }
        [void]$s.Children.Add((ConvertTo-BlobTextBlock $p -Size 12.5 -Default 'Gray'))
        $s.Children[$s.Children.Count - 1].Margin = '0,0,0,6'
    }
    if ($Mono.Count -gt 0) {
        if ($MonoTitle) { [void]$s.Children.Add((New-BlobText $MonoTitle.ToUpper() 11 'Ink3' 'Normal' '0,6,0,4' -Display)) }
        foreach ($m in $Mono) { [void]$s.Children.Add((ConvertTo-BlobTextBlock $m -Mono -Size 11.5)) }
    }
    return $s
}

function Set-BlobTooltip {
    param($Element, $Content)
    $Element.ToolTip = $Content
    [Windows.Controls.ToolTipService]::SetInitialShowDelay($Element, 150)
    [Windows.Controls.ToolTipService]::SetShowDuration($Element, 120000)
    [Windows.Controls.ToolTipService]::SetPlacement($Element, 'Bottom')
}

# A small circled "?" that shows detailed help when hovered.
function New-BlobHelpIcon {
    param($Tooltip, [scriptblock]$Builder)
    $b = [Windows.Controls.Border]::new()
    $b.Width = 18; $b.Height = 18; $b.CornerRadius = 9
    $b.BorderThickness = 1.2; $b.BorderBrush = Get-BlobBrush 'Ink3'; $b.Background = [Windows.Media.Brushes]::Transparent
    $b.Margin = '8,0,0,0'; $b.VerticalAlignment = 'Center'; $b.Cursor = [Windows.Input.Cursors]::Help
    $t = New-BlobText '?' 11.5 'Ink2' 'SemiBold' -Display
    $t.HorizontalAlignment = 'Center'; $t.VerticalAlignment = 'Center'; $t.Margin = '0,-1,0,0'
    $b.Child = $t
    $b.Add_MouseEnter({ param($s, $e) $s.BorderBrush = Get-BlobBrush 'Ink'; $s.Child.Foreground = Get-BlobBrush 'Ink' })
    $b.Add_MouseLeave({ param($s, $e) $s.BorderBrush = Get-BlobBrush 'Ink3'; $s.Child.Foreground = Get-BlobBrush 'Ink2' })
    if ($Builder) { Set-BlobLazyTooltip $b $Builder } else { Set-BlobTooltip $b $Tooltip }
    return $b
}

# Tooltip content built on first hover (keeps long lists fast).
function Set-BlobLazyTooltip {
    param($Element, [scriptblock]$Builder)
    Set-BlobTooltip $Element 'Loading...'
    $Element.Tag = $Builder
    $Element.Add_ToolTipOpening({ param($s, $e) if ($s.Tag -is [scriptblock]) { $sb = $s.Tag; $s.Tag = $null; $s.ToolTip = & $sb $s } })
}

# Risk meter: three small bars and a word. HIGH is the only one in signal orange.
$Blob.RiskMeter = @{
    Minimal  = @{ Level = 1; Word = 'LOW' }
    Standard = @{ Level = 2; Word = 'MED' }
    Advanced = @{ Level = 3; Word = 'HIGH' }
    Optional = @{ Level = 0; Word = 'PREF' }
}

function New-BlobRiskBadge {
    param([string]$Risk)
    $m = $Blob.RiskMeter[$Risk]
    $sp = New-BlobStack 'Horizontal'
    $sp.VerticalAlignment = 'Center'; $sp.Background = [Windows.Media.Brushes]::Transparent; $sp.Cursor = [Windows.Input.Cursors]::Help
    $fill = if ($Risk -eq 'Advanced') { Get-BlobBrush 'Signal' } else { Get-BlobBrush 'Ink' }
    for ($i = 1; $i -le 3; $i++) {
        $bar = [Windows.Shapes.Rectangle]::new()
        $bar.Width = 5; $bar.Height = 4 + 3 * $i; $bar.Margin = '0,0,2,0'; $bar.VerticalAlignment = 'Bottom'
        $bar.Fill = if ($i -le $m.Level) { $fill } else { Get-BlobBrush 'Rule' }
        [void]$sp.Children.Add($bar)
    }
    $word = New-BlobText $m.Word 11.5 $(if ($Risk -eq 'Advanced') { 'SignalText' } else { 'Ink2' }) 'SemiBold' '6,0,0,0' -Display
    $word.VerticalAlignment = 'Bottom'
    [void]$sp.Children.Add($word)
    $sp.DataContext = $Risk
    Set-BlobLazyTooltip $sp $Blob.GuiShared.RiskTip
    return $sp
}

function New-BlobRiskLegend {
    $wrap = [Windows.Controls.WrapPanel]::new()
    foreach ($k in @('Minimal', 'Standard', 'Advanced', 'Optional')) {
        $item = New-BlobStack 'Horizontal' '0,0,22,0'
        [void]$item.Children.Add((New-BlobRiskBadge $k))
        $short = switch ($k) { 'Minimal' { 'safe, minor' } 'Standard' { 'changes a feature' } 'Advanced' { 'test afterwards' } default { 'taste only' } }
        [void]$item.Children.Add((New-BlobText $short 12 'Ink3' 'Normal' '8,0,0,0'))
        [void]$wrap.Children.Add($item)
    }
    return $wrap
}

# Restore point step used before applying changes from the window.
function Invoke-BlobGuiRestorePointStep {
    param([string]$Description)
    Start-BlobGuiTask 'Creating System Restore point (this can take a minute)'
    Add-BlobGuiLog (New-BlobRestorePoint $Description)
}

# ---------------------------------------------------------------------------
#  Activity log and status
# ---------------------------------------------------------------------------
function Update-BlobGui {
    if ($Blob.Gui.Preloading) { return }
    try { $Blob.Gui.Window.Dispatcher.Invoke([Action] {}, [Windows.Threading.DispatcherPriority]::Background) } catch { }
}

function Add-BlobGuiLog {
    param([string]$Markup)
    $panel = $Blob.Gui.LogPanel
    if ($panel.Children.Count -gt 600) { $panel.Children.RemoveAt(0) }
    $stamp = '{DarkGray}' + (Get-Date -Format 'HH:mm:ss') + '  '
    [void]$panel.Children.Add((ConvertTo-BlobTextBlock ($stamp + $Markup) -Mono -Size 12))
    $Blob.Gui.LogScroll.ScrollToEnd()
    $Blob.Gui.LogLast.Text = (Get-BlobPlainText $Markup).Trim()
    Update-BlobGui
}

function Set-BlobGuiStatus {
    param([string]$Text)
    if ($Blob.Gui.Preloading) { return }
    $Blob.Gui.StatusText.Text = $Text
    Update-BlobGui
}

# ---------------------------------------------------------------------------
#  Dialogs
# ---------------------------------------------------------------------------
function Show-BlobGuiDialog {
    param([string]$Title, [string]$Subtitle = '', [string[]]$Lines = @(), [string]$OkText = 'Confirm',
          [switch]$Danger, [switch]$InfoOnly, [string]$Kind = 'Info', [string]$CancelText = 'Cancel',
          [string]$CheckText, [bool]$CheckDefault = $false, [bool]$CheckEnabled = $true)
    $d = New-BlobGuiWindow $Blob.GuiDialogXaml
    $d.Owner = $Blob.Gui.Window
    $d.Title = $Title
    $d.FindName('DlgTitle').Text = $Title
    $d.FindName('DlgSub').Text = $Subtitle
    if (-not $Subtitle) { $d.FindName('DlgSub').Visibility = 'Collapsed' }
    $body = $d.FindName('DlgBody')
    if ($Blob.DryRun -and -not $InfoOnly) { [void]$body.Children.Add((ConvertTo-BlobTextBlock '{Magenta}DRY RUN is active: nothing will actually be changed.')); [void]$body.Children.Add((ConvertTo-BlobTextBlock '')) }
    foreach ($l in $Lines) { [void]$body.Children.Add((ConvertTo-BlobTextBlock $l -Mono -Size 12.5)) }
    $ok = $d.FindName('DlgOk'); $cancel = $d.FindName('DlgCancel')
    $ok.Content = $OkText
    $cancel.Content = $CancelText
    # The stripe on top carries the mood: ink normally, signal for risky or failed things.
    $stripe = if ($Danger -or $Kind -in @('Error', 'Warning')) { 'Signal' } else { 'Ink' }
    $d.FindName('DlgStripe').Background = Get-BlobBrush $stripe
    if ($Danger) { $ok.Background = Get-BlobBrush 'Signal'; $ok.BorderBrush = Get-BlobBrush 'Signal'; $ok.Foreground = Get-BlobBrush 'Ink' }
    if ($InfoOnly) { $cancel.Visibility = 'Collapsed' }
    $check = $d.FindName('DlgCheck')
    if ($CheckText) {
        $check.Visibility = 'Visible'
        $d.FindName('DlgCheckText').Text = $CheckText
        $check.IsChecked = $CheckDefault
        $check.IsEnabled = $CheckEnabled
    }
    $d.Tag = $false
    $ok.Add_Click({ param($s, $e) $w = [Windows.Window]::GetWindow($s); $w.Tag = $true; $w.Close() })
    $cancel.Add_Click({ param($s, $e) [Windows.Window]::GetWindow($s).Close() })
    $d.Add_KeyDown({ param($s, $e) if ($e.Key -eq 'Escape') { $s.Close() } })
    if ($Lines.Count -le 6) { $d.Height = 300 }
    $null = $d.ShowDialog()
    $Blob.Gui.DialogCheck = ($CheckText -and $check.IsEnabled -and [bool]$check.IsChecked)
    return [bool]$d.Tag
}

function Show-BlobGuiMessage {
    param([string]$Title, [string[]]$Lines = @(), [ValidateSet('Info', 'Success', 'Warning', 'Error')][string]$Kind = 'Info')
    $null = Show-BlobGuiDialog -Title $Title -Lines $Lines -OkText 'Close' -InfoOnly -Kind $Kind
}

function Confirm-BlobGui {
    param([string]$Title, [string[]]$Lines, [string]$Subtitle = '', [string]$OkText = 'Apply', [switch]$Danger)
    return Show-BlobGuiDialog -Title $Title -Subtitle $Subtitle -Lines $Lines -OkText $OkText -Danger:$Danger
}

function Show-BlobGuiInput {
    param([string]$Title, [string[]]$Prompt, [string]$Default = '', [scriptblock]$Validate)
    $d = New-BlobGuiWindow $Blob.GuiDialogXaml
    $d.Owner = $Blob.Gui.Window
    $d.Height = 300
    $d.FindName('DlgTitle').Text = $Title
    $d.FindName('DlgSub').Visibility = 'Collapsed'
    $body = $d.FindName('DlgBody')
    foreach ($p in $Prompt) { [void]$body.Children.Add((ConvertTo-BlobTextBlock $p)) }
    $box = [Windows.Controls.TextBox]::new()
    $box.Text = $Default; $box.Margin = '0,12,0,6'
    [void]$body.Children.Add($box)
    $err = New-BlobText '' 12 'Red'
    [void]$body.Children.Add($err)
    $d.FindName('DlgOk').Content = 'OK'
    $d.Tag = @{ Result = $null; Validate = $Validate; Box = $box; Err = $err }
    $d.FindName('DlgOk').Add_Click({
            param($s, $e)
            $w = [Windows.Window]::GetWindow($s); $st = $w.Tag
            $v = $st.Box.Text.Trim()
            $msg = if ($st.Validate) { & $st.Validate $v } else { $null }
            if ($msg) { $st.Err.Text = $msg } else { $st.Result = $v; $w.Close() }
        })
    $d.FindName('DlgCancel').Add_Click({ param($s, $e) [Windows.Window]::GetWindow($s).Close() })
    $d.Add_KeyDown({ param($s, $e) if ($e.Key -eq 'Escape') { $s.Close() } })
    $d.Add_ContentRendered({ param($s, $e) $s.Tag.Box.Focus(); $s.Tag.Box.SelectAll() })
    $null = $d.ShowDialog()
    return $d.Tag.Result
}

function Show-BlobGuiAdminRequired {
    param([string]$Why)
    Show-BlobGuiMessage -Title 'Administrator rights required' -Kind Warning -Lines @(
        "{White}$Why", '',
        '{Gray}BLOB OPTIMIZER asks for administrator rights when it starts.',
        '{Gray}Close it and start it again, then choose Yes in the Windows permission prompt.')
}

# Runs a list of operations with progress in the activity log.
function Start-BlobGuiTask {
    param([string]$Title)
    Set-BlobGuiStatus "$Title..."
    Add-BlobGuiLog "{Cyan}$($Blob.Ch.On) {White}$Title"
}

# ---------------------------------------------------------------------------
#  Window and navigation
# ---------------------------------------------------------------------------
# Per-page state that builders put on $Blob.Gui. It is saved with each cached
# page and restored when the page is shown, so pages never share state.
$Blob.GuiPageState = @('P', 'CardGrid', 'CardCount', 'ApplySelBtn', 'SearchHint', 'PendingActions')
# Pages that show setting / journal state: refreshed in the background after any change.
$Blob.GuiVolatilePages = @('dashboard', 'presets', 'optimize', 'privacy', 'services', 'startup', 'apps', 'power', 'restore', 'measure')
# Preload order, and pages that wait for the background data snapshot on their first build.
$Blob.GuiPreloadOrder = @('optimize', 'privacy', 'presets', 'startup', 'power', 'restore', 'tools', 'measure', 'services', 'apps', 'cleanup', 'network', 'sysinfo', 'install', 'dashboard')
$Blob.GuiHeavyPages = @('services', 'apps', 'cleanup', 'network', 'sysinfo', 'install', 'dashboard')

function Set-BlobGuiPageActions {
    param([array]$Buttons = @())
    $Blob.Gui.PendingActions = @($Buttons)
}

# Builds a page into the cache without disturbing the page currently shown.
function New-BlobGuiPageEntry {
    param([string]$Key)
    $page = $Blob.Gui.Pages | Where-Object { $_.Key -eq $Key } | Select-Object -First 1
    $saved = @{}
    foreach ($n in $Blob.GuiPageState) { $saved[$n] = $Blob.Gui[$n]; $Blob.Gui[$n] = $null }
    $Blob.Gui.PendingActions = @()
    $sw = [Diagnostics.Stopwatch]::StartNew()
    try { $content = & $page.Build }
    catch {
        $content = New-BlobInfoCard @("{Red}This page could not be loaded: $($_.Exception.Message -replace '[{}]', '')")
        Write-BlobLog "GUI page '$Key' failed: $($_.Exception.Message) $($_.InvocationInfo.PositionMessage)" 'ERROR'
    }
    $entry = @{ Content = $content; Stale = $false; Scroll = 0; Ms = $sw.ElapsedMilliseconds }
    foreach ($n in $Blob.GuiPageState) { $entry[$n] = $Blob.Gui[$n]; $Blob.Gui[$n] = $saved[$n] }
    $Blob.Gui.Cache[$Key] = $entry
    return $entry
}

function Show-BlobGuiPage {
    param([string]$Key, [switch]$KeepScroll, [switch]$Rebuild)
    $page = $Blob.Gui.Pages | Where-Object { $_.Key -eq $Key } | Select-Object -First 1
    if (-not $page) { return }
    if ($Blob.Gui.Current -and $Blob.Gui.Current -ne $Key -and $Blob.Gui.Cache.ContainsKey($Blob.Gui.Current)) {
        $Blob.Gui.Cache[$Blob.Gui.Current].Scroll = $Blob.Gui.PageScroll.VerticalOffset
    }

    $entry = $Blob.Gui.Cache[$Key]
    if ($Rebuild -or -not $entry -or $entry.Stale) {
        $Blob.Gui.Window.Cursor = [Windows.Input.Cursors]::Wait
        $Blob.Gui.StatusText.Text = "Loading $($page.Label)..."
        $oldScroll = if ($entry) { $entry.Scroll } else { 0 }
        try { $entry = New-BlobGuiPageEntry $Key } finally { $Blob.Gui.Window.Cursor = $null }
        $entry.Scroll = $oldScroll
    }

    $Blob.Gui.Current = $Key
    foreach ($n in $Blob.GuiPageState) { $Blob.Gui[$n] = $entry[$n] }
    for ($i = 0; $i -lt $Blob.Gui.Pages.Count; $i++) {
        $p = $Blob.Gui.Pages[$i]
        $btn = $Blob.Gui.Nav[$p.Key]
        if ($p.Key -eq $Key) {
            $btn.Foreground = Get-BlobBrush 'Ink'; $btn.BorderBrush = Get-BlobBrush 'Signal'; $btn.FontWeight = 'SemiBold'
            $Blob.Gui.NavNum[$p.Key].Foreground = Get-BlobBrush 'SignalText'
            $Blob.Gui.PageNumber.Text = '{0:D2}' -f ($i + 1)
        } else {
            $btn.Foreground = Get-BlobBrush 'Ink2'; $btn.BorderBrush = [Windows.Media.Brushes]::Transparent; $btn.FontWeight = 'Normal'
            $Blob.Gui.NavNum[$p.Key].Foreground = Get-BlobBrush 'Ink3'
        }
    }
    $Blob.Gui.PageTitle.Text = $page.Label
    $Blob.Gui.PageSubtitle.Text = $page.Subtitle
    $Blob.Gui.PageActions.Children.Clear()
    foreach ($b in @($entry.PendingActions)) { if ($b) { [void]$Blob.Gui.PageActions.Children.Add($b) } }
    $Blob.Gui.PageHost.Content = $entry.Content
    Update-BlobGuiCardColumns
    if (-not $KeepScroll) { $Blob.Gui.PageScroll.UpdateLayout(); $Blob.Gui.PageScroll.ScrollToVerticalOffset($entry.Scroll) }
    if ($Blob.Gui.PreloadDone -or -not $Blob.Gui.PreloadTimer) { $Blob.Gui.StatusText.Text = 'Ready' }
}

# Re-renders the current page after a change (keeping the scroll position)
# and schedules a quiet background refresh of the other affected tabs.
function Update-BlobGuiPage {
    $Blob.PrefetchValid = $false        # data may have changed: query live from now on
    $offset = $Blob.Gui.PageScroll.VerticalOffset
    foreach ($k in $Blob.GuiVolatilePages) {
        if ($k -ne $Blob.Gui.Current -and $Blob.Gui.Cache.ContainsKey($k)) { $Blob.Gui.Cache[$k].Stale = $true }
    }
    Show-BlobGuiPage $Blob.Gui.Current -KeepScroll -Rebuild
    $Blob.Gui.PageScroll.UpdateLayout()
    $Blob.Gui.PageScroll.ScrollToVerticalOffset($offset)
    Start-BlobGuiPreload
}

function Start-BlobGuiPreload {
    if (-not $Blob.Gui.PreloadTimer) {
        $t = New-Object Windows.Threading.DispatcherTimer ([Windows.Threading.DispatcherPriority]::ApplicationIdle)
        $t.Interval = [TimeSpan]::FromMilliseconds(30)
        $t.Add_Tick({ Invoke-BlobGuiPreloadTick })
        $Blob.Gui.PreloadTimer = $t
    }
    $Blob.Gui.PreloadTimer.Start()
}

# Builds at most one page per tick so the window stays responsive.
function Invoke-BlobGuiPreloadTick {
    if ($Blob.Gui.Preloading -or $Blob.Gui.Busy) { return }
    if ($Blob.Gui.Window.OwnedWindows.Count -gt 0) { return }      # a dialog is open
    if ($Blob.PrefetchState -eq 'Running') { $null = Receive-BlobPrefetch }
    $waiting = $Blob.PrefetchState -eq 'Running'
    # Warm the Optimizations cards a few at a time so the window never stalls.
    if (-not $Blob.Gui.CardsWarm -and -not $Blob.Gui.Cache.ContainsKey('optimize')) {
        if (-not $Blob.Gui.CardQueue) { $Blob.Gui.CardQueue = [Collections.Queue]::new([object[]]$Blob.Tweaks.ToArray()) }
        $Blob.Gui.Preloading = $true
        try {
            for ($i = 0; $i -lt 6 -and $Blob.Gui.CardQueue.Count -gt 0; $i++) {
                $t = $Blob.Gui.CardQueue.Dequeue()
                $null = Get-BlobGuiCard $t (Get-BlobTweakState $t)
            }
        } finally { $Blob.Gui.Preloading = $false }
        if ($Blob.Gui.CardQueue.Count -eq 0) { $Blob.Gui.CardsWarm = $true }
        $Blob.Gui.StatusText.Text = "Preloading settings... $($Blob.Tweaks.Count - $Blob.Gui.CardQueue.Count) of $($Blob.Tweaks.Count)"
        return
    }
    $next = $null
    foreach ($k in $Blob.GuiPreloadOrder) {
        $e = $Blob.Gui.Cache[$k]
        if ($e -and -not $e.Stale) { continue }
        if ($k -eq $Blob.Gui.Current) { continue }
        if ($waiting -and -not $e -and $k -in $Blob.GuiHeavyPages) { continue }
        $next = $k; break
    }
    $total = $Blob.Gui.Pages.Count
    if (-not $next) {
        if ($waiting) { $Blob.Gui.StatusText.Text = 'Collecting system information in the background...'; return }
        $Blob.Gui.PreloadTimer.Stop()
        if (-not $Blob.Gui.PreloadDone) {
            $Blob.Gui.PreloadDone = $true
            $ms = 0; foreach ($e in $Blob.Gui.Cache.Values) { $ms += $e.Ms }
            Write-BlobLog "All $total tabs preloaded ($ms ms of build time)."
        }
        $Blob.Gui.StatusText.Text = 'Ready - all tabs loaded'
        return
    }
    $Blob.Gui.Preloading = $true
    try { $null = New-BlobGuiPageEntry $next } finally { $Blob.Gui.Preloading = $false }
    $ready = @($Blob.Gui.Cache.Values | Where-Object { -not $_.Stale }).Count
    if (-not $Blob.Gui.PreloadDone) { $Blob.Gui.StatusText.Text = "Preloading tabs... $ready of $total ready" }
}

# Card grids use as many columns as fit (about 300 px per card).
function Update-BlobGuiCardColumns {
    $g = $Blob.Gui.CardGrid
    if (-not ($g -is [Windows.Controls.Primitives.UniformGrid])) { return }
    $w = $Blob.Gui.PageScroll.ViewportWidth
    if (-not $w -or $w -le 0) { $w = $Blob.Gui.Window.ActualWidth - 60 }
    if (-not $w -or $w -le 0) { $w = $Blob.Gui.Window.Width - 60 }
    $g.Columns = [Math]::Max(1, [int][Math]::Floor($w / 300))
}

# The black bar at the bottom appears whenever choices are waiting to be applied.
function Update-BlobGuiPendingBar {
    $n = $Blob.Gui.Pending.Count
    if ($n -gt 0) {
        $on = @($Blob.Gui.Pending.Values | Where-Object { $_ -eq 'On' }).Count
        $off = $n - $on
        $parts = @()
        if ($on) { $parts += "$on to switch on" }
        if ($off) { $parts += "$off to switch off" }
        $Blob.Gui.PendingText.Text = "$($parts -join ', ').  Nothing has been changed yet."
        $Blob.Gui.PendingApply.Content = "Review and apply $n"
        $Blob.Gui.PendingBar.Visibility = 'Visible'
    } else { $Blob.Gui.PendingBar.Visibility = 'Collapsed' }
}

function Initialize-BlobGuiWindow {
    $w = New-BlobGuiWindow $Blob.GuiXaml
    $Blob.Gui = @{ Window = $w; Busy = $false; Current = $null; Nav = @{}; NavNum = @{}; LogVisible = $false }
    foreach ($n in @('TitleVersion', 'AdminBadge', 'AdminBadgeText', 'DryRunBadge', 'BtnMin', 'BtnMax', 'BtnClose', 'CloseGlyph', 'NavPanel',
                     'PageActions', 'PageNumber', 'PageTitle', 'PageSubtitle', 'PageScroll', 'PageHost', 'BtnToggleLog', 'BtnClearLog',
                     'LogScroll', 'LogPanel', 'LogLast', 'StatusText', 'StatusRight', 'RootBorder',
                     'PendingBar', 'PendingText', 'PendingDiscard', 'PendingApply', 'BtnSearch')) {
        $Blob.Gui[$n] = $w.FindName($n)
    }
    # Fit the window to the screen (taller when there is room, so the whole sidebar shows).
    try {
        $wa = [Windows.SystemParameters]::WorkArea
        $w.Height = [Math]::Max($w.MinHeight, [Math]::Min(880, $wa.Height - 40))
        $w.Width = [Math]::Max($w.MinWidth, [Math]::Min(1320, $wa.Width - 40))
    } catch { }
    $w.Title = "BLOB OPTIMIZER $($Blob.Version)"
    $Blob.Gui.TitleVersion.Text = $Blob.Version
    if ($Blob.IsAdmin) {
        $Blob.Gui.AdminBadge.BorderBrush = Get-BlobBrush 'Ink'; $Blob.Gui.AdminBadgeText.Text = 'ADMINISTRATOR'; $Blob.Gui.AdminBadgeText.Foreground = Get-BlobBrush 'Ink'
    } else {
        $Blob.Gui.AdminBadge.BorderBrush = Get-BlobBrush 'SignalText'; $Blob.Gui.AdminBadgeText.Text = 'LIMITED  -  SYSTEM SETTINGS READ-ONLY'; $Blob.Gui.AdminBadgeText.Foreground = Get-BlobBrush 'SignalText'
    }
    if ($Blob.DryRun) { $Blob.Gui.DryRunBadge.Visibility = 'Visible' }
    $Blob.Gui.StatusRight.Text = "$($Blob.SysInfo.Host)   PowerShell $($PSVersionTable.PSVersion.Major).$($PSVersionTable.PSVersion.Minor)   backups $($Blob.DataRoot)"

    $Blob.Gui.BtnMin.Add_Click({ $Blob.Gui.Window.WindowState = 'Minimized' })
    $Blob.Gui.BtnMax.Add_Click({ $win = $Blob.Gui.Window; if ($win.WindowState -eq 'Maximized') { $win.WindowState = 'Normal' } else { $win.WindowState = 'Maximized' } })
    $Blob.Gui.BtnClose.Add_Click({ $Blob.Gui.Window.Close() })
    $Blob.Gui.BtnClose.Add_MouseEnter({ $Blob.Gui.CloseGlyph.Stroke = Get-BlobBrush 'Paper' })
    $Blob.Gui.BtnClose.Add_MouseLeave({ $Blob.Gui.CloseGlyph.Stroke = Get-BlobBrush 'Ink' })
    # A chromeless maximised window overhangs the screen edge; pad it.
    $w.Add_StateChanged({
            $win = $Blob.Gui.Window
            $Blob.Gui.RootBorder.Margin = if ($win.WindowState -eq 'Maximized') { '7' } else { '0' }
        })
    $Blob.Gui.BtnClearLog.Add_Click({ $Blob.Gui.LogPanel.Children.Clear() })
    $Blob.Gui.BtnToggleLog.Add_Click({
            $Blob.Gui.LogVisible = -not $Blob.Gui.LogVisible
            $Blob.Gui.LogScroll.Visibility = if ($Blob.Gui.LogVisible) { 'Visible' } else { 'Collapsed' }
            $Blob.Gui.BtnToggleLog.Content = if ($Blob.Gui.LogVisible) { 'Hide log' } else { 'Show log' }
        })

    $Blob.Gui.Pages = [System.Collections.ArrayList]@(Get-BlobGuiPages)
    foreach ($p in $Blob.Gui.Pages) {
        $btn = [Windows.Controls.Button]::new()
        $btn.Style = $w.FindResource('NavButton')
        $sp = New-BlobStack 'Horizontal'
        $num = New-BlobText ('{0:D2}' -f ($Blob.Gui.Pages.IndexOf($p) + 1)) 13 'Ink3' 'Normal' '0,1,12,0' -Display
        $num.Width = 22; $num.VerticalAlignment = 'Center'
        $Blob.Gui.NavNum[$p.Key] = $num
        $label = [Windows.Controls.TextBlock]::new()
        $label.Text = $p.Label; $label.VerticalAlignment = 'Center'
        $label.SetBinding([Windows.Controls.TextBlock]::ForegroundProperty, (New-Object Windows.Data.Binding 'Foreground' -Property @{ Source = $btn })) | Out-Null
        [void]$sp.Children.Add($num); [void]$sp.Children.Add($label)
        $btn.Content = $sp
        $btn.Tag = $p.Key
        $btn.Add_Click({ param($s, $e) if (-not $Blob.Gui.Busy) { Show-BlobGuiPage $s.Tag } })
        [void]$Blob.Gui.NavPanel.Children.Add($btn)
        $Blob.Gui.Nav[$p.Key] = $btn
    }
    $Blob.Gui.PageScroll.Add_SizeChanged({ Update-BlobGuiCardColumns })
    $Blob.Gui.Selected = @{}
    $Blob.Gui.Pending = @{}          # tweak id -> 'On' / 'Off', applied only with Apply changes
    if (-not $Blob.Gui.OptRisk) { $Blob.Gui.OptRisk = 'All' }
    $Blob.Gui.Cache = @{}
    $Blob.Gui.PreloadDone = $false
    $Blob.Gui.PreloadTimer = $null
    $Blob.Gui.CardsWarm = $false
    $Blob.Gui.CardQueue = $null
    $Blob.Gui.CardCache = @{}
    if (-not $Blob.Gui.OptFilter) { $Blob.Gui.OptFilter = 'All' }
    Register-BlobClick $Blob.Gui.PendingApply { Invoke-BlobGuiApplyPending }
    Register-BlobClick $Blob.Gui.BtnSearch { Show-BlobGuiSearch }
    $w.Add_PreviewKeyDown({
            param($s, $e)
            if ($e.Key -eq 'K' -and ([Windows.Input.Keyboard]::Modifiers -band [Windows.Input.ModifierKeys]::Control)) {
                $e.Handled = $true
                if (-not $Blob.Gui.Busy) { Invoke-BlobGuiAction { Show-BlobGuiSearch } }
            }
        })
    Register-BlobClick $Blob.Gui.PendingDiscard {
        $Blob.Gui.Pending.Clear()
        if ($Blob.Gui.Current -in @('optimize', 'privacy')) { Update-BlobGuiCardGrid }
        foreach ($k in @('optimize', 'privacy')) { if ($k -ne $Blob.Gui.Current -and $Blob.Gui.Cache.ContainsKey($k)) { $Blob.Gui.Cache[$k].Stale = $true } }
        Update-BlobGuiPendingBar
    }

    $w.Add_ContentRendered({
            Add-BlobGuiLog "{White}BLOB OPTIMIZER $($Blob.Version) {Gray}started. Every change is previewed first and can be undone from Restore."
            if (-not $Blob.IsAdmin) { Add-BlobGuiLog '{Yellow}Running without administrator rights: machine-wide settings are read-only.' }
            if ($Blob.DryRun) { Add-BlobGuiLog '{Magenta}Dry run: nothing will be modified.' }
        })
}

function Start-BlobGui {
    Initialize-BlobGuiWindow
    Start-BlobPrefetch                      # slow system data, collected on a background thread
    Show-BlobGuiPage 'dashboard'
    $Blob.Gui.Window.Add_ContentRendered({ Start-BlobGuiPreload })
    $Blob.Gui.Window.Add_Closing({
            param($s, $e)
            $n = $Blob.Gui.Pending.Count
            if ($n -gt 0) {
                $close = Show-BlobGuiDialog -Title "Close with $n unapplied change(s)?" -OkText 'Close without applying' -CancelText 'Go back' -Lines @(
                    '{Gray}You flipped switches but did not press Apply changes.',
                    '{Gray}Closing now leaves those settings exactly as they are.')
                if (-not $close) { $e.Cancel = $true }
            }
        })
    $Blob.Gui.Window.Add_Closed({
            if ($Blob.Gui.PreloadTimer) { $Blob.Gui.PreloadTimer.Stop() }
            Stop-BlobPrefetch
        })
    $null = $Blob.Gui.Window.ShowDialog()
    Stop-BlobPrefetch
}
#endregion

#region ---- GuiPages.ps1 ----
# ============================================================================
#  BLOB OPTIMIZER - GuiPages.ps1
#  Window pages: page list, Overview, Presets, Tweaks, System, External tools.
#  Every action previews exact changes in a dialog before anything happens.
# ============================================================================

function Get-BlobGuiPages {
    @(
        @{ Key = 'dashboard'; Label = 'Overview'; Subtitle = 'Where this PC stands, and where to start.'; Build = { New-BlobGuiDashboard } }
        @{ Key = 'presets'; Label = 'Presets'; Subtitle = 'Three tested bundles. Each one lists every value it changes before anything happens.'; Build = { New-BlobGuiPresets } }
        @{ Key = 'optimize'; Label = 'Tweaks'; Subtitle = 'Switch what you want on or off. Nothing is changed until you review and apply.'; Build = { New-BlobGuiOptimizations } }
        @{ Key = 'privacy'; Label = 'Privacy'; Subtitle = "$(@(Get-BlobPrivacyItems).Count) privacy settings in $($Blob.PrivacyGroups.Count) sections. Every one explained, rated and recommended. Nothing changes until you review and apply."; Build = { New-BlobGuiPrivacy } }
        @{ Key = 'services'; Label = 'Services'; Subtitle = 'Startup types only. Nothing is deleted, and services Windows depends on are locked.'; Build = { New-BlobGuiServices } }
        @{ Key = 'startup'; Label = 'Startup'; Subtitle = 'Programs that start when you sign in. Disabled the same way Task Manager does it.'; Build = { New-BlobGuiStartup } }
        @{ Key = 'apps'; Label = 'Apps'; Subtitle = 'Remove programs completely: their own uninstaller first, then the leftovers you choose.'; Build = { New-BlobGuiApps } }
        @{ Key = 'install'; Label = 'Install'; Subtitle = 'Popular apps, installed with winget from the official winget repository.'; Build = { New-BlobGuiInstall } }
        @{ Key = 'cleanup'; Label = 'Cleanup'; Subtitle = 'Temporary files and caches. Sizes are measured first; deleted files are gone for good.'; Build = { New-BlobGuiCleanup } }
        @{ Key = 'network'; Label = 'Network'; Subtitle = 'Adapters, DNS, diagnostics and the last-resort resets.'; Build = { New-BlobGuiNetwork } }
        @{ Key = 'power'; Label = 'Power'; Subtitle = 'Power plans, screen and sleep timers, hibernation.'; Build = { New-BlobGuiPower } }
        @{ Key = 'measure'; Label = 'Measure'; Subtitle = 'Real numbers: boot times from Windows and snapshots you can compare.'; Build = { New-BlobGuiMeasure } }
        @{ Key = 'restore'; Label = 'Restore'; Subtitle = 'Everything BLOB has changed, and the way back.'; Build = { New-BlobGuiRestore } }
        @{ Key = 'tools'; Label = 'External tools'; Subtitle = 'Two well-known third-party utilities, started on request.'; Build = { New-BlobGuiTools } }
        @{ Key = 'sysinfo'; Label = 'System'; Subtitle = 'Hardware and Windows details. Read-only.'; Build = { New-BlobGuiSysInfo } }
    )
}

# ---------------------------------------------------------------------------
#  Shared apply / undo flows
# ---------------------------------------------------------------------------
function Invoke-BlobGuiApply {
    param([array]$Tweaks, [string]$Tag = 'gui', [string[]]$ExtraLines = @(), [string]$Title, [switch]$ForceDanger)
    $Tweaks = @($Tweaks | Where-Object { $_ })
    if ($Tweaks.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing selected' -Lines @('{Gray}Select one or more settings first (+ on a card).'); return $false }
    if (-not $Title) { $Title = "Apply {0} optimization(s)?" -f $Tweaks.Count }
    $danger = $ForceDanger -or (@($Tweaks | Where-Object { $_.Risk -eq 'Advanced' }).Count -gt 0)
    $canRp = $Blob.IsAdmin -and -not $Blob.DryRun
    $rpText = if ($canRp) { 'Create a System Restore point first (recommended)' }
              elseif ($Blob.DryRun) { 'Create a System Restore point first (not available in dry run)' }
              else { 'Create a System Restore point first (requires administrator)' }
    $ok = Show-BlobGuiDialog -Title $Title -Subtitle 'These exact settings will change. Original values are saved first.' `
        -Lines ($ExtraLines + (Get-BlobTweakPreview $Tweaks)) -Danger:$danger -OkText 'Apply' `
        -CheckText $rpText -CheckDefault $canRp -CheckEnabled $canRp
    if (-not $ok) { return $false }
    if ($Blob.Gui.DialogCheck) { Invoke-BlobGuiRestorePointStep "BLOB OPTIMIZER - before $Tag" }
    Start-BlobGuiTask ("Applying {0} optimization(s)" -f $Tweaks.Count)
    $Blob.Gui.Collected = New-Object System.Collections.ArrayList
    $out = Invoke-BlobTweakCore -Tweaks $Tweaks -Tag $Tag -Log $Blob.GuiShared.LogCollect
    Add-BlobGuiLog "{Cyan}$($out.Summary)"
    Show-BlobGuiChangeSummary 'What changed'
    if ($out.NeedsExplorer) {
        if (Show-BlobGuiDialog -Title 'Restart Windows Explorer now?' -OkText 'Restart Explorer' -CancelText 'Later' -Lines @(
                '{Gray}Some changes appear only after Explorer restarts.',
                '{Gray}The taskbar and open Explorer windows close and reopen. Choose Later to restart or sign out yourself.')) {
            Restart-BlobExplorer; Add-BlobGuiLog '{Green}Explorer restarted.'
        }
    }
    Update-BlobGuiPage
    return $true
}

# Rich hover help for one tweak: explanation, risk, exact changes, undo.
function New-BlobTweakTooltip {
    param($Tweak)
    $r = $Blob.RiskInfo[$Tweak.Risk]
    $state = Get-BlobTweakState $Tweak
    $paras = @(
        (Get-BlobTweakExplanation $Tweak),
        "{$($r.Color)}$($r.Label){Gray} - $($r.Text)")
    if ($Tweak.Warning) { $paras += "{Yellow}Warning: $($Tweak.Warning)" }
    if ($Tweak.Note) { $paras += "{Gray}When it applies: $($Tweak.Note)" }
    $paras += $(if ($Tweak.Admin) { '{Yellow}Requires administrator rights (machine-wide setting).' } else { '{Green}Works without administrator rights (your account only).' })
    $paras += "{Gray}Current status: {White}$(switch ($state) { 'Applied' { 'applied' } 'Partial' { 'partly applied' } 'Default' { 'not applied (Windows default or your own setting)' } default { 'not applicable' } })"
    $paras += '{Gray}Undo: the original value is saved before the change; restore it with "Undo selected" or from the Restore page.'
    $mono = @(Get-BlobTweakPreview @($Tweak) | Select-Object -Skip 1 | Where-Object { $_ -match '^\{(Gray|DarkGray)\} {4}' -and $_ -notmatch 'Note:' })
    return New-BlobTooltipPanel -Title $Tweak.Name -Paragraphs $paras -Mono $mono -MonoTitle 'Exact changes (current -> new)'
}

function Invoke-BlobGuiUndo {
    param([array]$Tweaks)
    $Tweaks = @($Tweaks | Where-Object { $_ })
    if ($Tweaks.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing selected' -Lines @('{Gray}Select the items you want to restore first (+ on a card).'); return $false }
    $undo = Get-BlobUndoPlan $Tweaks
    if ($undo.Records.Count -eq 0) {
        Show-BlobGuiMessage -Title 'Nothing to restore' -Kind Warning -Lines ($undo.Lines + @('', '{Gray}This setting already matched before BLOB OPTIMIZER changed anything (Windows default or your own choice), so there is no saved original to go back to.'))
        return $false
    }
    if (-not (Confirm-BlobGui -Title 'Restore original values?' -Lines $undo.Lines -OkText 'Restore')) { return $false }
    Start-BlobGuiTask 'Restoring original values'
    $ok, $bad = Invoke-BlobRestoreCore -Records $undo.Records -Log { param($m) Add-BlobGuiLog $m }
    Add-BlobGuiLog ("{Cyan}Restore finished: {0} restored, {1} not restored." -f $ok, $bad)
    Update-BlobGuiPage
    return $true
}

# ---------------------------------------------------------------------------
#  Dashboard
# ---------------------------------------------------------------------------
# A large readout: label, big number, small note. Used in a row divided by rules.
function New-BlobReadout {
    param([string]$Label, [string]$Value, [string]$Note = '', [bool]$First = $false, [string]$ValueColor = 'Ink')
    $b = [Windows.Controls.Border]::new()
    $b.BorderBrush = Get-BlobBrush 'Rule'; $b.BorderThickness = $(if ($First) { '0' } else { '1,0,0,0' })
    $b.Padding = $(if ($First) { '0,2,24,2' } else { '24,2,24,2' })
    $sp = New-BlobStack
    [void]$sp.Children.Add((New-BlobText $Label.ToUpper() 12 'Ink3' 'Normal' -Display))
    [void]$sp.Children.Add((New-BlobText $Value 44 $ValueColor 'Light' '0,2,0,0' -Display))
    if ($Note) { [void]$sp.Children.Add((New-BlobText $Note 12.5 'Ink2')) }
    $b.Child = $sp
    return $b
}

function New-BlobSpecRow {
    param([string]$Label, [string]$Value, [string]$ValueColor = 'Ink')
    $b = [Windows.Controls.Border]::new()
    $b.BorderBrush = Get-BlobBrush 'Rule'; $b.BorderThickness = '0,0,0,1'; $b.Padding = '0,9'
    $d = [Windows.Controls.DockPanel]::new()
    $l = New-BlobText $Label 12.5 'Ink3'
    $l.Width = 120
    [void]$d.Children.Add($l)
    [void]$d.Children.Add((New-BlobText $Value 13 $ValueColor))
    $b.Child = $d
    return $b
}

# A full-width action row: title, one line of explanation, an arrow.
function New-BlobActionRow {
    param([string]$Title, [string]$Note, [scriptblock]$Action)
    $btn = [Windows.Controls.Button]::new()
    $btn.Style = $Blob.Gui.Window.FindResource('RowButton')
    $d = [Windows.Controls.DockPanel]::new()
    $arrow = New-BlobText ([string][char]0x2192) 19 'Ink' 'Normal' '12,0,6,0' -Display
    $arrow.VerticalAlignment = 'Center'
    [Windows.Controls.DockPanel]::SetDock($arrow, 'Right')
    [void]$d.Children.Add($arrow)
    $sp = New-BlobStack
    [void]$sp.Children.Add((New-BlobText $Title 15.5 'Ink' 'SemiBold' -Display))
    [void]$sp.Children.Add((New-BlobText $Note 12.5 'Ink2' 'Normal' '0,2,0,0'))
    [void]$d.Children.Add($sp)
    $btn.Content = $d
    Register-BlobClick $btn $Action
    return $btn
}

function New-BlobGuiDashboard {
    $root = New-BlobStack
    $si = $Blob.SysInfo
    $core = @(Get-BlobCoreTweaks)
    $applied = @($core | Where-Object { (Get-BlobTweakState $_) -eq 'Applied' }).Count
    $restorable = @(Get-BlobAppliedChanges).Count

    $drift = @(Get-BlobDrift)
    if ($drift.Count) { [void]$root.Children.Add((New-BlobDriftBar $drift)) }

    # Readouts
    $row = [Windows.Controls.Grid]::new()
    $row.Margin = '0,4,0,34'
    for ($i = 0; $i -lt 4; $i++) { $cd = [Windows.Controls.ColumnDefinition]::new(); $cd.Width = '*'; $row.ColumnDefinitions.Add($cd) }
    $cells = @()
    $cells += New-BlobReadout 'Tweaks on' "$applied/$($core.Count)" 'detected from current settings' $true
    $memNote = ''; $memVal = '-'
    try {
        $os = Get-BlobPrefetch 'OS'
        if (-not $os) { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop }
        $total = [double]$os.TotalVisibleMemorySize * 1KB; $used = $total - [double]$os.FreePhysicalMemory * 1KB
        $memVal = '{0:N0}%' -f (100 * $used / $total); $memNote = '{0} of {1} in use' -f (Format-BlobSize $used), (Format-BlobSize $total)
    } catch { }
    $cells += New-BlobReadout 'Memory' $memVal $memNote
    $diskVal = '-'; $diskNote = ''
    try {
        $c = @(Get-BlobPrefetch 'LogicalDisks') | Where-Object { $_.DeviceID -eq $env:SystemDrive } | Select-Object -First 1
        if (-not $c) { $c = Get-CimInstance Win32_LogicalDisk -Filter "DeviceID='$($env:SystemDrive)'" -ErrorAction Stop }
        $diskVal = Format-BlobSize $c.FreeSpace; $diskNote = "free on $($env:SystemDrive) of $(Format-BlobSize $c.Size)"
    } catch { }
    $cells += New-BlobReadout 'Disk' $diskVal $diskNote
    $cells += New-BlobReadout 'Undo' "$restorable" 'changes can be restored'
    for ($i = 0; $i -lt 4; $i++) { [Windows.Controls.Grid]::SetColumn($cells[$i], $i); [void]$row.Children.Add($cells[$i]) }
    [void]$root.Children.Add($row)

    # Two columns: this PC / start here
    $cols = [Windows.Controls.Grid]::new()
    $c0 = [Windows.Controls.ColumnDefinition]::new(); $c0.Width = '5*'
    $cg = [Windows.Controls.ColumnDefinition]::new(); $cg.Width = '44'
    $c1 = [Windows.Controls.ColumnDefinition]::new(); $c1.Width = '6*'
    $cols.ColumnDefinitions.Add($c0); $cols.ColumnDefinitions.Add($cg); $cols.ColumnDefinitions.Add($c1)

    $spec = New-BlobStack
    [void]$spec.Children.Add((New-BlobHeading 'This PC' '0,0,0,2'))
    [void]$spec.Children.Add((New-BlobSpecRow 'Windows' $si.OS))
    [void]$spec.Children.Add((New-BlobSpecRow 'Processor' $si.CPU))
    [void]$spec.Children.Add((New-BlobSpecRow 'Graphics' $si.GPU))
    [void]$spec.Children.Add((New-BlobSpecRow 'Memory' $si.RAM))
    [void]$spec.Children.Add((New-BlobSpecRow 'Power plan' (Get-BlobActivePowerPlan).Name))
    [void]$spec.Children.Add((New-BlobSpecRow 'Computer' "$($si.Host), up $($si.Uptime)"))
    [void]$spec.Children.Add((New-BlobSpecRow 'Rights' $(if ($Blob.IsAdmin) { 'Administrator' } else { 'Limited - system settings are read-only' }) $(if ($Blob.IsAdmin) { 'Ink' } else { 'SignalText' })))
    [Windows.Controls.Grid]::SetColumn($spec, 0); [void]$cols.Children.Add($spec)

    $start = New-BlobStack
    [void]$start.Children.Add((New-BlobHeading 'Start here' '0,0,0,2'))
    [void]$start.Children.Add((New-BlobActionRow 'Apply a preset' 'Minimal, Standard or Advanced. Every value is shown before it changes.' { Show-BlobGuiPage 'presets' }))
    [void]$start.Children.Add((New-BlobActionRow 'Pick individual tweaks' "$($core.Count) settings, sorted by what they affect and how risky they are." { Show-BlobGuiPage 'optimize' }))
    [void]$start.Children.Add((New-BlobActionRow 'Review your privacy' "$(@(Get-BlobPrivacyItems).Count) privacy settings in $($Blob.PrivacyGroups.Count) sections, each explained with a clear recommendation." { Show-BlobGuiPage 'privacy' }))
    [void]$start.Children.Add((New-BlobActionRow 'Remove an app completely' 'Its own uninstaller, then the folders and keys it leaves behind.' { Show-BlobGuiPage 'apps' }))
    [void]$start.Children.Add((New-BlobActionRow 'Install apps' 'Popular apps in one go with winget, which is built into Windows.' { Show-BlobGuiPage 'install' }))
    [void]$start.Children.Add((New-BlobActionRow 'Measure before and after' 'Boot times from Windows itself, plus snapshots to compare.' { Show-BlobGuiPage 'measure' }))
    [void]$start.Children.Add((New-BlobActionRow 'Clear temporary files' 'Measures caches and temp folders first, then asks.' { Show-BlobGuiPage 'cleanup' }))
    [void]$start.Children.Add((New-BlobActionRow 'Make a restore point' 'A Windows-level safety net before you change anything big.' { Invoke-BlobGuiRestorePoint }))
    [void]$start.Children.Add((New-BlobActionRow 'Review or undo changes' 'Every change BLOB made, with its original value.' { Show-BlobGuiPage 'restore' }))
    [Windows.Controls.Grid]::SetColumn($start, 2); [void]$cols.Children.Add($start)
    [void]$root.Children.Add($cols)

    [void]$root.Children.Add((New-BlobText 'BLOB never touches Microsoft Defender, Windows Firewall, SmartScreen, UAC or Windows Update.' 12 'Ink3' 'Normal' '0,30,0,0'))
    return $root
}

# ---------------------------------------------------------------------------
#  Presets
# ---------------------------------------------------------------------------
function New-BlobGuiPresets {
    $root = New-BlobStack
    $grid = [Windows.Controls.Primitives.UniformGrid]::new()
    $grid.Columns = 3; $grid.Margin = '0,6,0,0'
    $presets = @(Get-BlobPresets)
    $maxRisk = @{ MINIMAL = 'Minimal'; STANDARD = 'Standard'; ADVANCED = 'Advanced' }
    for ($i = 0; $i -lt $presets.Count; $i++) {
        $p = $presets[$i]
        $tw = @($p.Ids | ForEach-Object { Get-BlobTweak $_ } | Where-Object { $_ })
        $on = @($tw | Where-Object { (Get-BlobTweakState $_) -eq 'Applied' }).Count
        $col = [Windows.Controls.Border]::new()
        $col.BorderBrush = Get-BlobBrush 'Rule'
        $col.BorderThickness = $(if ($i -eq 0) { '0' } else { '1,0,0,0' })
        $col.Padding = $(if ($i -eq 0) { '0,0,28,0' } else { '28,0,28,0' })
        $d = [Windows.Controls.DockPanel]::new()

        $btn = New-BlobButton 'Review and apply' ([scriptblock]::Create("Invoke-BlobGuiPreset '$($p.Name -replace "'", "''")'")) $(if ($i -eq 1) { 'Accent' } else { 'Normal' })
        $btn.HorizontalAlignment = 'Stretch'; $btn.Margin = '0,18,0,0'; $btn.Padding = '14,9'
        [Windows.Controls.DockPanel]::SetDock($btn, 'Bottom')
        [void]$d.Children.Add($btn)

        $sp = New-BlobStack
        $name = $p.Name.Substring(0, 1) + $p.Name.Substring(1).ToLower()
        [void]$sp.Children.Add((New-BlobText $name 30 'Ink' 'SemiBold' -Display))
        $meta = New-BlobStack 'Horizontal' '0,6,0,14'
        if ($maxRisk.ContainsKey($p.Name)) { [void]$meta.Children.Add((New-BlobRiskBadge $maxRisk[$p.Name])) }
        [void]$meta.Children.Add((New-BlobText "  $($tw.Count) tweaks, $on already on" 12 'Ink3' 'Normal' '10,0,0,0' -Mono))
        [void]$sp.Children.Add($meta)
        $desc = New-BlobText $p.Description 13.5 'Ink2'
        $desc.MinHeight = 60
        [void]$sp.Children.Add($desc)
        if ($p.Warning) { [void]$sp.Children.Add((New-BlobText $p.Warning 12.5 'SignalText' 'Normal' '0,10,0,0')) }
        [void]$sp.Children.Add((New-BlobText 'INCLUDES' 11.5 'Ink3' 'Normal' '0,18,0,6' -Display))
        foreach ($t in $tw) {
            $line = [Windows.Controls.DockPanel]::new()
            $line.Margin = '0,0,0,5'
            $st = Get-BlobTweakState $t
            $mark = [Windows.Shapes.Rectangle]::new()
            $mark.Width = 8; $mark.Height = 8; $mark.Margin = '0,5,10,0'; $mark.VerticalAlignment = 'Top'
            $mark.Stroke = $(if ($t.Risk -eq 'Advanced') { Get-BlobBrush 'Signal' } else { Get-BlobBrush 'Ink' }); $mark.StrokeThickness = 1.2
            $mark.Fill = $(if ($st -eq 'Applied') { $mark.Stroke } else { [Windows.Media.Brushes]::Transparent })
            [void]$line.Children.Add($mark)
            [void]$line.Children.Add((New-BlobText $t.Name 12.5 'Ink'))
            [void]$sp.Children.Add($line)
        }
        [void]$sp.Children.Add((New-BlobText 'Filled = already on.  Outline = will change.  Orange = higher risk.' 11.5 'Ink3' 'Normal' '0,10,0,0'))
        [void]$d.Children.Add($sp)
        $col.Child = $d
        [void]$grid.Children.Add($col)
    }
    [void]$root.Children.Add($grid)
    [void]$root.Children.Add((New-BlobText 'Personal-preference tweaks are never part of a preset. Everything a preset changes can be undone from Restore.' 12 'Ink3' 'Normal' '0,28,0,0'))
    return $root
}

function Invoke-BlobGuiRestorePoint {
    if (-not $Blob.IsAdmin) { Show-BlobGuiAdminRequired 'Creating a System Restore point is a machine-wide operation.'; return }
    if (-not (Confirm-BlobGui -Title 'Create a System Restore point?' -OkText 'Create' -Lines @('{Gray}This can take a minute. System Protection must be on for the system drive.', '{DarkGray}Windows creates at most one restore point per 24 hours by default.'))) { return }
    Start-BlobGuiTask 'Creating System Restore point'
    Add-BlobGuiLog (New-BlobRestorePoint 'BLOB OPTIMIZER manual restore point')
}

function Invoke-BlobGuiPreset {
    param([string]$Name)
    $p = @(Get-BlobPresets) | Where-Object { $_.Name -eq $Name } | Select-Object -First 1
    if (-not $p) { return }
    $tw = @($p.Ids | ForEach-Object { Get-BlobTweak $_ } | Where-Object { $_ })
    $extra = @()
    if ($p.Warning) { $extra = @("{Yellow}$($p.Warning)", '') }
    $null = Invoke-BlobGuiApply -Tweaks $tw -Tag "preset-$($p.Name)" -ExtraLines $extra -Title "Apply the $($p.Name) preset ($($tw.Count) optimizations)?" -ForceDanger:($p.Name -match 'ADVANCED')
}

# ---------------------------------------------------------------------------
#  Optimizations: all settings as cards with switches
# ---------------------------------------------------------------------------
$Blob.GuiCategories = @('All', 'FPS & Latency', 'Performance', 'Network', 'Quality of Life', 'Privacy & Security')

$Blob.GuiRiskFilters = [ordered]@{ All = 'All'; Minimal = 'Low risk'; Standard = 'Medium risk'; Advanced = 'High risk'; Optional = 'Preference' }

function Get-BlobGuiFilteredTweaks {
    $list = @(Get-BlobCoreTweaks)
    if ($Blob.Gui.OptFilter -and $Blob.Gui.OptFilter -ne 'All') { $list = @($list | Where-Object { $_.Category -eq $Blob.Gui.OptFilter }) }
    if ($Blob.Gui.OptRisk -and $Blob.Gui.OptRisk -ne 'All') { $list = @($list | Where-Object { $_.Risk -eq $Blob.Gui.OptRisk }) }
    $q = [string]$Blob.Gui.OptSearch
    if ($q.Trim()) {
        $q = $q.Trim()
        $list = @($list | Where-Object { $_.Name -like "*$q*" -or $_.Description -like "*$q*" -or $_.Category -like "*$q*" })
    }
    return $list
}

function New-BlobChip {
    param([string]$Text)
    return (New-BlobText $Text.ToUpper() 11 'Ink3' 'Normal' -Display)
}

# Plain-text markers: ! warning, ADMIN lock, > search.
function New-BlobGlyph {
    param([int]$Code, [string]$Color = 'Gray', [double]$Size = 13)
    $map = @{ 0xE7BA = '!'; 0xE72E = 'ADMIN'; 0xE721 = [string][char]0x2315; 0xE710 = '+'; 0xE73E = 'x' }
    $t = New-BlobText $(if ($map.ContainsKey($Code)) { $map[$Code] } else { '*' }) $Size $Color 'SemiBold' -Display
    $t.VerticalAlignment = 'Center'
    return $t
}

# One tweak as a ruled row: [marker][switch][name + description][risk][state][?]
function New-BlobTweakCard {
    param($Tweak, [string]$State, [string]$Pending)
    $state = $State
    $wantOn = if ($Pending) { $Pending -eq 'On' } else { $state -eq 'Applied' }
    $row = [Windows.Controls.Border]::new()
    $row.BorderBrush = Get-BlobBrush 'Rule'; $row.BorderThickness = '0,0,0,1'
    $row.Background = if ($Pending) { Get-BlobBrush 'SignalSoft' } else { [Windows.Media.Brushes]::Transparent }
    $row.Uid = $(if ($Pending) { 'P' } else { '' })
    $row.Add_MouseEnter({ param($s, $e) if ($s.Uid -ne 'P') { $s.Background = Get-BlobBrush 'Hover' } })
    $row.Add_MouseLeave({ param($s, $e) if ($s.Uid -ne 'P') { $s.Background = [Windows.Media.Brushes]::Transparent } })
    $g = [Windows.Controls.Grid]::new()
    foreach ($w in @('4', '58', '*', '96', '112', '34')) { $cd = [Windows.Controls.ColumnDefinition]::new(); $cd.Width = $w; $g.ColumnDefinitions.Add($cd) }

    $marker = [Windows.Controls.Border]::new()
    $marker.Background = if ($Pending) { Get-BlobBrush 'Signal' } else { [Windows.Media.Brushes]::Transparent }
    [void]$g.Children.Add($marker)

    $sw = [Windows.Controls.CheckBox]::new()
    $sw.Style = $Blob.Gui.Window.FindResource('Switch')
    $sw.IsChecked = $wantOn
    $sw.VerticalAlignment = 'Center'; $sw.HorizontalAlignment = 'Center'
    $row.Tag = $sw
    if ($Tweak.Admin -and -not $Blob.IsAdmin) {
        $sw.IsEnabled = $false
        $holder = [Windows.Controls.Border]::new()
        $holder.Background = [Windows.Media.Brushes]::Transparent; $holder.VerticalAlignment = 'Center'
        $holder.Child = $sw
        Set-BlobTooltip $holder (New-BlobTooltipPanel -Title 'Needs administrator rights' -Paragraphs @('This is a machine-wide setting. Start BLOB again and choose Yes in the Windows permission prompt to change it.'))
        [Windows.Controls.Grid]::SetColumn($holder, 1); [void]$g.Children.Add($holder)
    } else {
        $sw.DataContext = $Tweak.Id
        Register-BlobClick $sw $Blob.GuiShared.SwitchClick
        [Windows.Controls.Grid]::SetColumn($sw, 1); [void]$g.Children.Add($sw)
    }

    $text = New-BlobStack
    $text.Margin = '6,0,16,0'; $text.VerticalAlignment = 'Center'
    $title = New-BlobStack 'Horizontal'
    [void]$title.Children.Add((New-BlobText $Tweak.Name 14 'Ink' 'SemiBold'))
    if ($Tweak.Admin) { $ad = New-BlobBadge 'ADMIN' 'Ink3'; $ad.Margin = '10,1,0,0'; [void]$title.Children.Add($ad) }
    [void]$text.Children.Add($title)
    $desc = New-BlobText $Tweak.Description 12.5 'Ink2' 'Normal' '0,2,0,0'
    $desc.TextWrapping = 'NoWrap'; $desc.TextTrimming = 'CharacterEllipsis'
    [void]$text.Children.Add($desc)
    [Windows.Controls.Grid]::SetColumn($text, 2); [void]$g.Children.Add($text)

    $risk = New-BlobRiskBadge $Tweak.Risk
    [Windows.Controls.Grid]::SetColumn($risk, 3); [void]$g.Children.Add($risk)

    $arrow = [string][char]0x2192
    $stText = if ($Pending -eq 'On') { "$arrow ON" } elseif ($Pending -eq 'Off') { "$arrow OFF" } else { switch ($state) { 'Applied' { 'On' } 'Partial' { 'Partly on' } default { 'Off' } } }
    $stColor = if ($Pending) { 'SignalText' } elseif ($state -eq 'Applied') { 'Ink' } elseif ($state -eq 'Partial') { 'Ink2' } else { 'Ink3' }
    $st = New-BlobText $stText 13 $stColor $(if ($Pending -or $state -eq 'Applied') { 'SemiBold' } else { 'Normal' }) -Display
    $st.VerticalAlignment = 'Center'
    [Windows.Controls.Grid]::SetColumn($st, 4); [void]$g.Children.Add($st)

    $help = New-BlobHelpIcon -Builder $Blob.GuiShared.TweakTip
    $help.DataContext = $Tweak.Id
    $help.Margin = '0'; $help.HorizontalAlignment = 'Center'
    [Windows.Controls.Grid]::SetColumn($help, 5); [void]$g.Children.Add($help)

    $g.Margin = '0,10,0,10'
    $row.Child = $g
    return $row
}

# Returns the row for a tweak, reusing the cached element when its state and
# pending choice are unchanged (so switching, searching and filtering stay instant).
function Get-BlobGuiCard {
    param($Tweak, [string]$State)
    if (-not $Blob.Gui.CardCache) { $Blob.Gui.CardCache = @{} }
    $pend = [string]$Blob.Gui.Pending[$Tweak.Id]
    $c = $Blob.Gui.CardCache[$Tweak.Id]
    if (-not ($c -and $c.State -eq $State -and $c.Pending -eq $pend)) {
        $el0 = if ($Tweak.Section -eq 'PrivacyCenter') { New-BlobPrivacyRow $Tweak $State $pend } else { New-BlobTweakCard $Tweak $State $pend }
        $c = @{ Element = $el0; State = $State; Pending = $pend }
        $Blob.Gui.CardCache[$Tweak.Id] = $c
    }
    $el = $c.Element
    if ($el.Parent -is [Windows.Controls.Panel]) { $el.Parent.Children.Remove($el) }
    if ($el.Tag -is [Windows.Controls.CheckBox]) { $el.Tag.IsChecked = $(if ($pend) { $pend -eq 'On' } else { $State -eq 'Applied' }) }
    return $el
}

function New-BlobGroupHeader {
    param([string]$Title, [string]$Note)
    $b = [Windows.Controls.Border]::new()
    $b.BorderBrush = Get-BlobBrush 'Ink'; $b.BorderThickness = '0,0,0,1.5'; $b.Padding = '0,0,0,6'; $b.Margin = '0,26,0,0'
    $d = [Windows.Controls.DockPanel]::new()
    $n = New-BlobText $Note 12 'Ink3' 'Normal' -Mono
    $n.VerticalAlignment = 'Bottom'
    [Windows.Controls.DockPanel]::SetDock($n, 'Right')
    [void]$d.Children.Add($n)
    [void]$d.Children.Add((New-BlobText $Title 18 'Ink' 'SemiBold' -Display))
    $b.Child = $d
    return $b
}

function Update-BlobGuiCardGrid {
    $g = $Blob.Gui.CardGrid
    if (-not $g) { return }
    if ($Blob.Gui.Current -eq 'privacy') { Update-BlobGuiPrivacyList; return }
    $offset = $Blob.Gui.PageScroll.VerticalOffset
    $g.Children.Clear()
    $states = @{}
    foreach ($t in (Get-BlobCoreTweaks)) { $states[$t.Id] = Get-BlobTweakState $t }
    $list = @(Get-BlobGuiFilteredTweaks)
    foreach ($cat in @($Blob.GuiCategories | Where-Object { $_ -ne 'All' })) {
        $inCat = @($list | Where-Object { $_.Category -eq $cat })
        if ($inCat.Count -eq 0) { continue }
        $onCount = @($inCat | Where-Object { $states[$_.Id] -eq 'Applied' }).Count
        [void]$g.Children.Add((New-BlobGroupHeader $cat "$onCount of $($inCat.Count) on"))
        foreach ($t in $inCat) { [void]$g.Children.Add((Get-BlobGuiCard $t $states[$t.Id])) }
    }
    if ($list.Count -eq 0) { [void]$g.Children.Add((New-BlobText 'Nothing matches these filters.' 14 'Ink3' 'Normal' '0,30,0,0')) }
    $active = @($states.Values | Where-Object { $_ -eq 'Applied' }).Count
    $n = $Blob.Gui.Pending.Count
    $dot = [string][char]0x00B7
    $Blob.Gui.CardCount.Text = "$($list.Count) shown  $dot  $active of $($states.Count) on  $dot  $n waiting"
    Update-BlobGuiPendingBar
    $Blob.Gui.PageScroll.UpdateLayout(); $Blob.Gui.PageScroll.ScrollToVerticalOffset($offset)
}

# A switch only records what you want; nothing changes until Review and apply.
function Switch-BlobGuiTweak {
    param([string]$Id)
    $t = Get-BlobTweak $Id
    if (-not $t) { return }
    $state = Get-BlobTweakState $t
    $cur = $Blob.Gui.Pending[$Id]
    $isOn = if ($cur) { $cur -eq 'On' } else { $state -eq 'Applied' }
    if (-not $isOn) {
        if ($state -eq 'Applied') { $Blob.Gui.Pending.Remove($Id) } else { $Blob.Gui.Pending[$Id] = 'On' }
    } else {
        if ($state -eq 'Applied') { $Blob.Gui.Pending[$Id] = 'Off' } else { $Blob.Gui.Pending.Remove($Id) }
    }
    Update-BlobGuiCardGrid
}

function Invoke-BlobGuiApplyPending {
    $on = @($Blob.Gui.Pending.Keys | Where-Object { $Blob.Gui.Pending[$_] -eq 'On' } | ForEach-Object { Get-BlobTweak $_ } | Where-Object { $_ })
    $off = @($Blob.Gui.Pending.Keys | Where-Object { $Blob.Gui.Pending[$_] -eq 'Off' } | ForEach-Object { Get-BlobTweak $_ } | Where-Object { $_ })
    if ($on.Count + $off.Count -eq 0) {
        Show-BlobGuiMessage -Title 'Nothing to apply' -Lines @('{Gray}Switch the tweaks you want on or off first.', '{Gray}Nothing changes until you review and apply.')
        return
    }
    $lines = @()
    if ($on.Count) {
        $lines += "{Cyan}ACTIVATE ($($on.Count))"
        $lines += @(Get-BlobTweakPreview $on | Select-Object -SkipLast 2)
    }
    $undo = $null
    if ($off.Count) {
        $undo = Get-BlobUndoPlan $off
        $lines += "{Cyan}DEACTIVATE ($($off.Count)) - restore the values saved before they were changed"
        $lines += $undo.Lines
        $lines += ''
    }
    $lines += '{Gray}Original values are saved to the change journal before anything is modified.'
    $total = $on.Count + $off.Count
    $danger = @($on | Where-Object { $_.Risk -eq 'Advanced' }).Count -gt 0
    $canRp = $Blob.IsAdmin -and -not $Blob.DryRun
    $rpText = if ($canRp) { 'Create a System Restore point first (recommended)' } elseif ($Blob.DryRun) { 'Create a System Restore point first (not available in dry run)' } else { 'Create a System Restore point first (requires administrator)' }
    $noun = if ($total -eq 1) { 'change' } else { 'changes' }
    $ok = Show-BlobGuiDialog -Title "Apply $total ${noun}?" -Subtitle 'These exact settings will change.' -Lines $lines -Danger:$danger `
        -OkText "Apply $total $noun" -CheckText $rpText -CheckDefault $canRp -CheckEnabled $canRp
    if (-not $ok) { return }
    if ($Blob.Gui.DialogCheck) { Invoke-BlobGuiRestorePointStep 'BLOB OPTIMIZER - before applying changes' }
    $needsExplorer = $false
    $Blob.Gui.Collected = New-Object System.Collections.ArrayList
    if ($on.Count) {
        Start-BlobGuiTask "Activating $($on.Count) setting(s)"
        $out = Invoke-BlobTweakCore -Tweaks $on -Tag 'changes' -Log $Blob.GuiShared.LogCollect
        Add-BlobGuiLog "{Cyan}$($out.Summary)"
        $needsExplorer = $out.NeedsExplorer
    }
    if ($undo -and $undo.Records.Count) {
        Start-BlobGuiTask "Deactivating $($off.Count) setting(s)"
        $a, $b = Invoke-BlobRestoreCore -Records $undo.Records -Log $Blob.GuiShared.LogCollect
        Add-BlobGuiLog ("{Cyan}Deactivated: {0} value(s) restored, {1} not restored." -f $a, $b)
        if (@($off | Where-Object { $_.RestartExplorer }).Count) { $needsExplorer = $true }
    }
    $Blob.Gui.Pending.Clear()
    Show-BlobGuiChangeSummary 'What changed'
    if ($needsExplorer -and -not $Blob.DryRun) {
        if (Show-BlobGuiDialog -Title 'Restart Windows Explorer now?' -OkText 'Restart Explorer' -CancelText 'Later' -Lines @(
                '{Gray}Some changes appear only after Explorer restarts.',
                '{Gray}The taskbar and open Explorer windows close and reopen. Choose Later to restart or sign out yourself.')) {
            Restart-BlobExplorer; Add-BlobGuiLog '{Green}Explorer restarted.'
        }
    }
    Update-BlobGuiPage
}

# Text filter: active one in ink with a signal underline.
function New-BlobGuiFilterChip {
    param([string]$Text, [bool]$Active, [scriptblock]$Action)
    $b = [Windows.Controls.Button]::new()
    $b.Style = $Blob.Gui.Window.FindResource('ChipButton')
    $b.Content = $Text
    if ($Active) { $b.Foreground = Get-BlobBrush 'Ink'; $b.BorderBrush = Get-BlobBrush 'Signal'; $b.FontWeight = 'SemiBold' }
    Register-BlobClick $b $Action
    return $b
}

function New-BlobFilterRow {
    param([string]$Label, $Chips)
    $d = [Windows.Controls.DockPanel]::new()
    $d.Margin = '0,0,0,2'
    $l = New-BlobText $Label.ToUpper() 11.5 'Ink3' 'Normal' '0,5,0,0' -Display
    $l.Width = 86
    [void]$d.Children.Add($l)
    [void]$d.Children.Add($Chips)
    return $d
}

function New-BlobGuiOptimizations {
    $root = New-BlobStack
    $top = [Windows.Controls.DockPanel]::new()

    # Search (underline field with a hint)
    $sbox = [Windows.Controls.Grid]::new()
    $sbox.Width = 240; $sbox.VerticalAlignment = 'Top'; $sbox.Margin = '24,0,0,0'
    $search = [Windows.Controls.TextBox]::new()
    $search.Text = [string]$Blob.Gui.OptSearch; $search.Padding = '22,5,2,5'
    $hint = New-BlobText 'Search' 13.5 'Ink3' 'Normal' '23,6,0,0'
    $hint.IsHitTestVisible = $false
    if ($search.Text) { $hint.Visibility = 'Collapsed' }
    $glass = New-BlobGlyph 0xE721 'Ink2' 15
    $glass.Margin = '1,0,0,2'; $glass.HorizontalAlignment = 'Left'; $glass.IsHitTestVisible = $false
    [void]$sbox.Children.Add($search); [void]$sbox.Children.Add($hint); [void]$sbox.Children.Add($glass)
    $Blob.Gui.SearchHint = $hint
    $search.Add_TextChanged({
            param($s, $e)
            $Blob.Gui.OptSearch = $s.Text
            $Blob.Gui.SearchHint.Visibility = if ($s.Text) { 'Collapsed' } else { 'Visible' }
            Update-BlobGuiCardGrid
        })
    [Windows.Controls.DockPanel]::SetDock($sbox, 'Right')
    [void]$top.Children.Add($sbox)

    $filters = New-BlobStack
    $cats = [Windows.Controls.WrapPanel]::new()
    foreach ($c in $Blob.GuiCategories) {
        $count = if ($c -eq 'All') { @(Get-BlobCoreTweaks).Count } else { @(Get-BlobCoreTweaks | Where-Object { $_.Category -eq $c }).Count }
        [void]$cats.Children.Add((New-BlobGuiFilterChip "$c $count" ($Blob.Gui.OptFilter -eq $c) ([scriptblock]::Create("`$Blob.Gui.OptFilter = '$c'; Show-BlobGuiPage 'optimize' -Rebuild"))))
    }
    [void]$filters.Children.Add((New-BlobFilterRow 'Area' $cats))
    if (-not $Blob.Gui.OptRisk) { $Blob.Gui.OptRisk = 'All' }
    $risks = [Windows.Controls.WrapPanel]::new()
    foreach ($k in $Blob.GuiRiskFilters.Keys) {
        $count = if ($k -eq 'All') { @(Get-BlobCoreTweaks).Count } else { @(Get-BlobCoreTweaks | Where-Object { $_.Risk -eq $k }).Count }
        [void]$risks.Children.Add((New-BlobGuiFilterChip "$($Blob.GuiRiskFilters[$k]) $count" ($Blob.Gui.OptRisk -eq $k) ([scriptblock]::Create("`$Blob.Gui.OptRisk = '$k'; Show-BlobGuiPage 'optimize' -Rebuild"))))
    }
    [void]$filters.Children.Add((New-BlobFilterRow 'Risk' $risks))
    [void]$top.Children.Add($filters)
    [void]$root.Children.Add($top)

    $info = [Windows.Controls.DockPanel]::new()
    $info.Margin = '0,10,0,0'
    $legend = New-BlobRiskLegend
    [Windows.Controls.DockPanel]::SetDock($legend, 'Right')
    [void]$info.Children.Add($legend)
    $Blob.Gui.CardCount = New-BlobText '' 12 'Ink3' 'Normal' -Mono
    $Blob.Gui.CardCount.VerticalAlignment = 'Center'
    [void]$info.Children.Add($Blob.Gui.CardCount)
    [void]$root.Children.Add($info)

    $list = New-BlobStack
    $Blob.Gui.CardGrid = $list
    [void]$root.Children.Add($list)

    [void]$root.Children.Add((New-BlobHeading 'Related tools' '0,36,0,4'))
    $toolDefs = @(
        @('Memory and resources', 'What is using RAM and CPU right now.', { Show-BlobGuiMessage -Title 'Memory and resources' -Lines (Get-BlobMemoryInfo) }),
        @('Gaming status', 'Game Mode, recording, GPU scheduling and drivers at a glance.', { Show-BlobGuiMessage -Title 'Gaming status' -Lines (Get-BlobGamingStatus) }),
        @('Privacy overview', 'Your diagnostic-data level and every privacy setting.', { Show-BlobGuiMessage -Title 'Privacy overview' -Lines (Get-BlobPrivacyOverview) }),
        @('Optimize drives', 'TRIM for SSDs, defragmentation for hard drives (Windows Optimize-Volume).', {
                if (-not $Blob.IsAdmin) { Show-BlobGuiAdminRequired 'Drive optimization needs administrator rights.'; return }
                if (Confirm-BlobGui -Title 'Optimize all fixed drives now?' -OkText 'Optimize' -Lines @('{Gray}Uses the built-in Windows optimizer (Optimize-Volume): SSDs get TRIM, hard drives are defragmented.', '{Gray}Safe to run. Hard drive defragmentation can take a long time; the window waits until it finishes.')) {
                    Start-BlobGuiTask 'Optimizing drives'; Invoke-BlobOptimizeDrives -Log { param($m) Add-BlobGuiLog $m } } }),
        @('Restart Explorer', 'Makes taskbar and Explorer changes show up without signing out.', { if (Confirm-BlobGui -Title 'Restart Windows Explorer?' -OkText 'Restart Explorer' -Lines @('{Gray}The taskbar and open Explorer windows close and reopen.')) { Restart-BlobExplorer; Add-BlobGuiLog '{White}Explorer restarted.' } }))
    foreach ($d in $toolDefs) { [void]$root.Children.Add((New-BlobActionRow $d[0] $d[1] $d[2])) }

    Set-BlobGuiPageActions @(
        (New-BlobButton 'Choose all shown' {
                foreach ($t in (Get-BlobGuiFilteredTweaks)) {
                    if ($t.Admin -and -not $Blob.IsAdmin) { continue }
                    if ((Get-BlobTweakState $t) -ne 'Applied') { $Blob.Gui.Pending[$t.Id] = 'On' } elseif ($Blob.Gui.Pending[$t.Id] -eq 'Off') { $Blob.Gui.Pending.Remove($t.Id) }
                }
                Update-BlobGuiCardGrid } -ToolTip 'Mark every tweak currently shown to be switched on. Nothing changes until you review and apply.' -Margin '0'))
    Update-BlobGuiCardGrid
    return $root
}

# ---------------------------------------------------------------------------
#  System Info
# ---------------------------------------------------------------------------
function New-BlobGuiSysInfo {
    $lines = Get-BlobSystemInfoLines
    $Blob.Gui.P = @{ Text = (($lines | ForEach-Object { Get-BlobPlainText $_ }) -join [Environment]::NewLine) }
    Set-BlobGuiPageActions @((New-BlobButton 'Copy to clipboard' {
                Set-Clipboard -Value $Blob.Gui.P.Text; Add-BlobGuiLog '{Green}System information copied to the clipboard.' } -Margin '0'))
    $root = New-BlobStack
    $current = $null
    foreach ($l in $lines) {
        if ($l -match '^\{Cyan\}') {
            if ($current) { [void]$root.Children.Add((New-BlobCard $current)) }
            [void]$root.Children.Add((New-BlobHeading (Get-BlobPlainText $l)))
            $current = New-BlobStack
            continue
        }
        if (-not $current) { $current = New-BlobStack }
        if ($l) { [void]$current.Children.Add((ConvertTo-BlobTextBlock $l -Mono -Size 12.5)) }
    }
    if ($current) { [void]$root.Children.Add((New-BlobCard $current)) }
    return $root
}

# ---------------------------------------------------------------------------
#  External tools
# ---------------------------------------------------------------------------
function New-BlobGuiTools {
    $root = New-BlobStack
    $warn = New-BlobStack
    [void]$warn.Children.Add((New-BlobText 'Third-party software' 14 'Yellow' 'SemiBold'))
    [void]$warn.Children.Add((New-BlobText 'These tools are made by other developers. BLOB OPTIMIZER only starts them for you: it shows the official download address first, verifies digital signatures where possible, and records that you launched them. Changes made inside these tools are NOT tracked and cannot be undone from the Restore page - use their own undo options and a System Restore point.' 12.5 'Gray' 'Normal' '0,4,0,0'))
    [void]$root.Children.Add((New-BlobCard $warn))
    $wrap = [Windows.Controls.WrapPanel]::new()
    foreach ($t in $Blob.ExternalTools) {
        $s = New-BlobStack
        $head = New-BlobStack 'Horizontal'
        [void]$head.Children.Add((New-BlobText $t.Name 17 'White' 'SemiBold'))
        [void]$head.Children.Add((New-BlobHelpIcon (New-BlobTooltipPanel -Title $t.Name -Paragraphs (Get-BlobExternalToolLines $t))))
        [void]$s.Children.Add($head)
        [void]$s.Children.Add((New-BlobText $t.Publisher 12 'DarkGray' 'Normal' '0,2,0,10'))
        [void]$s.Children.Add((New-BlobText $t.Summary 13 'Gray'))
        [void]$s.Children.Add((New-BlobText "Source: $($t.Url)" 11.5 'DarkGray' 'Normal' '0,10,0,0'))
        if ($t.Kind -eq 'Exe') { [void]$s.Children.Add((New-BlobText "Signature must be valid and from $($t.Signer) before it runs." 11.5 'DarkGray' 'Normal' '0,2,0,0')) }
        $btns = New-BlobStack 'Horizontal' '0,14,0,0'
        [void]$btns.Children.Add((New-BlobButton 'Launch' ([scriptblock]::Create("Invoke-BlobGuiExternalTool '$($t.Id)'")) 'Accent'))
        [void]$btns.Children.Add((New-BlobButton 'Website' ([scriptblock]::Create("Start-Process '$($t.Home)'"))))
        [void]$s.Children.Add($btns)
        [void]$wrap.Children.Add((New-BlobCard $s '0,0,14,14' '20,18' 440))
    }
    [void]$root.Children.Add($wrap)
    return $root
}

function Invoke-BlobGuiExternalTool {
    param([string]$Id)
    $t = Get-BlobExternalTool $Id
    if (-not $t) { return }
    $canRp = $Blob.IsAdmin -and -not $Blob.DryRun
    $rpText = if ($canRp) { 'Create a System Restore point first (strongly recommended)' } else { 'Create a System Restore point first (requires administrator)' }
    $ok = Show-BlobGuiDialog -Title "Launch $($t.Name)?" -Subtitle 'Third-party software - read before continuing' -Lines (Get-BlobExternalToolLines $t) `
        -OkText 'Launch' -Kind 'Warning' -CheckText $rpText -CheckDefault $canRp -CheckEnabled $canRp
    if (-not $ok) { return }
    if ($Blob.Gui.DialogCheck) { Invoke-BlobGuiRestorePointStep "BLOB OPTIMIZER - before $($t.Name)" }
    Start-BlobGuiTask "Launching $($t.Name)"
    $null = Start-BlobExternalTool -Tool $t -Log { param($m) Add-BlobGuiLog $m }
}
#endregion

#region ---- GuiSystem.ps1 ----
# ============================================================================
#  BLOB OPTIMIZER - GuiSystem.ps1
#  Window pages: Services, Startup, Cleanup, Network, Power, Restore.
# ============================================================================

# ---------------------------------------------------------------------------
#  Services
# ---------------------------------------------------------------------------
function Get-BlobGuiServiceRows {
    param([string]$Filter = 'Recommended review', [string]$Search = '')
    $guide = @{}
    foreach ($g in $Blob.ServiceGuide) { $guide[$g.Name] = $g }
    $rows = foreach ($s in (Get-BlobServiceList).Values) {
        $g = $guide[$s.Name]
        if ($Filter -eq 'Recommended review' -and -not $g) { continue }
        if ($Filter -eq 'Running only' -and $s.State -ne 'Running') { continue }
        if ($Search -and -not ($s.DisplayName -like "*$Search*" -or $s.Name -like "*$Search*")) { continue }
        $start = Get-BlobServiceStartup $s.Name
        if (-not $start) { $start = [string]$s.StartMode }
        $info = if ($g) { $g.Info } elseif ($s.Description) { ($s.Description -replace '\s+', ' ') } else { 'No description provided.' }
        [pscustomobject]@{
            DisplayName = $s.DisplayName; Name = $s.Name; Status = [string]$s.State; Startup = $start
            Recommended = $(if ($g) { $g.Rec } else { '' })
            Check = $(if ($g) { if ($start -eq $g.Rec) { 'OK' } else { 'Differs' } } else { '' })
            Note = $(if ($s.Name -in $Blob.ProtectedServices) { 'Protected' } else { '' })
            Info = $info
        }
    }
    return @($rows | Sort-Object DisplayName)
}

function Update-BlobGuiServiceGrid {
    try {
        $P = $Blob.Gui.P
        $P.Grid.ItemsSource = @(Get-BlobGuiServiceRows -Filter ([string]$P.Filter.SelectedItem) -Search $P.Search.Text.Trim())
        $P.Count.Text = "$(@($P.Grid.ItemsSource).Count) services shown"
    } catch { Add-BlobGuiLog "{Red}Could not list services: $($_.Exception.Message -replace '[{}]', '')" }
}

function New-BlobGuiServices {
    $P = @{}
    $Blob.Gui.P = $P
    $root = New-BlobStack
    $bar = New-BlobStack 'Horizontal' '0,0,0,12'
    $P.Filter = New-BlobCombo @('Recommended review', 'All services', 'Running only') 0 200
    $P.Search = [Windows.Controls.TextBox]::new()
    $P.Search.Width = 260; $P.Search.Margin = '0,0,8,0'; $P.Search.ToolTip = 'Search by name'
    $P.Count = New-BlobText '' 12 'DarkGray' 'Normal' '8,8,0,0'
    [void]$bar.Children.Add($P.Filter)
    [void]$bar.Children.Add((New-BlobText 'Search' 12 'Gray' 'Normal' '8,8,8,0'))
    [void]$bar.Children.Add($P.Search)
    [void]$bar.Children.Add($P.Count)
    [void]$root.Children.Add($bar)

    $P.Grid = New-BlobGrid @(
        @{ Header = 'Service'; Path = 'DisplayName'; Width = 1 }, @{ Header = 'Name'; Path = 'Name'; Width = 150 },
        @{ Header = 'Status'; Path = 'Status'; Width = 90 }, @{ Header = 'Startup'; Path = 'Startup'; Width = 130 },
        @{ Header = 'Recommended'; Path = 'Recommended'; Width = 130 }, @{ Header = 'Check'; Path = 'Check'; Width = 80 },
        @{ Header = 'Note'; Path = 'Note'; Width = 90 }) 380
    [void]$root.Children.Add($P.Grid)
    $P.Detail = New-BlobText 'Select a service to see what it does.' 13 'Gray'
    [void]$root.Children.Add((New-BlobCard $P.Detail '0,12,0,12'))

    $act = New-BlobStack 'Horizontal'
    [void]$act.Children.Add((New-BlobText 'Set startup type to' 13 'Gray' 'Normal' '0,8,10,0'))
    $P.Type = New-BlobCombo @('Automatic', 'AutomaticDelayed', 'Manual', 'Disabled') 2 180
    [void]$act.Children.Add($P.Type)
    [void]$act.Children.Add((New-BlobButton 'Apply to selected' { Set-BlobGuiServices 'Chosen' } 'Accent'))
    [void]$act.Children.Add((New-BlobButton 'Apply recommended to selected' { Set-BlobGuiServices 'Recommended' }))
    [void]$act.Children.Add((New-BlobButton 'Open services.msc' { Start-Process 'services.msc' -ErrorAction SilentlyContinue }))
    [void]$root.Children.Add((New-BlobCard $act))
    [void]$root.Children.Add((New-BlobText 'Only the startup type changes; running services are not stopped. Changes take full effect after a restart and can be undone from Restore.' 12 'DarkGray'))

    $P.Filter.Add_SelectionChanged({ Update-BlobGuiServiceGrid })
    $P.Search.Add_TextChanged({ Update-BlobGuiServiceGrid })
    $P.Grid.Add_SelectionChanged({
            $r = $Blob.Gui.P.Grid.SelectedItem
            if ($r) {
                $t = "$($r.DisplayName) ($($r.Name)): $($r.Info)"
                if ($r.Recommended) { $t += "  Recommended: $($r.Recommended)." }
                if ($r.Note) { $t += '  This service is protected and cannot be changed.' }
                $Blob.Gui.P.Detail.Text = $t
            }
        })
    Set-BlobGuiPageActions @((New-BlobButton 'Refresh' { Update-BlobGuiServiceGrid } -Margin '0'))
    Update-BlobGuiServiceGrid
    return $root
}

function Set-BlobGuiServices {
    param([string]$Mode)
    $P = $Blob.Gui.P
    $sel = @($P.Grid.SelectedItems)
    if ($sel.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing selected' -Lines @('{Gray}Select one or more services in the list (Ctrl/Shift for several).'); return }
    if (-not $Blob.IsAdmin) { Show-BlobGuiAdminRequired 'Changing a service startup type is a machine-wide change.'; return }
    $plan = @(); $lines = @(); $notes = @()
    foreach ($r in $sel) {
        if ($r.Note -eq 'Protected') { $notes += "{Yellow}  $($r.DisplayName): protected, skipped"; continue }
        $new = if ($Mode -eq 'Recommended') { $r.Recommended } else { [string]$P.Type.SelectedItem }
        if (-not $new) { $notes += "{DarkGray}  $($r.DisplayName): no recommendation, skipped"; continue }
        if ($new -eq $r.Startup) { $notes += "{DarkGray}  $($r.DisplayName): already $new"; continue }
        if ($r.Startup -in @('Boot', 'System')) { $notes += "{Yellow}  $($r.DisplayName): driver-level, skipped"; continue }
        $plan += @{ Row = $r; New = $new }
        $lines += "{White}$($r.DisplayName) {DarkGray}($($r.Name))"
        $lines += "{Gray}    $($r.Startup) {White}-> {Green}$new"
    }
    if ($plan.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing to change' -Lines $notes; return }
    $danger = @($plan | Where-Object { $_.New -eq 'Disabled' -and $_.Row.Recommended -ne 'Disabled' }).Count -gt 0
    if ($notes) { $lines += ''; $lines += $notes }
    if ($danger) { $lines += ''; $lines += '{Yellow}Disabling a service that is not recommended for disabling can break features that depend on it.' }
    if (-not (Confirm-BlobGui -Title "Change $($plan.Count) service startup type(s)?" -Subtitle 'Original startup types are saved and can be restored.' -Lines $lines -Danger:$danger)) { return }
    Start-BlobGuiTask 'Changing service startup types'
    foreach ($x in $plan) { Add-BlobGuiLog (Format-BlobResult (Set-BlobServiceStartup -Name $x.Row.Name -StartupType $x.New -Source 'services' -Label "$($x.Row.DisplayName) startup type")) }
    Update-BlobGuiServiceGrid
}

# ---------------------------------------------------------------------------
#  Startup
# ---------------------------------------------------------------------------
function New-BlobGuiStartup {
    $P = @{}
    $Blob.Gui.P = $P
    $root = New-BlobStack
    $entries = @(Get-BlobStartupEntries | Sort-Object { $_.Scope }, { $_.Name })
    $rows = foreach ($e in $entries) {
        $src = "startup:" + $e.Approved + '|' + $e.Name
        [pscustomobject]@{ Name = $e.Name; Scope = $e.Scope; Status = $(if ($e.Enabled) { 'Enabled' } else { 'Disabled' })
                           Saved = $(if (@(Get-BlobAppliedChanges -Source $src).Count -gt 0) { 'Yes' } else { '' }); Command = $e.Command; Entry = $e }
    }
    $enabled = @($entries | Where-Object { $_.Enabled }).Count
    [void]$root.Children.Add((New-BlobText "$enabled of $($entries.Count) startup programs are enabled. Select rows (Ctrl/Shift for several) and choose an action." 13 'Gray' 'Normal' '0,0,0,12'))
    $P.Grid = New-BlobGrid @(
        @{ Header = 'Program'; Path = 'Name'; Width = 230 }, @{ Header = 'Scope'; Path = 'Scope'; Width = 150 },
        @{ Header = 'Status'; Path = 'Status'; Width = 90 }, @{ Header = 'Original saved'; Path = 'Saved'; Width = 110 },
        @{ Header = 'Command'; Path = 'Command'; Width = 1 }) 420
    $P.Grid.ItemsSource = @($rows)
    [void]$root.Children.Add($P.Grid)
    [void]$root.Children.Add((New-BlobText 'Disabling only stops a program from launching at sign-in - nothing is uninstalled or deleted. Task Manager shows the same state.' 12 'DarkGray' 'Normal' '0,12,0,0'))
    Set-BlobGuiPageActions @(
        (New-BlobButton 'Task Manager' { Start-Process 'taskmgr.exe' -ArgumentList '/7 /startup' -ErrorAction SilentlyContinue }),
        (New-BlobButton 'Restore original' { Restore-BlobGuiStartup }),
        (New-BlobButton 'Enable' { Set-BlobGuiStartup $true }),
        (New-BlobButton 'Disable' { Set-BlobGuiStartup $false } 'Accent' -Margin '0'))
    return $root
}

function Set-BlobGuiStartup {
    param([bool]$Enable)
    $sel = @($Blob.Gui.P.Grid.SelectedItems | ForEach-Object { $_.Entry })
    $verb = if ($Enable) { 'Enable' } else { 'Disable' }
    if ($sel.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing selected' -Lines @('{Gray}Select one or more programs first.'); return }
    $targets = @($sel | Where-Object { $_.Enabled -ne $Enable })
    if ($targets.Count -eq 0) { Show-BlobGuiMessage -Title "Already $($verb.ToLower())d" -Lines @('{Gray}The selected programs are already in that state.'); return }
    $blocked = @($targets | Where-Object { $_.Admin -and -not $Blob.IsAdmin })
    $targets = @($targets | Where-Object { -not ($_.Admin -and -not $Blob.IsAdmin) })
    if ($targets.Count -eq 0) { Show-BlobGuiAdminRequired 'These programs start for all users; their settings are machine-wide.'; return }
    $lines = @()
    foreach ($t in $targets) { $lines += "{White}$($t.Name)  {DarkGray}[$($t.Scope)]"; $lines += "{DarkGray}    $($t.Command)" }
    if ($blocked.Count -gt 0) { $lines += ''; $lines += "{Yellow}$($blocked.Count) all-users entr$(if ($blocked.Count -eq 1) { 'y needs' } else { 'ies need' }) administrator rights and will be skipped." }
    $lines += ''; $lines += '{Gray}Original flags are saved and can be restored at any time.'
    if (-not (Confirm-BlobGui -Title "$verb $($targets.Count) startup program(s)?" -Lines $lines -OkText $verb)) { return }
    Start-BlobGuiTask "$verb startup programs"
    foreach ($t in $targets) { Add-BlobGuiLog (Format-BlobResult (Set-BlobStartupEntry $t $Enable)) }
    Add-BlobGuiLog '{Gray}Changes take effect at the next sign-in.'
    Update-BlobGuiPage
}

function Restore-BlobGuiStartup {
    $sel = @($Blob.Gui.P.Grid.SelectedItems | ForEach-Object { $_.Entry })
    if ($sel.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing selected' -Lines @('{Gray}Select the programs to restore first.'); return }
    $recs = @($sel | ForEach-Object { Get-BlobAppliedChanges -Source ("startup:" + $_.Approved + '|' + $_.Name) })
    if ($recs.Count -eq 0) { Show-BlobGuiMessage -Title 'No saved original' -Kind Warning -Lines @('{Gray}BLOB OPTIMIZER has not changed the selected programs, so there is nothing to restore.'); return }
    if (-not (Confirm-BlobGui -Title 'Restore original startup state?' -OkText 'Restore' -Lines @($recs | ForEach-Object { "{Gray}$($_.Target)" }))) { return }
    Start-BlobGuiTask 'Restoring startup entries'
    $null = Invoke-BlobRestoreCore -Records $recs -Log { param($m) Add-BlobGuiLog $m }
    Update-BlobGuiPage
}

# ---------------------------------------------------------------------------
#  Cleanup
# ---------------------------------------------------------------------------
function Update-BlobGuiCleanupTotal {
    $P = $Blob.Gui.P
    $total = 0
    foreach ($c in $P.Checks) { if ($c.IsChecked) { $total += $P.Sizes[$c.Tag.Id].Bytes } }
    $P.Total.Text = Format-BlobSize $total
}

function New-BlobGuiCleanup {
    $P = @{ Checks = @(); Sizes = @{} }
    $Blob.Gui.P = $P
    Set-BlobGuiStatus 'Scanning cleanup locations (read-only)...'
    $preSizes = Get-BlobPrefetch 'CleanupSizes'
    foreach ($t in $Blob.CleanupTargets) {
        if ($preSizes -and $preSizes.ContainsKey($t.Id)) { $P.Sizes[$t.Id] = $preSizes[$t.Id] } else { $P.Sizes[$t.Id] = Measure-BlobCleanupTarget $t }
    }
    $root = New-BlobStack

    $head = New-BlobStack 'Horizontal'
    [void]$head.Children.Add((New-BlobText 'Selected for cleanup' 14 'Gray' 'Normal' '0,6,14,0'))
    $P.Total = New-BlobText '' 24 'Cyan' 'Bold'
    [void]$head.Children.Add($P.Total)
    [void]$root.Children.Add((New-BlobCard $head))

    [void]$root.Children.Add((New-BlobHeading 'Locations'))
    $list = New-BlobStack
    foreach ($t in $Blob.CleanupTargets) {
        $s = $P.Sizes[$t.Id]
        $grid = [Windows.Controls.Grid]::new()
        $c0 = [Windows.Controls.ColumnDefinition]::new(); $c0.Width = '*'
        $c1 = [Windows.Controls.ColumnDefinition]::new(); $c1.Width = 'Auto'
        $grid.ColumnDefinitions.Add($c0); $grid.ColumnDefinitions.Add($c1); $grid.Margin = '0,6,0,6'
        $cb = [Windows.Controls.CheckBox]::new()
        $content = New-BlobStack
        [void]$content.Children.Add((New-BlobText $t.Name 14 'White' 'SemiBold'))
        $age = if ($t.MinAgeHours -gt 0) { " Only files older than $($t.MinAgeHours) hours." } else { '' }
        [void]$content.Children.Add((New-BlobText ($t.Detail + $age) 12.5 $(if ($t.Warn) { 'Yellow' } else { 'Gray' }) 'Normal' '0,2,0,0'))
        [void]$content.Children.Add((New-BlobText $(if ($t.Paths) { $t.Paths -join '; ' } else { 'Recycle Bin (all drives)' }) 11.5 'DarkGray' 'Normal' '0,2,0,0'))
        $cb.Content = $content; $cb.Tag = $t
        if ($s.Note) { $cb.IsEnabled = $false } else { $cb.IsChecked = (-not $t.Warn -and $t.Special -ne 'Recycle') }
        $cb.Add_Checked({ Update-BlobGuiCleanupTotal }); $cb.Add_Unchecked({ Update-BlobGuiCleanupTotal })
        [Windows.Controls.Grid]::SetColumn($cb, 0); [void]$grid.Children.Add($cb)
        $size = if ($s.Note) { New-BlobText $s.Note 13 'Yellow' } else { New-BlobText ("{0}   {1} items" -f (Format-BlobSize $s.Bytes), $s.Count) 13 'White' 'SemiBold' }
        $size.Margin = '16,2,0,0'
        $right = New-BlobStack 'Horizontal'
        $right.VerticalAlignment = 'Top'
        [void]$right.Children.Add($size)
        $tipParas = @($t.Detail + $age,
            '{Yellow}Deleted files are removed permanently - they do not go to the Recycle Bin and cannot be restored.',
            '{Gray}Files that are currently in use are skipped automatically.',
            $(if ($t.Admin) { '{Yellow}Requires administrator rights.' } else { '{Green}Works without administrator rights.' }),
            '{DarkGray}Risk: LOW - these are temporary files and caches that Windows or apps recreate when needed.')
        $tipMono = if ($t.Paths) { @($t.Paths | ForEach-Object { "{White}$_" }) } else { @('{White}Recycle Bin on all drives') }
        [void]$right.Children.Add((New-BlobHelpIcon (New-BlobTooltipPanel -Title $t.Name -Paragraphs $tipParas -Mono $tipMono -MonoTitle 'Location')))
        [Windows.Controls.Grid]::SetColumn($right, 1); [void]$grid.Children.Add($right)
        [void]$list.Children.Add($grid)
        $P.Checks += $cb
    }
    [void]$root.Children.Add((New-BlobCard $list))

    [void]$root.Children.Add((New-BlobHeading 'Storage'))
    $st = New-BlobStack
    try {
        $lds = @(Get-BlobPrefetch 'LogicalDisks')
        if ($lds.Count -eq 0) { $lds = @(Get-CimInstance Win32_LogicalDisk -Filter 'DriveType=3' -ErrorAction Stop) }
        foreach ($d in $lds) {
            if (-not $d.Size) { continue }
            $row = New-BlobStack 'Horizontal' '0,4,0,4'
            [void]$row.Children.Add((New-BlobText "$($d.DeviceID)" 14 'White' 'SemiBold' '0,0,14,0'))
            $bar = New-BlobBar (1 - $d.FreeSpace / $d.Size) 320; $bar.VerticalAlignment = 'Center'
            [void]$row.Children.Add($bar)
            [void]$row.Children.Add((New-BlobText ("  {0} free of {1}" -f (Format-BlobSize $d.FreeSpace), (Format-BlobSize $d.Size)) 13 'Gray' 'Normal' '12,0,0,0'))
            [void]$st.Children.Add($row)
        }
        $pds = @(Get-BlobPrefetch 'PhysicalDisks')
        if ($pds.Count -eq 0) { $pds = @(Get-PhysicalDisk -ErrorAction Stop) }
        foreach ($pd in $pds) {
            [void]$st.Children.Add((New-BlobText ("{0}  -  {1}, {2}, health: {3}" -f $pd.FriendlyName, $pd.MediaType, (Format-BlobSize $pd.Size), $pd.HealthStatus) 12 'DarkGray' 'Normal' '0,6,0,0'))
        }
    } catch { }
    [void]$root.Children.Add((New-BlobCard $st))
    Update-BlobGuiCleanupTotal
    Set-BlobGuiPageActions @(
        (New-BlobButton 'Storage Sense' { Start-Process 'ms-settings:storagesense' -ErrorAction SilentlyContinue }),
        (New-BlobButton 'Rescan' { Update-BlobGuiPage }),
        (New-BlobButton 'Clean selected' { Invoke-BlobGuiCleanup } 'Accent' -Margin '0'))
    return $root
}

function Invoke-BlobGuiCleanup {
    $P = $Blob.Gui.P
    $sel = @($P.Checks | Where-Object { $_.IsChecked -and $_.IsEnabled } | ForEach-Object { $_.Tag })
    if ($sel.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing selected' -Lines @('{Gray}Tick the locations to clean first.'); return }
    $lines = @($sel | ForEach-Object { ("{{White}}{0,-36} {{Green}}{1}" -f $_.Name, (Format-BlobSize $P.Sizes[$_.Id].Bytes)) })
    $lines += ''; $lines += '{Yellow}Files are permanently deleted (not moved to the Recycle Bin) and cannot be restored.'
    $lines += '{Gray}Files that are in use are skipped automatically.'
    $danger = @($sel | Where-Object { $_.Warn -or $_.Special }).Count -gt 0
    if (-not (Confirm-BlobGui -Title 'Delete these files?' -Lines $lines -OkText 'Delete files' -Danger:$danger)) { return }
    Start-BlobGuiTask 'Cleaning up'
    $sum = 0
    foreach ($t in $sel) {
        Set-BlobGuiStatus "Cleaning $($t.Name)..."
        $r = Invoke-BlobCleanupTarget $t
        $sum += $r.Freed
        Add-BlobGuiLog ("{{Green}} OK   {{White}}{0}  {{Gray}}freed {1}, {2} files, {3} in use / skipped" -f $t.Name, (Format-BlobSize $r.Freed), $r.Deleted, $r.Failed)
        Add-BlobActionRecord -Source 'cleanup' -Label "Cleanup: $($t.Name)" -Target ($t.Paths -join '; ') -Detail ("freed {0}, {1} files" -f (Format-BlobSize $r.Freed), $r.Deleted)
    }
    Add-BlobGuiLog ("{Cyan}" + $(if ($Blob.DryRun) { 'Dry run - would free ' } else { 'Total freed: ' }) + (Format-BlobSize $sum))
    Update-BlobGuiPage
}

# ---------------------------------------------------------------------------
#  Network
# ---------------------------------------------------------------------------
function New-BlobGuiNetwork {
    $P = @{ Adapters = @(Get-BlobAdapters) }
    $Blob.Gui.P = $P
    $root = New-BlobStack
    [void]$root.Children.Add((New-BlobHeading 'Current configuration'))
    [void]$root.Children.Add((New-BlobInfoCard (Get-BlobNetworkInfo | Select-Object -Skip 2) -Mono))

    [void]$root.Children.Add((New-BlobHeading 'DNS servers'))
    $dns = New-BlobStack
    $row = New-BlobStack 'Horizontal'
    $P.Adapter = New-BlobCombo @($P.Adapters | ForEach-Object { $_.Name }) 0 220
    $P.Preset = New-BlobCombo @($Blob.DnsPresets | ForEach-Object { $_.Name }) 0 240
    $P.Custom = [Windows.Controls.TextBox]::new()
    $P.Custom.Width = 230; $P.Custom.Margin = '0,0,8,0'; $P.Custom.ToolTip = 'Custom servers, e.g. 1.1.1.1, 9.9.9.9'
    [void]$row.Children.Add($P.Adapter); [void]$row.Children.Add($P.Preset); [void]$row.Children.Add($P.Custom)
    [void]$row.Children.Add((New-BlobButton 'Apply DNS' { Set-BlobGuiDns } 'Accent'))
    [void]$dns.Children.Add($row)
    [void]$dns.Children.Add((New-BlobText 'The custom box is used when "Custom..." is chosen. The current servers are saved and can be restored from Restore. Requires administrator.' 12 'DarkGray' 'Normal' '0,10,0,0'))
    [void]$root.Children.Add((New-BlobCard $dns))

    [void]$root.Children.Add((New-BlobHeading 'Tools'))
    $tools = New-BlobStack 'Horizontal'
    [void]$tools.Children.Add((New-BlobButton 'Run diagnostics' {
                $ok = Confirm-BlobGui -Title 'Run network diagnostics?' -OkText 'Run' -Lines @(
                    '{Gray}The following checks will be made:', '{White}  1. Ping your default gateway (router)',
                    '{White}  2. Ping 1.1.1.1 (Cloudflare) to test internet reachability', '{White}  3. Resolve www.microsoft.com through your DNS',
                    '', '{DarkGray}Only standard ping and DNS queries are sent.')
                if ($ok) { Start-BlobGuiTask 'Network diagnostics'; Invoke-BlobNetworkDiagnosticsCore -Log { param($m) Add-BlobGuiLog $m } } }))
    [void]$tools.Children.Add((New-BlobButton 'Flush DNS cache' {
                Invoke-BlobGuiNetCommand 'Flush DNS cache' @('{Gray}Removes cached DNS entries; they are rebuilt on demand.') { ipconfig.exe /flushdns } }))
    [void]$tools.Children.Add((New-BlobButton 'Renew IP address' {
                Invoke-BlobGuiNetCommand 'Renew IP address' @('{Gray}Runs ipconfig /release and /renew. The connection drops for a few seconds.') { ipconfig.exe /release | Out-Null; ipconfig.exe /renew } -NeedsAdmin }))
    [void]$tools.Children.Add((New-BlobButton 'Reset Winsock and TCP/IP' {
                Invoke-BlobGuiNetCommand 'Reset Winsock and TCP/IP' @('{Gray}Runs: netsh winsock reset  and  netsh int ip reset',
                    '{Gray}Static IP settings and some VPN software may need to be set up again.', '{Yellow}A restart is required afterwards.') { netsh.exe winsock reset; netsh.exe int ip reset } -NeedsAdmin -Danger } 'Danger'))
    [void]$root.Children.Add((New-BlobCard $tools))
    Set-BlobGuiPageActions @((New-BlobButton 'Refresh' { Update-BlobGuiPage } -Margin '0'))
    return $root
}

function Invoke-BlobGuiNetCommand {
    param([string]$Title, [string[]]$Explain, [scriptblock]$Action, [switch]$NeedsAdmin, [switch]$Danger)
    if ($NeedsAdmin -and -not $Blob.IsAdmin) { Show-BlobGuiAdminRequired "$Title changes system network configuration."; return }
    if (-not (Confirm-BlobGui -Title "$Title?" -OkText 'Run' -Danger:$Danger -Lines ($Explain + @('', '{Yellow}This operation cannot be undone automatically.')))) { return }
    Start-BlobGuiTask $Title
    if ($Blob.DryRun) { Add-BlobGuiLog "{Magenta}Dry run - would run: $Title" }
    else {
        try { foreach ($line in (& $Action 2>&1)) { if ("$line".Trim()) { Add-BlobGuiLog ('{Gray}  ' + ("$line".Trim() -replace '[{}]', '')) } } }
        catch { Add-BlobGuiLog "{Red}  $($_.Exception.Message -replace '[{}]', '')" }
    }
    Add-BlobActionRecord -Source 'network' -Label $Title -Target 'Network'
    Add-BlobGuiLog "{Cyan}$Title finished."
}

function Set-BlobGuiDns {
    $P = $Blob.Gui.P
    if (-not $Blob.IsAdmin) { Show-BlobGuiAdminRequired 'Changing DNS servers modifies network adapter settings for all users.'; return }
    if ($P.Adapters.Count -eq 0 -or $P.Adapter.SelectedIndex -lt 0) { Show-BlobGuiMessage -Title 'No connected adapter' -Kind Warning; return }
    $adapter = $P.Adapters[$P.Adapter.SelectedIndex]
    $preset = $Blob.DnsPresets[$P.Preset.SelectedIndex]
    $servers = $preset.Servers
    if ($null -eq $servers) {
        $servers = @($P.Custom.Text -split '[,; ]+' | Where-Object { $_ })
        if ($servers.Count -eq 0) { Show-BlobGuiMessage -Title 'Enter custom DNS servers' -Kind Warning -Lines @('{Gray}Type one or two IP addresses in the custom box, e.g. 1.1.1.1, 9.9.9.9'); return }
        foreach ($s in $servers) { $ip = $null; if (-not [Net.IPAddress]::TryParse($s, [ref]$ip)) { Show-BlobGuiMessage -Title 'Invalid address' -Kind Warning -Lines @("{Gray}'$s' is not a valid IP address."); return } }
    }
    $cur = Get-BlobDnsInfo $adapter
    $newText = if ($servers.Count -eq 0) { 'automatic (DHCP)' } else { $servers -join ', ' }
    if (-not (Confirm-BlobGui -Title 'Change DNS servers?' -Lines @(
                "{Gray}Adapter   {White}$($adapter.Name)",
                "{Gray}Current   {White}$(@($cur.Servers) -join ', ') {DarkGray}($(if ($cur.Static) { 'manual' } else { 'automatic' }))",
                "{Gray}New       {Green}$newText", '', '{Gray}The current configuration is saved and can be restored.'))) { return }
    Start-BlobGuiTask 'Changing DNS servers'
    Add-BlobGuiLog (Format-BlobResult (Set-BlobDns -Adapter $adapter -Servers $servers -Label "DNS: $($preset.Name)"))
    Update-BlobGuiPage
}

# ---------------------------------------------------------------------------
#  Power
# ---------------------------------------------------------------------------
function New-BlobGuiPower {
    $P = @{ Timeouts = @() }
    $Blob.Gui.P = $P
    $root = New-BlobStack
    [void]$root.Children.Add((New-BlobHeading 'Power plans'))
    $plans = New-BlobStack
    foreach ($plan in @(Get-BlobPowerPlans)) {
        $row = [Windows.Controls.DockPanel]::new()
        $row.Margin = '0,4,0,4'
        $btn = New-BlobButton 'Activate' ([scriptblock]::Create("Invoke-BlobGuiSetPlan '$($plan.Guid)'")) -Margin '0'
        if ($plan.Active) { $btn.IsEnabled = $false; $btn.Content = 'Active' }
        [Windows.Controls.DockPanel]::SetDock($btn, 'Right'); [void]$row.Children.Add($btn)
        $name = New-BlobStack 'Horizontal'
        [void]$name.Children.Add((New-BlobText $plan.Name 14 $(if ($plan.Active) { 'Cyan' } else { 'White' }) 'SemiBold'))
        if ($plan.Active) { [void]$name.Children.Add((New-BlobBadge 'ACTIVE' 'Green')) }
        [void]$name.Children.Add((New-BlobText "  $($plan.Guid)" 11 'DarkGray' 'Normal' '8,3,0,0'))
        $name.VerticalAlignment = 'Center'
        [void]$row.Children.Add($name)
        [void]$plans.Children.Add($row)
    }
    $add = New-BlobStack 'Horizontal' '0,12,0,0'
    $hasHigh = @(Get-BlobPowerPlans | Where-Object { $_.Guid -eq $Blob.KnownPlans.HighPerformance }).Count -gt 0
    if (-not $hasHigh) { [void]$add.Children.Add((New-BlobButton 'Add High Performance plan' { Invoke-BlobGuiAddPlan 'HighPerformance' })) }
    [void]$add.Children.Add((New-BlobButton 'Add Ultimate Performance plan' { Invoke-BlobGuiAddPlan 'UltimatePerformance' }))
    [void]$plans.Children.Add($add)
    [void]$root.Children.Add((New-BlobCard $plans))

    [void]$root.Children.Add((New-BlobHeading 'Display and sleep (active plan)'))
    $choices = @(0, 1, 2, 3, 5, 10, 15, 20, 30, 45, 60, 120)
    $tgrid = New-BlobStack
    foreach ($t in $Blob.PowerTimeouts) {
        $cur = Get-BlobTimeoutMinutes $t
        $row = New-BlobStack 'Horizontal' '0,4,0,4'
        $lbl = New-BlobText $t.Name 13.5 'White'; $lbl.Width = 260; $lbl.VerticalAlignment = 'Center'
        $opts = @($choices)
        if ($null -ne $cur -and $cur -notin $opts) { $opts = @($opts + $cur | Sort-Object) }
        $combo = New-BlobCombo @($opts | ForEach-Object { Format-BlobMinutes $_ }) ([array]::IndexOf($opts, $cur)) 160
        [void]$row.Children.Add($lbl); [void]$row.Children.Add($combo)
        [void]$row.Children.Add((New-BlobText "current: $(Format-BlobMinutes $cur)" 12 'DarkGray' 'Normal' '6,8,0,0'))
        [void]$tgrid.Children.Add($row)
        $P.Timeouts += @{ T = $t; Combo = $combo; Opts = $opts; Cur = $cur }
    }
    $apply = New-BlobButton 'Apply timeouts' { Set-BlobGuiTimeouts } 'Accent'
    $apply.HorizontalAlignment = 'Left'; $apply.Margin = '0,10,0,0'
    [void]$tgrid.Children.Add($apply)
    [void]$root.Children.Add((New-BlobCard $tgrid))

    [void]$root.Children.Add((New-BlobHeading 'Hibernation'))
    $hib = Get-BlobHibernateEnabled
    $hrow = [Windows.Controls.DockPanel]::new()
    $hbtn = New-BlobButton $(if ($hib) { 'Turn off' } else { 'Turn on' }) { Invoke-BlobGuiHibernate } -Margin '0'
    [Windows.Controls.DockPanel]::SetDock($hbtn, 'Right'); [void]$hrow.Children.Add($hbtn)
    $hs = New-BlobStack
    [void]$hs.Children.Add((New-BlobText "Hibernation is $(if ($hib) { 'on' } else { 'off' })" 14 'White' 'SemiBold'))
    [void]$hs.Children.Add((New-BlobText 'Turning it off frees disk space (hiberfil.sys) but also disables Fast Startup and the Hibernate option. Requires administrator.' 12.5 'Gray' 'Normal' '0,2,12,0'))
    [void]$hrow.Children.Add($hs)
    [void]$root.Children.Add((New-BlobCard $hrow))
    Set-BlobGuiPageActions @((New-BlobButton 'Refresh' { Update-BlobGuiPage } -Margin '0'))
    return $root
}

function Invoke-BlobGuiSetPlan {
    param([string]$Guid)
    $plan = @(Get-BlobPowerPlans) | Where-Object { $_.Guid -eq $Guid } | Select-Object -First 1
    if (-not $plan) { return }
    if (-not (Confirm-BlobGui -Title "Activate '$($plan.Name)'?" -OkText 'Activate' -Lines @("{Gray}$((Get-BlobActivePowerPlan).Name) {White}-> {Green}$($plan.Name)", '', '{Gray}The previous plan is saved and can be re-activated from Restore.'))) { return }
    Start-BlobGuiTask 'Changing power plan'
    Add-BlobGuiLog (Format-BlobResult (Set-BlobPowerPlan $plan.Guid $plan.Name))
    Update-BlobGuiPage
}

function Invoke-BlobGuiAddPlan {
    param([string]$Which)
    $name = if ($Which -eq 'HighPerformance') { 'High Performance' } else { 'Ultimate Performance' }
    if (-not (Confirm-BlobGui -Title "Create and activate the $name plan?" -OkText 'Create plan' -Lines @(
                "{Gray}A new power plan is created from the built-in $name template and activated.",
                '{Gray}Higher performance plans use more power and produce more heat. No FPS gain is guaranteed.',
                '{Gray}Undo from Restore: re-activate the previous plan, then remove the created plan.'))) { return }
    Start-BlobGuiTask "Creating $name plan"
    $add = Add-BlobPowerPlan $Blob.KnownPlans[$Which] $name
    Add-BlobGuiLog (Format-BlobResult $add.Result)
    if ($add.Guid) { Add-BlobGuiLog (Format-BlobResult (Set-BlobPowerPlan $add.Guid $name)) }
    Update-BlobGuiPage
}

function Set-BlobGuiTimeouts {
    $changes = @()
    foreach ($x in $Blob.Gui.P.Timeouts) {
        if ($x.Combo.SelectedIndex -lt 0) { continue }
        $new = $x.Opts[$x.Combo.SelectedIndex]
        if ($new -ne $x.Cur) { $changes += @{ T = $x.T; New = $new; Cur = $x.Cur } }
    }
    if ($changes.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing changed' -Lines @('{Gray}Pick new values in the lists first.'); return }
    $lines = @($changes | ForEach-Object { "{White}$($_.T.Name)   {Gray}$(Format-BlobMinutes $_.Cur) {White}-> {Green}$(Format-BlobMinutes $_.New)" })
    if (-not (Confirm-BlobGui -Title 'Change power timeouts?' -Lines ($lines + @('', '{Gray}Previous values are saved and can be restored.')))) { return }
    Start-BlobGuiTask 'Changing power timeouts'
    foreach ($c in $changes) { Add-BlobGuiLog (Format-BlobResult (Set-BlobPowerTimeout $c.T $c.New)) }
    Update-BlobGuiPage
}

function Invoke-BlobGuiHibernate {
    if (-not $Blob.IsAdmin) { Show-BlobGuiAdminRequired 'Hibernation is a machine-wide setting.'; return }
    $target = -not (Get-BlobHibernateEnabled)
    $word = if ($target) { 'on' } else { 'off' }
    if (-not (Confirm-BlobGui -Title "Turn hibernation $word?" -OkText "Turn $word" -Lines @(
                '{Gray}Turning hibernation off deletes hiberfil.sys and disables Fast Startup and the Hibernate option.',
                '{Gray}It can be turned back on here or from Restore.'))) { return }
    Start-BlobGuiTask "Turning hibernation $word"
    Add-BlobGuiLog (Format-BlobResult (Set-BlobHibernate $target))
    Update-BlobGuiPage
}

# ---------------------------------------------------------------------------
#  Restore
# ---------------------------------------------------------------------------
function New-BlobGuiRestore {
    $P = @{}
    $Blob.Gui.P = $P
    $root = New-BlobStack
    $drift = @(Get-BlobDrift)
    if ($drift.Count) { [void]$root.Children.Add((New-BlobDriftBar $drift)) }
    $recs = @($Blob.Changes.ToArray()); [array]::Reverse($recs)
    $rows = foreach ($r in $recs) {
        [pscustomobject]@{ Time = $r.Time; Change = $r.Label; Target = $r.Target; Status = $r.Status
                           Undo = $(if ($r.Reversible) { 'Restorable' } else { 'One-way' }); Rec = $r }
    }
    $restorable = @(Get-BlobAppliedChanges).Count
    [void]$root.Children.Add((New-BlobText "$($recs.Count) recorded changes, $restorable can be restored. Select rows (Ctrl/Shift for several) and choose Restore selected." 13 'Gray' 'Normal' '0,0,0,12'))
    $P.Grid = New-BlobGrid @(
        @{ Header = 'Time'; Path = 'Time'; Width = 150 }, @{ Header = 'Change'; Path = 'Change'; Width = 1 },
        @{ Header = 'Target'; Path = 'Target'; Width = 1 }, @{ Header = 'Status'; Path = 'Status'; Width = 90 },
        @{ Header = 'Undo'; Path = 'Undo'; Width = 95 }) 330
    $P.Grid.ItemsSource = @($rows)
    $P.Grid.Add_MouseDoubleClick({ Show-BlobGuiChangeDetail })
    [void]$root.Children.Add($P.Grid)

    [void]$root.Children.Add((New-BlobHeading 'Undo a whole session' '0,16,0,10'))
    $sess = New-BlobStack 'Horizontal'
    $P.Sessions = @($Blob.Changes | Group-Object SessionId | Sort-Object Name -Descending)
    $labels = @($P.Sessions | ForEach-Object { "Session $($_.Name)  ($(@($_.Group | Where-Object { $_.Status -eq 'Applied' -and $_.Reversible }).Count) restorable)" })
    $P.SessionCombo = New-BlobCombo $labels 0 340
    [void]$sess.Children.Add($P.SessionCombo)
    [void]$sess.Children.Add((New-BlobButton 'Undo session' { Undo-BlobGuiSession }))
    [void]$root.Children.Add((New-BlobCard $sess))

    [void]$root.Children.Add((New-BlobHeading 'Backups and configuration'))
    $b = New-BlobStack
    $row1 = New-BlobStack 'Horizontal'
    [void]$row1.Children.Add((New-BlobButton 'Create System Restore point' { Invoke-BlobGuiRestorePoint }))
    [void]$row1.Children.Add((New-BlobButton 'Export configuration' { Export-BlobGuiConfig }))
    [void]$row1.Children.Add((New-BlobButton 'Import configuration' { Import-BlobGuiConfig }))
    [void]$row1.Children.Add((New-BlobButton 'Open backup folder' {
                if (Test-Path -LiteralPath $Blob.DataRoot) { Start-Process explorer.exe -ArgumentList "`"$($Blob.DataRoot)`"" }
                else { Show-BlobGuiMessage -Title 'No files yet' -Lines @('{Gray}The folder is created when the first change is made.', "{DarkGray}$($Blob.DataRoot)") } }))
    [void]$b.Children.Add($row1)
    $row2 = New-BlobStack 'Horizontal' '0,12,0,0'
    $P.Snaps = @()
    if (Test-Path -LiteralPath $Blob.RegBackupDir) { $P.Snaps = @(Get-ChildItem -LiteralPath $Blob.RegBackupDir -Directory | Sort-Object Name -Descending) }
    [void]$row2.Children.Add((New-BlobText 'Registry snapshot' 13 'Gray' 'Normal' '0,8,10,0'))
    $P.SnapCombo = New-BlobCombo @($P.Snaps | ForEach-Object { $_.Name }) 0 300
    [void]$row2.Children.Add($P.SnapCombo)
    [void]$row2.Children.Add((New-BlobButton 'Import snapshot' { Import-BlobGuiSnapshot } 'Danger'))
    [void]$b.Children.Add($row2)
    [void]$b.Children.Add((New-BlobText 'Prefer the history above for precise per-setting restore. Snapshot import re-applies whole registry keys as they were.' 12 'DarkGray' 'Normal' '0,10,0,0'))
    [void]$root.Children.Add((New-BlobCard $b))

    Set-BlobGuiPageActions @(
        (New-BlobButton 'Undo everything' { Invoke-BlobGuiUndoEverything } 'Danger' -ToolTip 'Put back every original value BLOB saved'),
        (New-BlobButton 'Details' { Show-BlobGuiChangeDetail }),
        (New-BlobButton 'Restore selected' { Restore-BlobGuiSelected } 'Accent' -Margin '0'))
    return $root
}

function Show-BlobGuiChangeDetail {
    $r = $Blob.Gui.P.Grid.SelectedItem
    if (-not $r) { Show-BlobGuiMessage -Title 'Nothing selected' -Lines @('{Gray}Select a change in the list first.'); return }
    Show-BlobGuiMessage -Title 'Change details' -Lines (Get-BlobChangeDetail $r.Rec)
}

function Restore-BlobGuiSelected {
    $sel = @($Blob.Gui.P.Grid.SelectedItems | ForEach-Object { $_.Rec })
    if ($sel.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing selected' -Lines @('{Gray}Select one or more changes first.'); return }
    $ok = @($sel | Where-Object { $_.Status -eq 'Applied' -and $_.Reversible })
    if ($ok.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing restorable selected' -Kind Warning -Lines @('{Gray}The selected records are already restored, failed, or one-way operations.'); return }
    $lines = @($ok | ForEach-Object { "{Gray}$($_.Target)" })
    if ($sel.Count -gt $ok.Count) { $lines += ''; $lines += "{Yellow}$($sel.Count - $ok.Count) selected record(s) cannot be restored and will be skipped." }
    if (-not (Confirm-BlobGui -Title "Restore $($ok.Count) original value(s)?" -Lines $lines -OkText 'Restore')) { return }
    Start-BlobGuiTask 'Restoring changes'
    $a, $b = Invoke-BlobRestoreCore -Records $ok -Log { param($m) Add-BlobGuiLog $m }
    Add-BlobGuiLog ("{Cyan}Restore finished: {0} restored, {1} not restored." -f $a, $b)
    Update-BlobGuiPage
}

function Undo-BlobGuiSession {
    $P = $Blob.Gui.P
    if ($P.Sessions.Count -eq 0 -or $P.SessionCombo.SelectedIndex -lt 0) { Show-BlobGuiMessage -Title 'No sessions recorded yet'; return }
    $g = $P.Sessions[$P.SessionCombo.SelectedIndex]
    $recs = @($g.Group | Where-Object { $_.Status -eq 'Applied' -and $_.Reversible })
    if ($recs.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing left to restore in this session'; return }
    if (-not (Confirm-BlobGui -Title "Restore all $($recs.Count) changes from session $($g.Name)?" -OkText 'Restore session' -Lines @($recs | ForEach-Object { "{Gray}$($_.Target)" }))) { return }
    Start-BlobGuiTask "Undoing session $($g.Name)"
    $a, $b = Invoke-BlobRestoreCore -Records $recs -Log { param($m) Add-BlobGuiLog $m }
    Add-BlobGuiLog ("{Cyan}Session restore finished: {0} restored, {1} not restored." -f $a, $b)
    Update-BlobGuiPage
}

function Import-BlobGuiSnapshot {
    $P = $Blob.Gui.P
    if ($P.Snaps.Count -eq 0 -or $P.SnapCombo.SelectedIndex -lt 0) { Show-BlobGuiMessage -Title 'No registry snapshots yet' -Lines @('{Gray}A snapshot is exported automatically before each batch of tweaks.'); return }
    $dir = $P.Snaps[$P.SnapCombo.SelectedIndex]
    $files = @(Get-ChildItem -LiteralPath $dir.FullName -Filter *.reg | Sort-Object Name)
    $lines = @($files | ForEach-Object { $k = Get-Content -LiteralPath $_.FullName -TotalCount 5 | Where-Object { $_ -match '^\[' } | Select-Object -First 1; "{Gray}$($_.Name)  {White}$k" })
    $lines += ''; $lines += '{Yellow}Importing writes every value from these files back into the registry.'
    $lines += '{Gray}Values created after the snapshot are not removed. Machine-wide keys need administrator rights.'
    if (-not (Confirm-BlobGui -Title 'Import this registry snapshot?' -Subtitle $dir.FullName -Lines $lines -OkText 'Import' -Danger)) { return }
    Start-BlobGuiTask 'Importing registry snapshot'
    foreach ($f in $files) {
        if ($Blob.DryRun) { Add-BlobGuiLog "{Magenta} DRY  {White}$($f.Name)"; continue }
        $out = & reg.exe import $f.FullName 2>&1
        if ($LASTEXITCODE -eq 0) { Add-BlobGuiLog "{Green} OK   {White}$($f.Name)" } else { Add-BlobGuiLog "{Red} FAIL {White}$($f.Name) {Gray}$(("$out" -replace '[{}]', '').Trim())" }
    }
    Add-BlobActionRecord -Source 'restore' -Label 'Imported registry snapshot' -Target $dir.FullName
    Add-BlobGuiLog '{Cyan}Snapshot import finished. Sign out or restart for all settings to apply.'
}

function Export-BlobGuiConfig {
    $applied = @($Blob.Tweaks | Where-Object { (Get-BlobTweakState $_) -eq 'Applied' } | ForEach-Object { $_.Id })
    $dlg = [Microsoft.Win32.SaveFileDialog]::new()
    $dlg.Filter = 'BLOB OPTIMIZER configuration (*.json)|*.json'
    $dlg.FileName = "BLOB-config-{0}.json" -f (Get-Date -Format 'yyyyMMdd-HHmm')
    $dlg.InitialDirectory = [Environment]::GetFolderPath('MyDocuments')
    if ($dlg.ShowDialog($Blob.Gui.Window) -ne $true) { return }
    $obj = [ordered]@{ tool = 'BLOB OPTIMIZER'; format = 1; version = $Blob.Version; exported = (Get-Date).ToString('s'); tweaks = $applied }
    [IO.File]::WriteAllText($dlg.FileName, (ConvertTo-Json -InputObject $obj -Depth 4), (New-Object Text.UTF8Encoding($false)))
    Add-BlobGuiLog "{Green}Configuration exported: {White}$($dlg.FileName) {Gray}($($applied.Count) tweaks, no personal data)"
}

function Import-BlobGuiConfig {
    $dlg = [Microsoft.Win32.OpenFileDialog]::new()
    $dlg.Filter = 'BLOB OPTIMIZER configuration (*.json)|*.json'
    $dlg.InitialDirectory = [Environment]::GetFolderPath('MyDocuments')
    if ($dlg.ShowDialog($Blob.Gui.Window) -ne $true) { return }
    try {
        $cfg = Get-Content -LiteralPath $dlg.FileName -Raw -ErrorAction Stop | ConvertFrom-Json -ErrorAction Stop
        if ($cfg.tool -ne 'BLOB OPTIMIZER' -or -not $cfg.tweaks) { throw 'This is not a BLOB OPTIMIZER configuration file.' }
    } catch { Show-BlobGuiMessage -Title 'Cannot read configuration' -Kind Error -Lines @("{Gray}$($_.Exception.Message -replace '[{}]', '')"); return }
    $ids = @($cfg.tweaks | ForEach-Object { [string]$_ })
    $known = @($ids | ForEach-Object { Get-BlobTweak $_ } | Where-Object { $_ })
    $unknown = @($ids | Where-Object { -not (Get-BlobTweak $_) })
    $extra = @()
    if ($unknown.Count -gt 0) { $extra = @("{Yellow}$($unknown.Count) unknown setting(s) will be ignored: $($unknown -join ', ')", '') }
    $null = Invoke-BlobGuiApply -Tweaks $known -Tag 'import' -ExtraLines $extra
}
#endregion

#region ---- GuiApps.ps1 ----
# ============================================================================
#  BLOB OPTIMIZER - GuiApps.ps1
#  The Apps page: every installed program and Store app, removed completely
#  (own uninstaller first, then the leftovers you choose).
# ============================================================================

$Blob.GuiShared.AppUninstall = { Invoke-BlobGuiUninstall $Blob.Gui.Sender.DataContext }

function Get-BlobGuiFilteredApps {
    $list = @($Blob.Gui.AppsData)
    switch ($Blob.Gui.AppsFilter) {
        'Desktop' { $list = @($list | Where-Object { $_.Kind -eq 'Desktop' }) }
        'Store' { $list = @($list | Where-Object { $_.Kind -eq 'Store' }) }
    }
    $q = ([string]$Blob.Gui.AppsSearch).Trim()
    if ($q) { $list = @($list | Where-Object { $_.Name -like "*$q*" -or $_.Publisher -like "*$q*" }) }
    switch ($Blob.Gui.AppsSort) {
        'Size' { $list = @($list | Sort-Object @{ Expression = { $_.SizeBytes }; Descending = $true }, Name) }
        'Newest' { $list = @($list | Sort-Object @{ Expression = { if ($_.InstallDate) { $_.InstallDate } else { [datetime]::MinValue } }; Descending = $true }, Name) }
        default { $list = @($list | Sort-Object Name) }
    }
    return $list
}

function New-BlobAppRow {
    param($App)
    $row = [Windows.Controls.Border]::new()
    $row.BorderBrush = Get-BlobBrush 'Rule'; $row.BorderThickness = '0,0,0,1'; $row.Padding = '0,10'
    $row.Background = [Windows.Media.Brushes]::Transparent
    $row.Add_MouseEnter({ param($s, $e) $s.Background = Get-BlobBrush 'Hover' })
    $row.Add_MouseLeave({ param($s, $e) $s.Background = [Windows.Media.Brushes]::Transparent })
    $g = [Windows.Controls.Grid]::new()
    foreach ($w in @('*', '96', '104', '84', '126')) { $cd = [Windows.Controls.ColumnDefinition]::new(); $cd.Width = $w; $g.ColumnDefinitions.Add($cd) }

    $text = New-BlobStack
    $text.Margin = '4,0,16,0'; $text.VerticalAlignment = 'Center'
    $title = New-BlobStack 'Horizontal'
    [void]$title.Children.Add((New-BlobText $App.Name 14 'Ink' 'SemiBold'))
    if ($App.Protected) { $b = New-BlobBadge 'WINDOWS NEEDS THIS' 'Ink3'; $b.Margin = '10,1,0,0'; [void]$title.Children.Add($b) }
    elseif ($App.Shared) { $b = New-BlobBadge 'SHARED COMPONENT' 'SignalText'; $b.Margin = '10,1,0,0'; [void]$title.Children.Add($b) }
    [void]$text.Children.Add($title)
    $meta = @($App.Publisher, $(if ($App.Version) { "version $($App.Version)" }), $App.Scope) | Where-Object { $_ }
    $m = New-BlobText ($meta -join ('  ' + [string][char]0x00B7 + '  ')) 12.5 'Ink2' 'Normal' '0,2,0,0'
    $m.TextWrapping = 'NoWrap'; $m.TextTrimming = 'CharacterEllipsis'
    [void]$text.Children.Add($m)
    [void]$g.Children.Add($text)

    $size = New-BlobText $(if ($App.SizeBytes -gt 0) { Format-BlobSize $App.SizeBytes } else { [string][char]0x2014 }) 12.5 'Ink2' 'Normal' -Mono
    $size.VerticalAlignment = 'Center'; $size.HorizontalAlignment = 'Right'; $size.Margin = '0,0,16,0'
    [Windows.Controls.Grid]::SetColumn($size, 1); [void]$g.Children.Add($size)
    $date = New-BlobText $(if ($App.InstallDate) { $App.InstallDate.ToString('yyyy-MM-dd') } else { [string][char]0x2014 }) 12.5 'Ink3' 'Normal' -Mono
    $date.VerticalAlignment = 'Center'
    [Windows.Controls.Grid]::SetColumn($date, 2); [void]$g.Children.Add($date)
    $kind = New-BlobText $(if ($App.Kind -eq 'Store') { 'STORE' } else { 'PROGRAM' }) 11.5 'Ink3' 'Normal' -Display
    $kind.VerticalAlignment = 'Center'
    [Windows.Controls.Grid]::SetColumn($kind, 3); [void]$g.Children.Add($kind)

    if ($App.Protected) {
        $lock = New-BlobText 'Protected' 13 'Ink3' 'Normal' -Display
        $lock.VerticalAlignment = 'Center'; $lock.HorizontalAlignment = 'Right'; $lock.Margin = '0,0,4,0'
        Set-BlobTooltip $lock (New-BlobTooltipPanel -Title 'Windows depends on this' -Paragraphs @('Removing it can break Windows features or other apps, so BLOB does not offer it.'))
        [Windows.Controls.Grid]::SetColumn($lock, 4); [void]$g.Children.Add($lock)
    } else {
        $btn = [Windows.Controls.Button]::new()
        $btn.Content = 'Uninstall'; $btn.Padding = '14,4'; $btn.Margin = '0,0,4,0'; $btn.HorizontalAlignment = 'Right'; $btn.VerticalAlignment = 'Center'
        $btn.DataContext = $App.Id
        Register-BlobClick $btn $Blob.GuiShared.AppUninstall
        [Windows.Controls.Grid]::SetColumn($btn, 4); [void]$g.Children.Add($btn)
    }
    $row.Child = $g
    return $row
}

function Update-BlobGuiAppsList {
    $P = $Blob.Gui.P
    if (-not $P -or -not $P.List) { return }
    $offset = $Blob.Gui.PageScroll.VerticalOffset
    $P.List.Children.Clear()
    if (-not $Blob.Gui.AppRowCache) { $Blob.Gui.AppRowCache = @{} }
    $list = @(Get-BlobGuiFilteredApps)
    foreach ($a in $list) {
        $el = $Blob.Gui.AppRowCache[$a.Id]
        if (-not $el) { $el = New-BlobAppRow $a; $Blob.Gui.AppRowCache[$a.Id] = $el }
        if ($el.Parent -is [Windows.Controls.Panel]) { $el.Parent.Children.Remove($el) }
        [void]$P.List.Children.Add($el)
    }
    if ($list.Count -eq 0) { [void]$P.List.Children.Add((New-BlobText 'Nothing matches.' 14 'Ink3' 'Normal' '0,24,0,0')) }
    $total = ($list | Measure-Object -Property SizeBytes -Sum).Sum
    $dot = [string][char]0x00B7
    $P.Count.Text = "$($list.Count) shown  $dot  $(Format-BlobSize $total) reported by the programs  $dot  Store apps do not report a size"
    $Blob.Gui.PageScroll.UpdateLayout(); $Blob.Gui.PageScroll.ScrollToVerticalOffset($offset)
}

function New-BlobGuiApps {
    $P = @{}
    $Blob.Gui.P = $P
    if (-not $Blob.Gui.AppsFilter) { $Blob.Gui.AppsFilter = 'All' }
    if (-not $Blob.Gui.AppsSort) { $Blob.Gui.AppsSort = 'Name' }
    $Blob.Gui.AppsData = @(Get-BlobDesktopApps) + @(Get-BlobStoreApps)
    $Blob.Gui.AppRowCache = @{}
    $root = New-BlobStack

    $top = [Windows.Controls.DockPanel]::new()
    $sbox = [Windows.Controls.Grid]::new()
    $sbox.Width = 240; $sbox.VerticalAlignment = 'Top'; $sbox.Margin = '24,0,0,0'
    $search = [Windows.Controls.TextBox]::new()
    $search.Text = [string]$Blob.Gui.AppsSearch; $search.Padding = '22,5,2,5'
    $hint = New-BlobText 'Search apps' 13.5 'Ink3' 'Normal' '23,6,0,0'
    $hint.IsHitTestVisible = $false
    if ($search.Text) { $hint.Visibility = 'Collapsed' }
    $glass = New-BlobGlyph 0xE721 'Ink2' 15
    $glass.Margin = '1,0,0,2'; $glass.HorizontalAlignment = 'Left'; $glass.IsHitTestVisible = $false
    [void]$sbox.Children.Add($search); [void]$sbox.Children.Add($hint); [void]$sbox.Children.Add($glass)
    $P.Hint = $hint
    $search.Add_TextChanged({ param($s, $e) $Blob.Gui.AppsSearch = $s.Text; $Blob.Gui.P.Hint.Visibility = if ($s.Text) { 'Collapsed' } else { 'Visible' }; Update-BlobGuiAppsList })
    [Windows.Controls.DockPanel]::SetDock($sbox, 'Right')
    [void]$top.Children.Add($sbox)

    $filters = New-BlobStack
    $all = $Blob.Gui.AppsData
    $types = [Windows.Controls.WrapPanel]::new()
    foreach ($f in @(@('All', "All $($all.Count)"), @('Desktop', "Programs $(@($all | Where-Object { $_.Kind -eq 'Desktop' }).Count)"), @('Store', "Store apps $(@($all | Where-Object { $_.Kind -eq 'Store' }).Count)"))) {
        [void]$types.Children.Add((New-BlobGuiFilterChip $f[1] ($Blob.Gui.AppsFilter -eq $f[0]) ([scriptblock]::Create("`$Blob.Gui.AppsFilter = '$($f[0])'; Show-BlobGuiPage 'apps' -Rebuild"))))
    }
    [void]$filters.Children.Add((New-BlobFilterRow 'Type' $types))
    $sorts = [Windows.Controls.WrapPanel]::new()
    foreach ($o in @(@('Name', 'Name'), @('Size', 'Largest first'), @('Newest', 'Newest first'))) {
        [void]$sorts.Children.Add((New-BlobGuiFilterChip $o[1] ($Blob.Gui.AppsSort -eq $o[0]) ([scriptblock]::Create("`$Blob.Gui.AppsSort = '$($o[0])'; Show-BlobGuiPage 'apps' -Rebuild"))))
    }
    [void]$filters.Children.Add((New-BlobFilterRow 'Sort' $sorts))
    [void]$top.Children.Add($filters)
    [void]$root.Children.Add($top)

    # How it works, in three lines
    $how = [Windows.Controls.Grid]::new()
    $how.Margin = '0,14,0,6'
    for ($i = 0; $i -lt 3; $i++) { $cd = [Windows.Controls.ColumnDefinition]::new(); $cd.Width = '*'; $how.ColumnDefinitions.Add($cd) }
    $steps = @(
        @('1', 'Own uninstaller', 'The program removes itself the way its maker intended. Store apps are removed by Windows, data included.'),
        @('2', 'Leftover scan', 'Only once Windows no longer lists it: folders, registry keys, shortcuts and startup entries with its exact name.'),
        @('3', 'You choose', 'Folders and shortcuts go to the Recycle Bin. Registry keys are backed up to .reg first.'))
    for ($i = 0; $i -lt 3; $i++) {
        $b = [Windows.Controls.Border]::new()
        $b.BorderBrush = Get-BlobBrush 'Rule'; $b.BorderThickness = $(if ($i -eq 0) { '0' } else { '1,0,0,0' }); $b.Padding = $(if ($i -eq 0) { '0,0,20,0' } else { '20,0,20,0' })
        $d = [Windows.Controls.DockPanel]::new()
        $n = New-BlobText $steps[$i][0] 30 'Ghost' 'Light' '0,-4,12,0' -Display
        [void]$d.Children.Add($n)
        $sp = New-BlobStack
        [void]$sp.Children.Add((New-BlobText $steps[$i][1] 14.5 'Ink' 'SemiBold' -Display))
        [void]$sp.Children.Add((New-BlobText $steps[$i][2] 12.5 'Ink2' 'Normal' '0,2,0,0'))
        [void]$d.Children.Add($sp)
        $b.Child = $d
        [Windows.Controls.Grid]::SetColumn($b, $i); [void]$how.Children.Add($b)
    }
    [void]$root.Children.Add($how)

    # Column heads
    $head = [Windows.Controls.Grid]::new()
    $head.Margin = '0,18,0,0'
    foreach ($w in @('*', '96', '104', '84', '126')) { $cd = [Windows.Controls.ColumnDefinition]::new(); $cd.Width = $w; $head.ColumnDefinitions.Add($cd) }
    $heads = @(@('NAME', 0, 'Left', '4,0,0,6'), @('SIZE', 1, 'Right', '0,0,16,6'), @('INSTALLED', 2, 'Left', '0,0,0,6'), @('TYPE', 3, 'Left', '0,0,0,6'))
    foreach ($h in $heads) {
        $t = New-BlobText $h[0] 11.5 'Ink3' 'Normal' $h[3] -Display
        $t.HorizontalAlignment = $h[2]
        [Windows.Controls.Grid]::SetColumn($t, $h[1]); [void]$head.Children.Add($t)
    }
    $hb = [Windows.Controls.Border]::new()
    $hb.BorderBrush = Get-BlobBrush 'Ink'; $hb.BorderThickness = '0,0,0,1.5'; $hb.Child = $head
    [void]$root.Children.Add($hb)

    $P.List = New-BlobStack
    [void]$root.Children.Add($P.List)
    $P.Count = New-BlobText '' 12 'Ink3' 'Normal' '0,14,0,0' -Mono
    [void]$root.Children.Add($P.Count)

    Set-BlobGuiPageActions @(
        (New-BlobButton 'Apps & features' { Start-Process 'ms-settings:appsfeatures' -ErrorAction SilentlyContinue } -ToolTip 'Open the Windows list of installed apps'),
        (New-BlobButton 'Refresh' { $Blob.PrefetchValid = $false; Show-BlobGuiPage 'apps' -Rebuild } -Margin '0'))
    Update-BlobGuiAppsList
    return $root
}

# Leftover picker: one checkbox per item, all ticked by default.
function Show-BlobGuiLeftovers {
    param($App, [array]$Items)
    $d = New-BlobGuiWindow $Blob.GuiDialogXaml
    $d.Owner = $Blob.Gui.Window
    $d.FindName('DlgTitle').Text = "$($App.Name) left $($Items.Count) thing(s) behind"
    $d.FindName('DlgSub').Text = 'Untick anything you want to keep. Folders and shortcuts go to the Recycle Bin; registry keys are backed up first.'
    $body = $d.FindName('DlgBody')
    $boxes = New-Object System.Collections.ArrayList
    foreach ($it in $Items) {
        $cb = [Windows.Controls.CheckBox]::new()
        $cb.IsChecked = $true; $cb.Margin = '0,0,0,12'
        $sp = New-BlobStack
        [void]$sp.Children.Add((New-BlobText $it.Type.ToUpper() 11.5 'Ink3' 'Normal' -Display))
        [void]$sp.Children.Add((New-BlobText $it.Path 12.5 'Ink' 'Normal' '0,1,0,0' -Mono))
        if ($it.Detail) { [void]$sp.Children.Add((New-BlobText $it.Detail 12 'Ink2' 'Normal' '0,1,0,0')) }
        $cb.Content = $sp
        $cb.Tag = $it
        [void]$body.Children.Add($cb)
        [void]$boxes.Add($cb)
    }
    $ok = $d.FindName('DlgOk'); $cancel = $d.FindName('DlgCancel')
    $ok.Content = 'Remove selected'; $cancel.Content = 'Keep everything'
    $d.Tag = $false
    $ok.Add_Click({ param($s, $e) $w = [Windows.Window]::GetWindow($s); $w.Tag = $true; $w.Close() })
    $cancel.Add_Click({ param($s, $e) [Windows.Window]::GetWindow($s).Close() })
    $d.Add_KeyDown({ param($s, $e) if ($e.Key -eq 'Escape') { $s.Close() } })
    $null = $d.ShowDialog()
    if (-not $d.Tag) { return @() }
    return @($boxes | Where-Object { $_.IsChecked } | ForEach-Object { $_.Tag })
}

function Invoke-BlobGuiUninstall {
    param([string]$Id)
    $app = @($Blob.Gui.AppsData) | Where-Object { $_.Id -eq $Id } | Select-Object -First 1
    if (-not $app) { return }
    if ($app.Protected) { Show-BlobGuiMessage -Title 'Windows depends on this' -Lines @('{Gray}Removing it can break Windows features or other apps, so BLOB does not offer it.'); return }
    if ($app.NeedsAdmin -and -not $Blob.IsAdmin) { Show-BlobGuiAdminRequired "$($app.Name) is installed for all users; removing it needs administrator rights."; return }

    $lines = @(
        "{Gray}Program     {White}$($app.Name)",
        "{Gray}Publisher   {White}$($app.Publisher)",
        "{Gray}Version     {White}$($app.Version)")
    if ($app.SizeBytes -gt 0) { $lines += "{Gray}Size        {White}$(Format-BlobSize $app.SizeBytes)" }
    if ($app.InstallLocation) { $lines += "{Gray}Location    {White}$($app.InstallLocation)" }
    $lines += ''
    if ($app.Kind -eq 'Store') {
        $lines += '{White}Windows removes this Store app together with its app data. Nothing else is touched.'
    } else {
        $lines += '{White}1. The program''s own uninstaller opens. Follow its steps.'
        $lines += '{White}2. When Windows no longer lists the program, BLOB looks for leftovers.'
        $lines += '{White}3. You choose what to remove. Nothing is removed without your OK.'
    }
    if ($app.Shared) { $lines += ''; $lines += '{Yellow}This is a shared component. Other programs, games or drivers may need it.' }
    $canRp = $Blob.IsAdmin -and -not $Blob.DryRun
    $rpText = if ($canRp) { 'Create a System Restore point first' } else { 'Create a System Restore point first (needs administrator, not in dry run)' }
    $ok = Show-BlobGuiDialog -Title "Uninstall $($app.Name)?" -Lines $lines -OkText 'Uninstall' -Danger:$app.Shared -CheckText $rpText -CheckDefault ($canRp -and $app.Shared) -CheckEnabled $canRp
    if (-not $ok) { return }
    if ($Blob.Gui.DialogCheck) { Invoke-BlobGuiRestorePointStep "BLOB OPTIMIZER - before removing $($app.Name)" }

    Start-BlobGuiTask "Uninstalling $($app.Name)"
    Set-BlobGuiStatus "Waiting for the uninstaller of $($app.Name)..."
    $r = Invoke-BlobAppUninstall -App $app -Log { param($m) Add-BlobGuiLog $m } -Pump { Update-BlobGui; Start-Sleep -Milliseconds 120 }
    if ($r -eq 'DryRun') { return }
    if ($r -notin @('Finished', 'Removed')) { Show-BlobGuiMessage -Title "Could not uninstall $($app.Name)" -Kind Error -Lines @("{Gray}$($r -replace '[{}]', '')"); return }
    if ($r -eq 'Removed') {
        $Blob.PrefetchValid = $false
        Show-BlobGuiMessage -Title "$($app.Name) is removed" -Kind Success -Lines @('{Gray}Windows removed the app and its app data.')
        Update-BlobGuiPage
        return
    }

    # Only scan for leftovers once Windows no longer lists the program.
    while (Test-BlobAppInstalled $app) {
        $again = Show-BlobGuiDialog -Title "$($app.Name) is still installed" -OkText 'Check again' -CancelText 'Stop' -Lines @(
            '{Gray}The uninstaller may still be open, or it was cancelled.',
            '{Gray}Finish it, then choose Check again.', '',
            '{White}BLOB only looks for leftovers after Windows stops listing the program,',
            '{White}so nothing that belongs to an installed program is ever removed.')
        if (-not $again) { Add-BlobGuiLog "{Yellow}$($app.Name) is still installed - leftover scan skipped."; Update-BlobGuiPage; return }
    }
    Add-BlobGuiLog "{White}$($app.Name) {Gray}is no longer installed. Looking for leftovers..."
    Set-BlobGuiStatus 'Looking for leftovers...'
    $left = @(Find-BlobAppLeftovers $app)
    if ($left.Count -eq 0) {
        Add-BlobGuiLog "{White}$($app.Name) {Gray}left nothing behind."
        Show-BlobGuiMessage -Title "$($app.Name) is fully removed" -Kind Success -Lines @('{Gray}The uninstaller cleaned up after itself. No leftover folders, registry keys, shortcuts or startup entries were found.')
        Update-BlobGuiPage
        return
    }
    $chosen = @(Show-BlobGuiLeftovers $app $left)
    if ($chosen.Count -eq 0) { Add-BlobGuiLog "{Gray}Leftovers of $($app.Name) kept."; Update-BlobGuiPage; return }
    Start-BlobGuiTask "Removing leftovers of $($app.Name)"
    $backup = Join-Path $Blob.RegBackupDir ("{0}-apps-{1}" -f (Get-Date -Format 'yyyyMMdd-HHmmss'), (($app.Name -replace '[^\w-]', '') | ForEach-Object { $_.Substring(0, [Math]::Min(30, $_.Length)) }))
    foreach ($it in $chosen) { Add-BlobGuiLog (Remove-BlobLeftover $it $backup $app.Name) }
    Add-BlobGuiLog "{White}$($app.Name) {Gray}is fully removed. Folders are in the Recycle Bin; registry keys can be restored from Restore."
    Update-BlobGuiPage
}
#endregion

#region ---- GuiPrivacy.ps1 ----
# ============================================================================
#  BLOB OPTIMIZER - GuiPrivacy.ps1
#  The Privacy page: every section of the privacy catalogue, each item with
#  a switch (on = that Windows feature is turned off), privacy impact,
#  recommendation, state and a full explanation on hover.
#  Uses the same choose-then-apply flow as the Tweaks page.
# ============================================================================

$Blob.GuiShared.PrivacyTip = { param($el) New-BlobPrivacyTooltip (Get-BlobTweak $el.DataContext) }
$Blob.PcRecFilters = [ordered]@{ All = 'All'; Disable = 'Recommended off'; Optional = 'Your choice'; Keep = 'Better kept on' }

function New-BlobPrivacyTooltip {
    param($Tweak)
    $p = $Tweak.Privacy
    $s = New-BlobStack
    $s.MaxWidth = 500
    $head = New-BlobStack 'Horizontal' '0,0,0,8'
    [void]$head.Children.Add((New-BlobText $Tweak.Name 16 'Ink' 'SemiBold' -Display))
    if ($p.Oo) { $b = New-BlobBadge "O&O $($p.Oo)" 'Ink2'; $b.Margin = '10,2,0,0'; [void]$head.Children.Add($b) }
    [void]$s.Children.Add($head)
    $rows = @(
        @('What it does', $p.Does),
        @('What Windows or Microsoft can collect', $p.Data),
        @('Benefit of turning it off', $p.Benefit),
        @('What you lose', $p.Lose),
        @('Possible problems', $p.Issues))
    foreach ($r in $rows) {
        [void]$s.Children.Add((New-BlobText $r[0].ToUpper() 11 'Ink3' 'Normal' '0,4,0,1' -Display))
        [void]$s.Children.Add((New-BlobText $r[1] 12.5 'Ink' 'Normal' '0,0,0,4'))
    }
    $recWord = switch ($p.Rec) { 'Disable' { 'DISABLE - good privacy benefit, minimal downside' } 'Optional' { 'OPTIONAL - depends on how you use the PC' } default { 'KEEP ENABLED - important for security or everyday use' } }
    $line = New-BlobStack 'Horizontal' '0,6,0,0'
    [void]$line.Children.Add((New-BlobText 'RECOMMENDATION  ' 11 'Ink3' 'Normal' '0,1,0,0' -Display))
    [void]$line.Children.Add((New-BlobText $recWord 12.5 $(if ($p.Rec -eq 'Keep') { 'SignalText' } else { 'Ink' }) 'SemiBold'))
    [void]$s.Children.Add($line)
    $line2 = New-BlobStack 'Horizontal' '0,4,0,0'
    [void]$line2.Children.Add((New-BlobText 'PRIVACY IMPACT  ' 11 'Ink3' 'Normal' '0,1,0,0' -Display))
    [void]$line2.Children.Add((New-BlobText $p.Impact.ToUpper() 12.5 $(if ($p.Impact -eq 'High') { 'SignalText' } else { 'Ink' }) 'SemiBold'))
    [void]$s.Children.Add($line2)
    [void]$s.Children.Add((New-BlobText 'EXACT CHANGE (CURRENT -> NEW)' 11 'Ink3' 'Normal' '0,10,0,3' -Display))
    foreach ($m in @(Get-BlobTweakPreview @($Tweak) | Select-Object -Skip 1 | Where-Object { $_ -match '^\{(Gray|DarkGray)\} {4}' -and $_ -notmatch 'Note:' })) {
        [void]$s.Children.Add((ConvertTo-BlobTextBlock $m -Mono -Size 11.5))
    }
    [void]$s.Children.Add((New-BlobText 'The original value is saved first; undo it here or on the Restore page.' 12 'Ink2' 'Normal' '0,6,0,0'))
    return $s
}

# Privacy impact meter: three bars, HIGH in signal orange.
function New-BlobImpactMeter {
    param([string]$Impact)
    $lvl = switch ($Impact) { 'High' { 3 } 'Medium' { 2 } default { 1 } }
    $sp = New-BlobStack 'Horizontal'
    $sp.VerticalAlignment = 'Center'
    $fill = if ($Impact -eq 'High') { Get-BlobBrush 'Signal' } else { Get-BlobBrush 'Ink' }
    for ($i = 1; $i -le 3; $i++) {
        $bar = [Windows.Shapes.Rectangle]::new()
        $bar.Width = 5; $bar.Height = 4 + 3 * $i; $bar.Margin = '0,0,2,0'; $bar.VerticalAlignment = 'Bottom'
        $bar.Fill = if ($i -le $lvl) { $fill } else { Get-BlobBrush 'Rule' }
        [void]$sp.Children.Add($bar)
    }
    $w = New-BlobText $(switch ($Impact) { 'High' { 'HIGH' } 'Medium' { 'MED' } default { 'LOW' } }) 11.5 $(if ($Impact -eq 'High') { 'SignalText' } else { 'Ink2' }) 'SemiBold' '6,0,0,0' -Display
    $w.VerticalAlignment = 'Bottom'
    [void]$sp.Children.Add($w)
    return $sp
}

function New-BlobPrivacyRow {
    param($Tweak, [string]$State, [string]$Pending)
    $p = $Tweak.Privacy
    $wantOn = if ($Pending) { $Pending -eq 'On' } else { $State -eq 'Applied' }
    $row = [Windows.Controls.Border]::new()
    $row.BorderBrush = Get-BlobBrush 'Rule'; $row.BorderThickness = '0,0,0,1'
    $row.Background = if ($Pending) { Get-BlobBrush 'SignalSoft' } else { [Windows.Media.Brushes]::Transparent }
    $row.Uid = $(if ($Pending) { 'P' } else { '' })
    $row.Add_MouseEnter({ param($s, $e) if ($s.Uid -ne 'P') { $s.Background = Get-BlobBrush 'Hover' } })
    $row.Add_MouseLeave({ param($s, $e) if ($s.Uid -ne 'P') { $s.Background = [Windows.Media.Brushes]::Transparent } })
    $g = [Windows.Controls.Grid]::new()
    foreach ($w in @('4', '58', '*', '86', '108', '112', '34')) { $cd = [Windows.Controls.ColumnDefinition]::new(); $cd.Width = $w; $g.ColumnDefinitions.Add($cd) }

    $marker = [Windows.Controls.Border]::new()
    $marker.Background = if ($Pending) { Get-BlobBrush 'Signal' } else { [Windows.Media.Brushes]::Transparent }
    [void]$g.Children.Add($marker)

    if ($Tweak.InfoOnly) {
        $dash = New-BlobText ([string][char]0x2014) 14 'Ink3' 'Normal' -Display
        $dash.HorizontalAlignment = 'Center'; $dash.VerticalAlignment = 'Center'
        [Windows.Controls.Grid]::SetColumn($dash, 1); [void]$g.Children.Add($dash)
    } else {
        $sw = [Windows.Controls.CheckBox]::new()
        $sw.Style = $Blob.Gui.Window.FindResource('Switch')
        $sw.IsChecked = $wantOn
        $sw.VerticalAlignment = 'Center'; $sw.HorizontalAlignment = 'Center'
        $row.Tag = $sw
        if ($Tweak.Admin -and -not $Blob.IsAdmin) {
            $sw.IsEnabled = $false
            $holder = [Windows.Controls.Border]::new()
            $holder.Background = [Windows.Media.Brushes]::Transparent; $holder.VerticalAlignment = 'Center'
            $holder.Child = $sw
            Set-BlobTooltip $holder (New-BlobTooltipPanel -Title 'Needs administrator rights' -Paragraphs @('This is a machine-wide setting. Start BLOB again and choose Yes in the Windows permission prompt to change it.'))
            [Windows.Controls.Grid]::SetColumn($holder, 1); [void]$g.Children.Add($holder)
        } else {
            $sw.DataContext = $Tweak.Id
            $sw.ToolTip = 'On = turn this Windows feature off. Nothing changes until you review and apply.'
            Register-BlobClick $sw $Blob.GuiShared.SwitchClick
            [Windows.Controls.Grid]::SetColumn($sw, 1); [void]$g.Children.Add($sw)
        }
    }

    $text = New-BlobStack
    $text.Margin = '6,0,16,0'; $text.VerticalAlignment = 'Center'
    $title = New-BlobStack 'Horizontal'
    [void]$title.Children.Add((New-BlobText $Tweak.Name 14 $(if ($p.Rec -eq 'N/A') { 'Ink3' } else { 'Ink' }) 'SemiBold'))
    if ($p.Oo) { $b = New-BlobBadge $p.Oo 'Ink2'; $b.Margin = '10,1,0,0'; [void]$title.Children.Add($b) }
    if ($Tweak.Admin -and -not $Tweak.InfoOnly) { $ad = New-BlobBadge 'ADMIN' 'Ink3'; $ad.Margin = '6,1,0,0'; [void]$title.Children.Add($ad) }
    [void]$text.Children.Add($title)
    $desc = New-BlobText $p.Does 12.5 'Ink2' 'Normal' '0,2,0,0'
    $desc.TextWrapping = 'NoWrap'; $desc.TextTrimming = 'CharacterEllipsis'
    [void]$text.Children.Add($desc)
    [Windows.Controls.Grid]::SetColumn($text, 2); [void]$g.Children.Add($text)

    $impact = New-BlobImpactMeter $p.Impact
    [Windows.Controls.Grid]::SetColumn($impact, 3); [void]$g.Children.Add($impact)

    $recText = switch ($p.Rec) { 'Disable' { 'DISABLE' } 'Optional' { 'OPTIONAL' } 'Keep' { 'KEEP ON' } default { 'N/A' } }
    $rec = New-BlobText $recText 12 $(switch ($p.Rec) { 'Disable' { 'Ink' } 'Keep' { 'SignalText' } default { 'Ink3' } }) $(if ($p.Rec -eq 'Disable') { 'SemiBold' } else { 'Normal' }) -Display
    $rec.VerticalAlignment = 'Center'
    [Windows.Controls.Grid]::SetColumn($rec, 4); [void]$g.Children.Add($rec)

    $arrow = [string][char]0x2192
    $stText = if ($Tweak.InfoOnly) { 'Info only' } elseif ($Pending -eq 'On') { "$arrow OFF" } elseif ($Pending -eq 'Off') { "$arrow BACK ON" } else {
        switch ($State) { 'Applied' { 'Turned off' } 'Partial' { 'Partly off' } default { 'Windows default' } } }
    $stColor = if ($Pending) { 'SignalText' } elseif ($State -eq 'Applied') { 'Ink' } else { 'Ink3' }
    $st = New-BlobText $stText 12.5 $stColor $(if ($Pending -or $State -eq 'Applied') { 'SemiBold' } else { 'Normal' }) -Display
    $st.VerticalAlignment = 'Center'
    [Windows.Controls.Grid]::SetColumn($st, 5); [void]$g.Children.Add($st)

    $help = New-BlobHelpIcon -Builder $Blob.GuiShared.PrivacyTip
    $help.DataContext = $Tweak.Id
    $help.Margin = '0'; $help.HorizontalAlignment = 'Center'
    [Windows.Controls.Grid]::SetColumn($help, 6); [void]$g.Children.Add($help)

    $g.Margin = '0,9,0,9'
    $row.Child = $g
    return $row
}

function Get-BlobGuiFilteredPrivacy {
    $list = @(Get-BlobPrivacyItems)
    if ($Blob.Gui.PcSection -and $Blob.Gui.PcSection -ne 'All sections') { $list = @($list | Where-Object { $_.Group -eq $Blob.Gui.PcSection }) }
    if ($Blob.Gui.PcRec -and $Blob.Gui.PcRec -ne 'All') { $list = @($list | Where-Object { $_.Privacy.Rec -eq $Blob.Gui.PcRec }) }
    $q = ([string]$Blob.Gui.PcSearch).Trim()
    if ($q) { $list = @($list | Where-Object { $_.Name -like "*$q*" -or $_.Privacy.Does -like "*$q*" -or $_.Privacy.Oo -like "*$q*" -or $_.Group -like "*$q*" }) }
    return $list
}

function Update-BlobGuiPrivacyList {
    $g = $Blob.Gui.CardGrid
    if (-not $g) { return }
    $offset = $Blob.Gui.PageScroll.VerticalOffset
    $g.Children.Clear()
    $items = @(Get-BlobPrivacyItems)
    $states = @{}
    foreach ($t in $items) { $states[$t.Id] = Get-BlobTweakState $t }
    $list = @(Get-BlobGuiFilteredPrivacy)
    $n = 0
    foreach ($grp in $Blob.PrivacyGroups) {
        $inGrp = @($list | Where-Object { $_.Group -eq $grp })
        if ($inGrp.Count -eq 0) { continue }
        $n++
        $switchable = @($inGrp | Where-Object { -not $_.InfoOnly })
        $off = @($switchable | Where-Object { $states[$_.Id] -eq 'Applied' }).Count
        $num = [array]::IndexOf($Blob.PrivacyGroups, $grp) + 1
        [void]$g.Children.Add((New-BlobGroupHeader "$num. $grp" "$off of $($switchable.Count) turned off"))
        foreach ($t in $inGrp) { [void]$g.Children.Add((Get-BlobGuiCard $t $states[$t.Id])) }
    }
    if ($list.Count -eq 0) { [void]$g.Children.Add((New-BlobText 'Nothing matches these filters.' 14 'Ink3' 'Normal' '0,30,0,0')) }
    $switchAll = @($items | Where-Object { -not $_.InfoOnly })
    $offAll = @($switchAll | Where-Object { $states[$_.Id] -eq 'Applied' }).Count
    $dot = [string][char]0x00B7
    $Blob.Gui.CardCount.Text = "$($list.Count) shown  $dot  $offAll of $($switchAll.Count) turned off  $dot  $($Blob.Gui.Pending.Count) waiting"
    Update-BlobGuiPendingBar
    $Blob.Gui.PageScroll.UpdateLayout(); $Blob.Gui.PageScroll.ScrollToVerticalOffset($offset)
}

function New-BlobGuiPrivacy {
    $root = New-BlobStack
    if (-not $Blob.Gui.PcSection) { $Blob.Gui.PcSection = 'All sections' }
    if (-not $Blob.Gui.PcRec) { $Blob.Gui.PcRec = 'All' }
    $items = @(Get-BlobPrivacyItems)

    $top = [Windows.Controls.DockPanel]::new()
    $sbox = [Windows.Controls.Grid]::new()
    $sbox.Width = 240; $sbox.VerticalAlignment = 'Top'; $sbox.Margin = '24,0,0,0'
    $search = [Windows.Controls.TextBox]::new()
    $search.Text = [string]$Blob.Gui.PcSearch; $search.Padding = '22,5,2,5'
    $hint = New-BlobText 'Search, or an O&O ID' 13.5 'Ink3' 'Normal' '23,6,0,0'
    $hint.IsHitTestVisible = $false
    if ($search.Text) { $hint.Visibility = 'Collapsed' }
    $glass = New-BlobGlyph 0xE721 'Ink2' 15
    $glass.Margin = '1,0,0,2'; $glass.HorizontalAlignment = 'Left'; $glass.IsHitTestVisible = $false
    [void]$sbox.Children.Add($search); [void]$sbox.Children.Add($hint); [void]$sbox.Children.Add($glass)
    $Blob.Gui.SearchHint = $hint
    $search.Add_TextChanged({ param($s, $e) $Blob.Gui.PcSearch = $s.Text; $Blob.Gui.SearchHint.Visibility = if ($s.Text) { 'Collapsed' } else { 'Visible' }; Update-BlobGuiPrivacyList })
    [Windows.Controls.DockPanel]::SetDock($sbox, 'Right')
    [void]$top.Children.Add($sbox)

    $filters = New-BlobStack
    $secRow = [Windows.Controls.DockPanel]::new()
    $secRow.Margin = '0,0,0,8'
    $l = New-BlobText 'SECTION' 11.5 'Ink3' 'Normal' '0,8,0,0' -Display
    $l.Width = 86
    [void]$secRow.Children.Add($l)
    $names = @('All sections') + @($Blob.PrivacyGroups | ForEach-Object { $_ })
    $labels = @('All sections') + @(for ($i = 0; $i -lt $Blob.PrivacyGroups.Count; $i++) { '{0}. {1}' -f ($i + 1), $Blob.PrivacyGroups[$i] })
    $combo = New-BlobCombo $labels ([array]::IndexOf($names, $Blob.Gui.PcSection)) 320
    $combo.HorizontalAlignment = 'Left'
    $combo.Tag = $names
    $combo.Add_SelectionChanged({ param($s, $e) $Blob.Gui.PcSection = $s.Tag[$s.SelectedIndex]; Update-BlobGuiPrivacyList })
    [void]$secRow.Children.Add($combo)
    [void]$filters.Children.Add($secRow)
    $recs = [Windows.Controls.WrapPanel]::new()
    foreach ($k in $Blob.PcRecFilters.Keys) {
        $count = if ($k -eq 'All') { $items.Count } else { @($items | Where-Object { $_.Privacy.Rec -eq $k }).Count }
        [void]$recs.Children.Add((New-BlobGuiFilterChip "$($Blob.PcRecFilters[$k]) $count" ($Blob.Gui.PcRec -eq $k) ([scriptblock]::Create("`$Blob.Gui.PcRec = '$k'; Show-BlobGuiPage 'privacy' -Rebuild"))))
    }
    [void]$filters.Children.Add((New-BlobFilterRow 'Advice' $recs))
    [void]$top.Children.Add($filters)
    [void]$root.Children.Add($top)

    $Blob.Gui.CardCount = New-BlobText '' 12 'Ink3' 'Normal' '0,10,0,0' -Mono
    [void]$root.Children.Add($Blob.Gui.CardCount)

    # Column heads
    $head = [Windows.Controls.Grid]::new()
    $head.Margin = '0,16,0,0'
    foreach ($w in @('4', '58', '*', '86', '108', '112', '34')) { $cd = [Windows.Controls.ColumnDefinition]::new(); $cd.Width = $w; $head.ColumnDefinitions.Add($cd) }
    foreach ($h in @(@('TURN OFF', 1, '6,0,0,4'), @('SETTING', 2, '6,0,0,4'), @('PRIVACY', 3, '0,0,0,4'), @('ADVICE', 4, '0,0,0,4'), @('STATE', 5, '0,0,0,4'))) {
        $t = New-BlobText $h[0] 11 'Ink3' 'Normal' $h[2] -Display
        [Windows.Controls.Grid]::SetColumn($t, $h[1]); [void]$head.Children.Add($t)
    }
    [void]$root.Children.Add($head)

    $list = New-BlobStack
    $Blob.Gui.CardGrid = $list
    [void]$root.Children.Add($list)
    [void]$root.Children.Add((New-BlobText 'Every switch uses a documented Windows, Edge or Office policy or setting. Microsoft Defender, security updates and Windows activation are never changed. O&O ShutUp10++ IDs are shown where known.' 12 'Ink3' 'Normal' '0,24,0,0'))

    Set-BlobGuiPageActions @(
        (New-BlobButton 'Choose all recommended' {
                foreach ($t in (Get-BlobGuiFilteredPrivacy)) {
                    if ($t.InfoOnly -or $t.Privacy.Rec -ne 'Disable') { continue }
                    if ($t.Admin -and -not $Blob.IsAdmin) { continue }
                    if ((Get-BlobTweakState $t) -ne 'Applied') { $Blob.Gui.Pending[$t.Id] = 'On' }
                }
                Update-BlobGuiPrivacyList } -ToolTip 'Marks every shown setting with advice DISABLE. Nothing changes until you review and apply.' -Margin '0'))
    Update-BlobGuiPrivacyList
    return $root
}
#endregion

#region ---- GuiExtras.ps1 ----
# ============================================================================
#  BLOB OPTIMIZER - GuiExtras.ps1
#  Drift bar and flows, Undo everything, Install page (winget), Measure page,
#  global search (Ctrl+K) and the "What changed" summary after applying.
# ============================================================================

# ---------------------------------------------------------------------------
#  Drift: settings Windows (or you) changed back
# ---------------------------------------------------------------------------
function New-BlobDriftBar {
    param([array]$Drift)
    $b = [Windows.Controls.Border]::new()
    $b.Background = Get-BlobBrush 'SignalSoft'; $b.BorderBrush = Get-BlobBrush 'Signal'; $b.BorderThickness = '3,0,0,0'
    $b.Padding = '18,14'; $b.Margin = '0,0,0,26'
    $d = [Windows.Controls.DockPanel]::new()
    $btns = New-BlobStack 'Horizontal'
    [Windows.Controls.DockPanel]::SetDock($btns, 'Right')
    [void]$btns.Children.Add((New-BlobButton 'Details' { Show-BlobGuiDriftDetails }))
    [void]$btns.Children.Add((New-BlobButton "Keep Windows' values" { Invoke-BlobGuiDriftAccept }))
    [void]$btns.Children.Add((New-BlobButton "Re-apply $($Drift.Count)" { Invoke-BlobGuiDriftRepair } 'Accent' -Margin '0'))
    $btns.VerticalAlignment = 'Center'
    [void]$d.Children.Add($btns)
    $t = New-BlobStack
    [void]$t.Children.Add((New-BlobText $(if ($Drift.Count -eq 1) { "1 of your settings was changed back" } else { "$($Drift.Count) of your settings were changed back" }) 16 'Ink' 'SemiBold' -Display))
    [void]$t.Children.Add((New-BlobText 'Windows updates (or a change in Settings) put them back. Re-apply them, or keep the current values.' 12.5 'Ink2' 'Normal' '0,3,16,0'))
    [void]$d.Children.Add($t)
    $b.Child = $d
    return $b
}

function Get-BlobDriftLines {
    param([array]$Drift)
    return @($Drift | ForEach-Object { "{White}$($_.Label)"; "{Gray}    $($_.Target)"; "{DarkGray}        now $($_.Now) {White}-> {White}BLOB set $($_.Want)" })
}

function Show-BlobGuiDriftDetails {
    $drift = @(Get-BlobDrift)
    Show-BlobGuiMessage -Title "$($drift.Count) setting(s) changed back" -Lines (@('{Gray}These were changed by BLOB and later put back by Windows or in Settings.', '') + (Get-BlobDriftLines $drift))
}

function Invoke-BlobGuiDriftRepair {
    $drift = @(Get-BlobDrift)
    if ($drift.Count -eq 0) { Update-BlobGuiPage; return }
    $ok = Show-BlobGuiDialog -Title "Re-apply $($drift.Count) setting(s)?" -Subtitle 'Your original values stay saved, so undo still returns the PC to how it was before BLOB.' `
        -Lines (Get-BlobDriftLines $drift) -OkText 'Re-apply'
    if (-not $ok) { return }
    Start-BlobGuiTask 'Re-applying settings that were changed back'
    $Blob.Gui.Collected = New-Object System.Collections.ArrayList
    foreach ($i in $drift) { $line = Repair-BlobDrift $i; Add-BlobGuiLog $line; [void]$Blob.Gui.Collected.Add($line) }
    Show-BlobGuiChangeSummary 'Re-applied settings'
    Update-BlobGuiPage
}

function Invoke-BlobGuiDriftAccept {
    $drift = @(Get-BlobDrift)
    if ($drift.Count -eq 0) { Update-BlobGuiPage; return }
    $ok = Show-BlobGuiDialog -Title "Keep the current values?" -OkText "Keep Windows' values" -Lines (@(
            '{Gray}BLOB stops tracking these settings and leaves them as they are now.',
            '{Gray}They will no longer appear in Undo everything.', '') + (Get-BlobDriftLines $drift))
    if (-not $ok) { return }
    foreach ($i in $drift) { Set-BlobDriftAccepted $i }
    Add-BlobGuiLog "{White}Kept the current values of $($drift.Count) setting(s)."
    Update-BlobGuiPage
}

# ---------------------------------------------------------------------------
#  Undo everything
# ---------------------------------------------------------------------------
function Invoke-BlobGuiUndoEverything {
    $recs = @(Get-BlobAppliedChanges)
    if ($recs.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing to undo' -Lines @('{Gray}BLOB has no changes that can be undone on this PC.'); return }
    $bySource = $recs | Group-Object { $_.Label } | Sort-Object Count -Descending
    $lines = @('{White}Every value below goes back to what it was before BLOB changed it:', '')
    $lines += @($bySource | ForEach-Object { "{Gray}  $($_.Name)  {DarkGray}($($_.Count) value(s))" })
    $lines += ''; $lines += '{Gray}Removed app leftovers in the Recycle Bin and cleaned files are not affected.'
    $canRp = $Blob.IsAdmin -and -not $Blob.DryRun
    $ok = Show-BlobGuiDialog -Title "Undo all $($recs.Count) change(s)?" -Subtitle 'Puts this PC back the way it was before BLOB.' -Lines $lines -OkText 'Undo everything' -Danger `
        -CheckText $(if ($canRp) { 'Create a System Restore point first' } else { 'Create a System Restore point first (needs administrator, not in dry run)' }) -CheckDefault $false -CheckEnabled $canRp
    if (-not $ok) { return }
    if ($Blob.Gui.DialogCheck) { Invoke-BlobGuiRestorePointStep 'BLOB OPTIMIZER - before undo everything' }
    Start-BlobGuiTask "Undoing $($recs.Count) change(s)"
    $Blob.Gui.Collected = New-Object System.Collections.ArrayList
    $a, $b = Invoke-BlobRestoreCore -Records $recs -Log $Blob.GuiShared.LogCollect
    Add-BlobGuiLog ("{White}Undo everything finished: {0} restored, {1} not restored." -f $a, $b)
    Show-BlobGuiChangeSummary 'Undo everything'
    Update-BlobGuiPage
}

# ---------------------------------------------------------------------------
#  What changed
# ---------------------------------------------------------------------------
$Blob.GuiShared.LogCollect = { param($m) Add-BlobGuiLog $m; if ($null -ne $Blob.Gui.Collected) { [void]$Blob.Gui.Collected.Add($m) } }

function Show-BlobGuiChangeSummary {
    param([string]$Title = 'What changed')
    $lines = @($Blob.Gui.Collected | Where-Object { $_ -match '(OK|SAME|SKIP|FAIL|DRY) ' -or $_ -match "^\{Cyan\}" })
    if ($lines.Count -eq 0) { return }
    $plain = @($lines | ForEach-Object { (Get-BlobPlainText $_).TrimEnd() })
    $ok = @($plain | Where-Object { $_ -match '^\s*OK ' }).Count
    $fail = @($plain | Where-Object { $_ -match '^\s*FAIL ' }).Count
    $dry = @($plain | Where-Object { $_ -match '^\s*DRY ' }).Count
    $same = @($plain | Where-Object { $_ -match '^\s*SAME ' }).Count
    $Blob.Gui.SummaryText = $plain
    $sub = if ($dry) { "Dry run: $dry would change, $same already set, nothing was modified." } else { "$ok changed, $same already set, $fail failed." }
    $save = Show-BlobGuiDialog -Title $Title -Subtitle "$sub The same list is in the log at the bottom." -Lines $lines -OkText 'Save as text file' -CancelText 'Close' -Kind $(if ($fail) { 'Warning' } else { 'Info' })
    if (-not $save) { return }
    $dlg = [Microsoft.Win32.SaveFileDialog]::new()
    $dlg.Filter = 'Text file (*.txt)|*.txt'
    $dlg.FileName = "BLOB-changes-{0}.txt" -f (Get-Date -Format 'yyyyMMdd-HHmm')
    $dlg.InitialDirectory = [Environment]::GetFolderPath('MyDocuments')
    if ($dlg.ShowDialog($Blob.Gui.Window) -ne $true) { return }
    $head = @("BLOB OPTIMIZER $($Blob.Version) - $Title", (Get-Date).ToString('yyyy-MM-dd HH:mm'), "Computer: $($Blob.SysInfo.Host)", '')
    [IO.File]::WriteAllLines($dlg.FileName, [string[]]($head + $Blob.Gui.SummaryText), (New-Object Text.UTF8Encoding($false)))
    Add-BlobGuiLog "{White}Saved the summary to {Gray}$($dlg.FileName)"
}

# ---------------------------------------------------------------------------
#  Install page (winget)
# ---------------------------------------------------------------------------
function Get-BlobGuiWingetInstalled {
    if ($null -eq $Blob.Gui.WingetText) { $Blob.Gui.WingetText = Get-BlobWingetListText }
    $found = Get-BlobWingetInstalledIds $Blob.Gui.WingetText
    foreach ($k in @($Blob.Gui.WingetAdded.Keys)) { $found[$k] = $true }
    return $found
}

function Update-BlobGuiInstallList {
    $P = $Blob.Gui.P
    if (-not $P -or -not $P.List) { return }
    $P.List.Children.Clear()
    $installed = Get-BlobGuiWingetInstalled
    $q = ([string]$Blob.Gui.InstSearch).Trim()
    $apps = @($Blob.WingetCatalog | Where-Object { -not $q -or $_.Name -like "*$q*" -or $_.Id -like "*$q*" -or $_.Cat -like "*$q*" })
    foreach ($cat in @($apps | ForEach-Object { $_.Cat } | Select-Object -Unique)) {
        $inCat = @($apps | Where-Object { $_.Cat -eq $cat })
        $n = @($inCat | Where-Object { $installed[$_.Id] }).Count
        [void]$P.List.Children.Add((New-BlobGroupHeader $cat "$n of $($inCat.Count) installed"))
        $wrap = [Windows.Controls.Primitives.UniformGrid]::new()
        $wrap.Columns = 2; $wrap.Margin = '0,4,0,0'
        foreach ($a in $inCat) {
            $row = [Windows.Controls.Border]::new()
            $row.BorderBrush = Get-BlobBrush 'Rule'; $row.BorderThickness = '0,0,0,1'; $row.Padding = '2,9'; $row.Margin = '0,0,24,0'
            $dock = [Windows.Controls.DockPanel]::new()
            $state = New-BlobText $(if ($installed[$a.Id]) { 'Installed' } else { '' }) 12 'Ink3' 'Normal' -Display
            $state.VerticalAlignment = 'Center'
            [Windows.Controls.DockPanel]::SetDock($state, 'Right'); [void]$dock.Children.Add($state)
            $cb = [Windows.Controls.CheckBox]::new()
            $content = New-BlobStack
            [void]$content.Children.Add((New-BlobText $a.Name 14 'Ink' 'SemiBold'))
            [void]$content.Children.Add((New-BlobText $a.Id 11.5 'Ink3' 'Normal' '0,1,0,0' -Mono))
            $cb.Content = $content
            $cb.Tag = $a.Id
            if ($installed[$a.Id]) { $cb.IsEnabled = $false } else { $cb.IsChecked = [bool]$Blob.Gui.InstSel[$a.Id] }
            $cb.Add_Checked({ param($s, $e) $Blob.Gui.InstSel[$s.Tag] = $true; Update-BlobGuiInstallButton })
            $cb.Add_Unchecked({ param($s, $e) $Blob.Gui.InstSel.Remove($s.Tag); Update-BlobGuiInstallButton })
            [void]$dock.Children.Add($cb)
            $row.Child = $dock
            [void]$wrap.Children.Add($row)
        }
        [void]$P.List.Children.Add($wrap)
    }
    Update-BlobGuiInstallButton
}

function Update-BlobGuiInstallButton {
    $n = $Blob.Gui.InstSel.Count
    if ($Blob.Gui.P -and $Blob.Gui.P.InstallBtn) { $Blob.Gui.P.InstallBtn.Content = $(if ($n) { "Install $n" } else { 'Install selected' }) }
}

function New-BlobGuiInstall {
    $P = @{}
    $Blob.Gui.P = $P
    if (-not $Blob.Gui.InstSel) { $Blob.Gui.InstSel = @{} }
    if (-not $Blob.Gui.WingetAdded) { $Blob.Gui.WingetAdded = @{} }
    $root = New-BlobStack
    if (-not (Test-BlobWinget)) {
        $s = New-BlobStack
        [void]$s.Children.Add((New-BlobText 'winget is not available on this PC' 18 'Ink' 'SemiBold' -Display))
        [void]$s.Children.Add((New-BlobText 'winget comes with "App Installer" from the Microsoft Store. Install or update it, then open this page again.' 13 'Ink2' 'Normal' '0,6,0,12'))
        $b = New-BlobButton 'Open App Installer in the Store' { Start-Process 'ms-windows-store://pdp/?productid=9NBLGGH4NNS1' -ErrorAction SilentlyContinue } 'Accent'
        $b.HorizontalAlignment = 'Left'
        [void]$s.Children.Add($b)
        [void]$root.Children.Add((New-BlobCard $s))
        return $root
    }
    $top = [Windows.Controls.DockPanel]::new()
    $sbox = [Windows.Controls.Grid]::new()
    $sbox.Width = 240; $sbox.HorizontalAlignment = 'Right'
    $search = [Windows.Controls.TextBox]::new()
    $search.Text = [string]$Blob.Gui.InstSearch; $search.Padding = '22,5,2,5'
    $hint = New-BlobText 'Search apps' 13.5 'Ink3' 'Normal' '23,6,0,0'
    $hint.IsHitTestVisible = $false
    if ($search.Text) { $hint.Visibility = 'Collapsed' }
    $glass = New-BlobGlyph 0xE721 'Ink2' 15
    $glass.Margin = '1,0,0,2'; $glass.HorizontalAlignment = 'Left'; $glass.IsHitTestVisible = $false
    [void]$sbox.Children.Add($search); [void]$sbox.Children.Add($hint); [void]$sbox.Children.Add($glass)
    $P.Hint = $hint
    $search.Add_TextChanged({ param($s, $e) $Blob.Gui.InstSearch = $s.Text; $Blob.Gui.P.Hint.Visibility = if ($s.Text) { 'Collapsed' } else { 'Visible' }; Update-BlobGuiInstallList })
    [Windows.Controls.DockPanel]::SetDock($sbox, 'Right')
    [void]$top.Children.Add($sbox)
    [void]$top.Children.Add((New-BlobText 'Tick the apps you want. They are installed one after another with winget, from the official winget repository. Remove them later on the Apps page.' 13 'Ink2' 'Normal' '0,4,24,0'))
    [void]$root.Children.Add($top)
    $P.List = New-BlobStack
    [void]$root.Children.Add($P.List)
    $P.InstallBtn = New-BlobButton 'Install selected' { Invoke-BlobGuiInstall } 'Accent' -Margin '0'
    Set-BlobGuiPageActions @(
        (New-BlobButton 'Update all apps' { Invoke-BlobGuiWingetUpgrade } -ToolTip 'Runs winget upgrade --all for every app winget knows how to update'),
        (New-BlobButton 'Refresh' { $Blob.Gui.WingetText = $null; $Blob.PrefetchValid = $false; Show-BlobGuiPage 'install' -Rebuild }),
        $P.InstallBtn)
    Update-BlobGuiInstallList
    return $root
}

function Invoke-BlobGuiInstall {
    $ids = @($Blob.Gui.InstSel.Keys)
    $apps = @($Blob.WingetCatalog | Where-Object { $_.Id -in $ids })
    if ($apps.Count -eq 0) { Show-BlobGuiMessage -Title 'Nothing selected' -Lines @('{Gray}Tick the apps you want to install first.'); return }
    $lines = @($apps | ForEach-Object { "{White}$($_.Name)  {DarkGray}$($_.Id)" })
    $lines += ''; $lines += '{Gray}Each app is downloaded by winget from its official source and installed with its own installer.'
    $lines += '{Gray}This can take a few minutes. The window stays usable; progress appears in the log.'
    if (-not (Show-BlobGuiDialog -Title "Install $($apps.Count) app(s)?" -Lines $lines -OkText 'Install')) { return }
    Start-BlobGuiTask "Installing $($apps.Count) app(s) with winget"
    $Blob.Gui.Collected = New-Object System.Collections.ArrayList
    $i = 0
    foreach ($a in $apps) {
        $i++
        Set-BlobGuiStatus "Installing $($a.Name) ($i of $($apps.Count))..."
        Install-BlobWingetApp -App $a -Log $Blob.GuiShared.LogCollect -Pump { Update-BlobGui; Start-Sleep -Milliseconds 150 }
        if (@($Blob.Gui.Collected | Where-Object { $_ -match "OK .*$([regex]::Escape($a.Name))" }).Count) { $Blob.Gui.WingetAdded[$a.Id] = $true; $Blob.Gui.InstSel.Remove($a.Id) }
    }
    Show-BlobGuiChangeSummary 'Installed apps'
    $Blob.PrefetchValid = $false
    if ($Blob.Gui.Cache.ContainsKey('apps')) { $Blob.Gui.Cache['apps'].Stale = $true }
    Update-BlobGuiPage
}

function Invoke-BlobGuiWingetUpgrade {
    if (-not (Show-BlobGuiDialog -Title 'Update all apps?' -OkText 'Update all' -Lines @(
                '{Gray}Runs winget upgrade --all: every app winget can update is updated with its own installer.',
                '{Gray}Apps that are open may need to be closed. This can take a while.'))) { return }
    Start-BlobGuiTask 'Updating apps with winget'
    $Blob.Gui.Collected = New-Object System.Collections.ArrayList
    Update-BlobWingetAll -Log $Blob.GuiShared.LogCollect -Pump { Update-BlobGui; Start-Sleep -Milliseconds 150 }
    Show-BlobGuiChangeSummary 'Updated apps'
}

# ---------------------------------------------------------------------------
#  Measure page
# ---------------------------------------------------------------------------
function New-BlobGuiMeasure {
    $P = @{}
    $Blob.Gui.P = $P
    $root = New-BlobStack
    $boots = @(Get-BlobBootTimes 12)
    $snaps = @(Get-BlobSnapshots)

    $row = [Windows.Controls.Grid]::new()
    $row.Margin = '0,4,0,30'
    for ($i = 0; $i -lt 4; $i++) { $cd = [Windows.Controls.ColumnDefinition]::new(); $cd.Width = '*'; $row.ColumnDefinitions.Add($cd) }
    $last = if ($boots.Count) { '{0:N1} s' -f ($boots[0].BootMs / 1000) } else { [string][char]0x2014 }
    $avg = if ($boots.Count -ge 2) { '{0:N1} s' -f (($boots | Select-Object -First 5 | Measure-Object BootMs -Average).Average / 1000) } else { [string][char]0x2014 }
    $os = $null; try { $os = Get-CimInstance Win32_OperatingSystem -ErrorAction Stop } catch { }
    $ram = if ($os) { Format-BlobSize ((([double]$os.TotalVisibleMemorySize - [double]$os.FreePhysicalMemory)) * 1KB) } else { [string][char]0x2014 }
    $cells = @(
        (New-BlobReadout 'Last boot' $last $(if ($boots.Count) { $boots[0].Date.ToString('yyyy-MM-dd HH:mm') } else { 'no boot records available' }) $true),
        (New-BlobReadout 'Average boot' $avg 'last 5 boots'),
        (New-BlobReadout 'Memory in use' $ram 'right now'),
        (New-BlobReadout 'Processes' "$(@(Get-Process).Count)" 'running right now'))
    for ($i = 0; $i -lt 4; $i++) { [Windows.Controls.Grid]::SetColumn($cells[$i], $i); [void]$row.Children.Add($cells[$i]) }
    [void]$root.Children.Add($row)

    [void]$root.Children.Add((New-BlobHeading 'Boot history' '0,0,0,8'))
    if ($boots.Count) {
        $rows = @($boots | ForEach-Object { [pscustomobject]@{ Date = $_.Date.ToString('yyyy-MM-dd HH:mm'); Boot = '{0:N1} s' -f ($_.BootMs / 1000); MainPath = '{0:N1} s' -f ($_.MainPathMs / 1000); AfterSignIn = '{0:N1} s' -f ($_.PostBootMs / 1000) } })
        $g = New-BlobGrid @(@{ Header = 'Boot'; Path = 'Date'; Width = 180 }, @{ Header = 'Total boot time'; Path = 'Boot'; Width = 160 }, @{ Header = 'Until desktop'; Path = 'MainPath'; Width = 160 }, @{ Header = 'Settling after sign-in'; Path = 'AfterSignIn'; Width = 1 }) ([Math]::Min(380, 40 + 32 * $rows.Count))
        $g.ItemsSource = $rows
        [void]$root.Children.Add($g)
        [void]$root.Children.Add((New-BlobText 'From Windows'' own boot performance log. "Until desktop" is the time to a usable desktop; "settling" is the work that continues after sign-in.' 12 'Ink3' 'Normal' '0,8,0,0'))
    } else {
        $why = if (-not $Blob.IsAdmin) { 'Reading the Windows boot performance log needs administrator rights. Start BLOB again and choose Yes in the permission prompt.' } else { 'Windows has not recorded any boots in its performance log yet. Restart the PC once and come back.' }
        [void]$root.Children.Add((New-BlobText $why 13 'Ink2'))
    }

    [void]$root.Children.Add((New-BlobHeading 'Snapshots' '0,30,0,8'))
    [void]$root.Children.Add((New-BlobText 'Take one before you apply a preset and one after a restart. For a fair comparison, wait two minutes after signing in. Differences under 5% are normal noise.' 13 'Ink2' 'Normal' '0,0,0,10'))
    if ($snaps.Count) {
        $g2 = New-BlobGrid @(@{ Header = 'Taken'; Path = 'Time'; Width = 140 }, @{ Header = 'Label'; Path = 'Label'; Width = 1 }, @{ Header = 'Boot s'; Path = 'BootSec'; Width = 80 }, @{ Header = 'RAM MB'; Path = 'RamUsedMB'; Width = 90 }, @{ Header = 'Processes'; Path = 'Processes'; Width = 90 }, @{ Header = 'Services'; Path = 'Services'; Width = 80 }, @{ Header = 'Startup'; Path = 'StartupApps'; Width = 76 }, @{ Header = 'Tweaks on'; Path = 'TweaksOn'; Width = 90 }) ([Math]::Min(300, 40 + 32 * $snaps.Count))
        $rev = @($snaps); [Array]::Reverse($rev)
        $g2.ItemsSource = $rev
        [void]$root.Children.Add($g2)
        if ($snaps.Count -ge 2) {
            [void]$root.Children.Add((New-BlobHeading "Compare: first '$($snaps[0].Label)' with latest '$($snaps[-1].Label)'" '0,24,0,8'))
            foreach ($l in (Compare-BlobSnapshots $snaps[0] $snaps[-1])) { [void]$root.Children.Add((ConvertTo-BlobTextBlock $l -Mono -Size 12.5)) }
        }
    } else { [void]$root.Children.Add((New-BlobText 'No snapshots yet.' 13 'Ink3')) }
    Set-BlobGuiPageActions @((New-BlobButton 'Take a snapshot' {
                $label = Show-BlobGuiInput -Title 'Name this snapshot' -Prompt @('{Gray}For example: Before Standard preset, After restart.') -Default $(if (@(Get-BlobSnapshots).Count) { 'After changes' } else { 'Before changes' }) -Validate { param($v) if (-not $v) { 'Enter a short name.' } }
                if (-not $label) { return }
                $s = New-BlobSnapshot $label
                Add-BlobGuiLog "{White}Snapshot '$label' taken {Gray}(RAM $($s.RamUsedMB) MB, $($s.Processes) processes, $($s.StartupApps) startup programs)"
                Update-BlobGuiPage } 'Accent' -Margin '0'))
    return $root
}

# ---------------------------------------------------------------------------
#  Search everything (Ctrl+K)
# ---------------------------------------------------------------------------
function Get-BlobSearchIndex {
    $idx = New-Object System.Collections.ArrayList
    foreach ($p in $Blob.Gui.Pages) { [void]$idx.Add(@{ Title = $p.Label; Where = 'Page'; Go = [scriptblock]::Create("Show-BlobGuiPage '$($p.Key)'") }) }
    foreach ($t in (Get-BlobCoreTweaks)) { [void]$idx.Add(@{ Title = $t.Name; Where = "Tweaks - $($t.Category)"; Text = $t.Description; Key = 'optimize'; Value = $t.Name }) }
    foreach ($t in (Get-BlobPrivacyItems)) { [void]$idx.Add(@{ Title = $t.Name + $(if ($t.Privacy.Oo) { " ($($t.Privacy.Oo))" }); Where = "Privacy - $($t.Group)"; Text = $t.Privacy.Does; Key = 'privacy'; Value = $t.Name }) }
    foreach ($a in @($Blob.Gui.AppsData)) { if ($a) { [void]$idx.Add(@{ Title = $a.Name; Where = 'Apps - installed'; Text = $a.Publisher; Key = 'apps'; Value = $a.Name }) } }
    foreach ($a in $Blob.WingetCatalog) { [void]$idx.Add(@{ Title = $a.Name; Where = "Install - $($a.Cat)"; Text = $a.Id; Key = 'install'; Value = $a.Name }) }
    return $idx.ToArray()
}

function Invoke-BlobSearchResult {
    param($R)
    if ($R.Go) { & $R.Go; return }
    switch ($R.Key) {
        'optimize' { $Blob.Gui.OptFilter = 'All'; $Blob.Gui.OptRisk = 'All'; $Blob.Gui.OptSearch = $R.Value }
        'privacy' { $Blob.Gui.PcSection = 'All sections'; $Blob.Gui.PcRec = 'All'; $Blob.Gui.PcSearch = $R.Value }
        'apps' { $Blob.Gui.AppsFilter = 'All'; $Blob.Gui.AppsSearch = $R.Value }
        'install' { $Blob.Gui.InstSearch = $R.Value }
    }
    Show-BlobGuiPage $R.Key -Rebuild
}

function Show-BlobGuiSearch {
    if ($Blob.Gui.Window.OwnedWindows.Count -gt 0) { return }
    $d = New-BlobGuiWindow $Blob.GuiDialogXaml
    $d.Owner = $Blob.Gui.Window
    $d.Height = 560
    $d.FindName('DlgTitle').Text = 'Search everything'
    $d.FindName('DlgSub').Text = 'Pages, tweaks, privacy settings (and O&O IDs), installed apps and apps to install. Enter opens, Esc closes.'
    $body = $d.FindName('DlgBody')
    $box = [Windows.Controls.TextBox]::new()
    $box.FontSize = 16; $box.Margin = '0,0,0,12'
    $list = [Windows.Controls.ListBox]::new()
    $list.MinHeight = 300
    [void]$body.Children.Add($box); [void]$body.Children.Add($list)
    $d.FindName('DlgOk').Content = 'Open'
    $d.FindName('DlgCancel').Content = 'Close'
    $d.Tag = @{ Index = (Get-BlobSearchIndex); Box = $box; List = $list; Result = $null }
    $box.Tag = $d; $list.Tag = $d
    $box.Add_TextChanged({
            param($s, $e)
            $st = $s.Tag.Tag
            $q = $s.Text.Trim()
            $st.List.Items.Clear()
            if ($q.Length -lt 2) { return }
            $hits = @($st.Index | Where-Object { $_.Title -like "*$q*" } | Select-Object -First 30)
            if ($hits.Count -lt 30) { $hits += @($st.Index | Where-Object { $_.Title -notlike "*$q*" -and $_.Text -like "*$q*" } | Select-Object -First (30 - $hits.Count)) }
            foreach ($h in $hits) {
                $item = [Windows.Controls.ListBoxItem]::new()
                $sp = New-BlobStack
                [void]$sp.Children.Add((New-BlobText $h.Title 14 'Ink' 'SemiBold'))
                [void]$sp.Children.Add((New-BlobText $h.Where 12 'Ink3' 'Normal' -Display))
                $item.Content = $sp; $item.Tag = $h; $item.Padding = '8,6'
                [void]$st.List.Items.Add($item)
            }
            if ($st.List.Items.Count) { $st.List.SelectedIndex = 0 }
        })
    $go = {
        param($s, $e)
        $w = [Windows.Window]::GetWindow($s)
        $st = $w.Tag
        if ($st.List.SelectedItem) { $st.Result = $st.List.SelectedItem.Tag; $w.Close() }
    }
    $d.FindName('DlgOk').Add_Click($go)
    $list.Add_MouseDoubleClick($go)
    $d.FindName('DlgCancel').Add_Click({ param($s, $e) [Windows.Window]::GetWindow($s).Close() })
    $d.Add_PreviewKeyDown({
            param($s, $e)
            $st = $s.Tag
            switch ($e.Key) {
                'Escape' { $s.Close(); $e.Handled = $true }
                'Down' { if ($st.List.Items.Count) { $st.List.SelectedIndex = [Math]::Min($st.List.Items.Count - 1, $st.List.SelectedIndex + 1); $st.List.ScrollIntoView($st.List.SelectedItem) }; $e.Handled = $true }
                'Up' { if ($st.List.Items.Count) { $st.List.SelectedIndex = [Math]::Max(0, $st.List.SelectedIndex - 1); $st.List.ScrollIntoView($st.List.SelectedItem) }; $e.Handled = $true }
                'Return' { if ($st.List.SelectedItem) { $st.Result = $st.List.SelectedItem.Tag; $s.Close() }; $e.Handled = $true }
            }
        })
    $d.Add_ContentRendered({ param($s, $e) $s.Tag.Box.Focus() })
    $null = $d.ShowDialog()
    if ($d.Tag.Result) { Invoke-BlobSearchResult $d.Tag.Result }
}
#endregion

#region ---- Main.ps1 ----
# ============================================================================
#  BLOB OPTIMIZER - Main.ps1
#  Entry point. Validates the host, initialises state, runs the UI and always
#  restores the console - even on errors or Ctrl+C.
# ============================================================================

function Invoke-BlobSelfTest {
    # Non-interactive smoke test: reads everything, changes nothing.
    # Usage: $env:BLOB_SELFTEST = '1'; .\BLOB.ps1
    $Blob.DryRun = $true
    $fail = 0
    $check = {
        param($name, $block)
        try { $r = & $block; Write-Host ("  [ OK ] {0} {1}" -f $name, $r) -ForegroundColor Cyan }
        catch { Write-Host ("  [FAIL] {0}: {1}" -f $name, $_.Exception.Message) -ForegroundColor Cyan; $Blob.SelfTestFailed = $true }
    }
    $Blob.SelfTestFailed = $false
    Write-Host "BLOB OPTIMIZER $($Blob.Version) self-test (read-only)" -ForegroundColor Cyan
    & $check 'System summary'  { $s = Get-BlobSystemSummary; "- $($s.OS)" }
    & $check 'Tweak catalogue' { $bad = @($Blob.Tweaks | Group-Object { $_.Id } | Where-Object { $_.Count -gt 1 }); if ($bad) { throw "duplicate ids: $($bad.Name -join ',')" }; "- $($Blob.Tweaks.Count) tweaks" }
    & $check 'Privacy catalogue' {
        $pc = @(Get-BlobPrivacyItems)
        $missing = @($Blob.PrivacyGroups | Where-Object { $g = $_; -not @($pc | Where-Object { $_.Group -eq $g }).Count })
        if ($missing) { throw "sections without items: $($missing -join ', ')" }
        foreach ($t in $pc) {
            foreach ($op in $t.Registry) { if ($op.Path -notmatch '^(HKCU|HKLM):\\') { throw "bad path in $($t.Id): $($op.Path)" } }
            foreach ($f in 'Does', 'Data', 'Benefit', 'Lose', 'Issues') { if (-not $t.Privacy[$f]) { throw "$($t.Id) has no '$f' text" } }
        }
        $noop = @($pc | Where-Object InfoOnly)
        if ($noop) { throw "settings without a switch: $(($noop | ForEach-Object Id) -join ', ')" }
        "- $($pc.Count) settings in $($Blob.PrivacyGroups.Count) sections, every one switchable"
    }
    & $check 'Drift check'     { "- $(@(Get-BlobDrift).Count) setting(s) changed back since BLOB set them" }
    & $check 'Install catalog' { $dup = @($Blob.WingetCatalog | Group-Object { $_.Id } | Where-Object Count -gt 1); if ($dup) { throw "duplicate ids: $($dup.Name -join ', ')" }; "- $($Blob.WingetCatalog.Count) apps, winget $(if (Test-BlobWinget) { 'available' } else { 'not available' })" }
    & $check 'Tweak states'    { $st = @($Blob.Tweaks | ForEach-Object { Get-BlobTweakState $_ }); "- $(@($st | Where-Object { $_ -eq 'Applied' }).Count) applied" }
    & $check 'Presets'         { $p = @(Get-BlobPresets); foreach ($x in $p) { foreach ($id in $x.Ids) { if (-not (Get-BlobTweak $id)) { throw "preset $($x.Name) references unknown tweak '$id'" } } }; "- $(($p | ForEach-Object { "$($_.Name)=$($_.Ids.Count)" }) -join ' ')" }
    & $check 'Preset safety'   { foreach ($x in @(Get-BlobPresets)) { foreach ($id in $x.Ids) { if ((Get-BlobTweak $id).Risk -eq 'Optional') { throw "optional tweak '$id' in preset $($x.Name)" } } }; '' }
    & $check 'Dry-run apply'   { $r = Set-BlobRegValue -Path 'HKCU:\Software\BLOB-OPTIMIZER-SelfTest' -Name 'Probe' -Value 1; if ($r.Status -ne 'DryRun') { throw "expected DryRun, got $($r.Status)" }; if (Test-Path 'HKCU:\Software\BLOB-OPTIMIZER-SelfTest') { throw 'dry run wrote to the registry' }; '' }
    & $check 'Startup entries' { "- $(@(Get-BlobStartupEntries).Count) entries" }
    & $check 'Power plans'     { "- active: $((Get-BlobActivePowerPlan).Name)" }
    & $check 'Services'        { "- $((Get-BlobServiceList).Count) services" }
    & $check 'Journal'         { "- $($Blob.Changes.Count) records at $($Blob.JournalPath)" }
    & $check 'Window UI'       {
        $why = Test-BlobGuiSupported
        if ($why) { return "- skipped: $why" }
        $null = New-BlobGuiWindow $Blob.GuiDialogXaml
        Initialize-BlobGuiWindow
        $built = 0
        foreach ($p in $Blob.Gui.Pages) {
            try { $c = & $p.Build; if (-not $c) { throw 'no content' }; $built++ }
            catch { throw "page '$($p.Key)': $($_.Exception.Message) $($_.InvocationInfo.PositionMessage)" }
        }
        $Blob.Gui.Window.Close()
        "- XAML ok, $built/$($Blob.Gui.Pages.Count) pages built"
    }
    & $check 'Cleanup scan'    { $t = $Blob.CleanupTargets[0]; $m = Measure-BlobCleanupTarget $t; "- $($t.Name): $(Format-BlobSize $m.Bytes)" }
    if ($Blob.SelfTestFailed) { Write-Host 'Self-test FAILED' -ForegroundColor Cyan } else { Write-Host 'Self-test passed' -ForegroundColor Cyan }
}

# Relaunches BLOB OPTIMIZER through the standard Windows administrator prompt (UAC).
# Returns 'Started', 'Declined' or 'NoSource'. Never bypasses the prompt.
function Request-BlobElevation {
    param([bool]$DryRun, [bool]$Tui, [string]$ScriptPath)
    $exe = try { (Get-Process -Id $PID).Path } catch { $null }
    if (-not $exe) { $exe = 'powershell.exe' }
    $extra = @()
    if ($DryRun) { $extra += '-DryRun' }
    if ($Tui) { $extra += '-Tui' }
    if ($ScriptPath -and (Test-Path -LiteralPath $ScriptPath)) {
        $argList = "-NoProfile -ExecutionPolicy Bypass -File `"$ScriptPath`" $($extra -join ' ')"
    } elseif ($Blob.ReleaseUrl) {
        # Started with irm | iex: run the same pinned release URL again, elevated.
        $argList = "-NoProfile -ExecutionPolicy Bypass -Command `"& ([scriptblock]::Create((irm '$($Blob.ReleaseUrl)'))) $($extra -join ' ')`""
    } else { return 'NoSource' }
    try {
        Start-Process -FilePath $exe -ArgumentList $argList -Verb RunAs -ErrorAction Stop
        Write-BlobLog "Relaunched elevated: $exe $argList"
        return 'Started'
    } catch { return 'Declined' }
}

function Start-BlobOptimizer {
    param([bool]$DryRun, [bool]$Tui, [bool]$NoElevate, [string]$ScriptPath)

    if ($PSVersionTable.PSVersion.Major -lt 5) { Write-Host 'BLOB OPTIMIZER requires PowerShell 5.1 or newer.' -ForegroundColor Cyan; return }
    if ($PSVersionTable.PSEdition -eq 'Core' -and -not $IsWindows) { Write-Host 'BLOB OPTIMIZER only runs on Windows.' -ForegroundColor Cyan; return }

    Initialize-BlobState -DryRun $DryRun
    $Blob.SysInfo = Get-BlobSystemSummary

    if ($env:BLOB_SELFTEST -eq '1') { Invoke-BlobSelfTest; return }

    # Always run as administrator: ask Windows (UAC) to relaunch elevated.
    if (-not $Blob.IsAdmin -and -not $NoElevate -and $env:BLOB_NOELEVATE -ne '1') {
        Write-Host '  BLOB OPTIMIZER needs administrator rights - Windows will ask for permission...' -ForegroundColor Cyan
        $elev = Request-BlobElevation -DryRun $Blob.DryRun -Tui $Tui -ScriptPath $ScriptPath
        if ($elev -eq 'Started') {
            Write-Host '  BLOB OPTIMIZER opened in a new administrator window. You can close this one.' -ForegroundColor Cyan
            return
        }
        if ($elev -eq 'Declined') { Write-Host '  Administrator permission was not given - continuing in read-only mode.' -ForegroundColor DarkCyan }
        else { Write-Host '  Could not relaunch automatically - continuing in read-only mode.' -ForegroundColor DarkCyan }
    }

    # Window interface (default). Falls back to the terminal UI when WPF is unavailable.
    if (-not $Tui -and $env:BLOB_TUI -ne '1') {
        $why = Test-BlobGuiSupported
        if (-not $why) {
            Write-Host ''
            Write-Host '  BLOB OPTIMIZER window is open.' -ForegroundColor Cyan -NoNewline
            Write-Host ' Close it to return to this prompt. (Terminal version: add -Tui)' -ForegroundColor DarkCyan
            $failure = $null
            try { Start-BlobGui } catch { $failure = $_ }
            if ($failure) {
                Write-BlobLog "Fatal (window): $($failure.Exception.Message) $($failure.InvocationInfo.PositionMessage)" 'ERROR'
                Write-Host 'BLOB OPTIMIZER window stopped because of an unexpected error:' -ForegroundColor Cyan
                Write-Host "  $($failure.Exception.Message)" -ForegroundColor Cyan
                Write-Host "  $($failure.InvocationInfo.PositionMessage)" -ForegroundColor DarkCyan
            }
            Write-BlobExitSummary
            return
        }
        Write-Host "  Window interface unavailable ($why) - starting the terminal interface." -ForegroundColor Cyan
    }

    if ($Host.Name -match 'ISE') { Write-Host 'Please run BLOB OPTIMIZER in Windows Terminal or a PowerShell console (the ISE has no interactive console).' -ForegroundColor Cyan; return }
    try { $null = [Console]::KeyAvailable; $null = [Console]::WindowWidth } catch {
        Write-Host 'BLOB OPTIMIZER needs an interactive console window (input is redirected).' -ForegroundColor Cyan; return
    }

    $failure = $null
    Initialize-BlobConsole
    try {
        Show-BlobDashboard
    } catch {
        if ($_.Exception.Message -ne 'BLOB_WINDOW_TOO_SMALL') { $failure = $_ }
    } finally {
        Restore-BlobConsole
    }

    if ($failure) {
        Write-BlobLog "Fatal: $($failure.Exception.Message) $($failure.InvocationInfo.PositionMessage)" 'ERROR'
        Write-Host 'BLOB OPTIMIZER stopped because of an unexpected error:' -ForegroundColor Cyan
        Write-Host "  $($failure.Exception.Message)" -ForegroundColor Cyan
        Write-Host "  $($failure.InvocationInfo.PositionMessage)" -ForegroundColor DarkCyan
    }
    Write-BlobExitSummary
}

function Write-BlobExitSummary {
    $session = @($Blob.Changes | Where-Object { $_.SessionId -eq $Blob.SessionId })
    Write-Host ''
    Write-Host '  BLOB OPTIMIZER closed.' -ForegroundColor Cyan -NoNewline
    Write-Host ' Nothing is left running.' -ForegroundColor DarkCyan
    if ($session.Count -gt 0) {
        Write-Host ("  {0} change(s) recorded this session. Undo them any time from Restore." -f $session.Count) -ForegroundColor DarkCyan
        Write-Host "  Backups and logs: $($Blob.DataRoot)" -ForegroundColor DarkCyan
    }
    Write-Host ''
}
#endregion

Start-BlobOptimizer -DryRun $BlobDryRun -Tui $BlobTui -NoElevate $BlobNoElevate -ScriptPath $BlobScriptPath
} ([bool]$DryRun) ([bool]$Tui) ([bool]$NoElevate) $PSCommandPath
